import React, { useState, useEffect } from 'react';
import { X, Plus, Trash2, Loader2 } from 'lucide-react';
import api from '../api';
import { useAuth } from '../context/AuthContext';
import { useToast } from '../context/ToastContext';

interface InventoryItem {
  id: string;
  name: string;
  unit: string;
  currentStock: number;
}

interface Ingredient {
  id: string;
  inventoryItemId: string;
  quantity: number;
  inventoryItem?: InventoryItem;
}

interface IngredientEditorProps {
  menuItemId: string;
  menuItemName: string;
  onClose: () => void;
}

const IngredientEditor: React.FC<IngredientEditorProps> = ({ menuItemId, menuItemName, onClose }) => {
  const { user } = useAuth();
  const { showToast } = useToast();
  const [inventory, setInventory] = useState<InventoryItem[]>([]);
  const [ingredients, setIngredients] = useState<Ingredient[]>([]);
  const [loading, setLoading] = useState(true);

  const [selectedInvId, setSelectedInvId] = useState('');
  const [quantity, setQuantity] = useState<number | ''>('');

  const fetchData = async () => {
    try {
      const [invRes, ingRes] = await Promise.all([
        api.get(`/tenants/${user?.tenantId}/inventory`),
        api.get(`/tenants/${user?.tenantId}/inventory/menu/${menuItemId}/ingredients`)
      ]);
      setInventory(invRes.data);
      setIngredients(ingRes.data);
    } catch (err) {
      console.error('Failed to fetch ingredient data', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, [menuItemId]);

  const handleAdd = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedInvId || !quantity) return;

    try {
      await api.post(`/tenants/${user?.tenantId}/inventory/menu/${menuItemId}/ingredients`, {
        inventoryItemId: selectedInvId,
        quantity: Number(quantity)
      });
      showToast('Ingredient added successfully', 'success');
      setSelectedInvId('');
      setQuantity('');
      fetchData();
    } catch (err) {
      console.error('Failed to add ingredient', err);
      showToast('Failed to link ingredient', 'error');
    }
  };

  const handleDelete = async (ingredientId: string) => {
    try {
      await api.delete(`/tenants/${user?.tenantId}/inventory/ingredients/${ingredientId}`);
      showToast('Ingredient removed', 'success');
      fetchData();
    } catch (err) {
      console.error('Failed to delete ingredient', err);
      showToast('Failed to remove ingredient', 'error');
    }
  };

  const filteredInventory = inventory.filter(i => 
    !ingredients.some(ing => ing.inventoryItemId === i.id)
  );

  return (
    <div style={{ position: 'fixed', inset: 0, zIndex: 110, display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'rgba(15, 23, 42, 0.4)', backdropFilter: 'blur(4px)', padding: '1rem', animation: 'fadeIn 0.2s ease-out' }}>
      <div style={{ background: 'var(--bg-elevated)', width: '100%', maxWidth: '42rem', padding: '2rem', borderRadius: '32px', boxShadow: '0 20px 60px -15px rgba(0,0,0,0.1)', border: '1px solid var(--border)', position: 'relative', overflow: 'hidden', animation: 'scaleIn 0.2s ease-out' }}>

        {/* Glow */}
        <div style={{ position: 'absolute', top: 0, left: '50%', transform: 'translateX(-50%)', width: '16rem', height: '16rem', background: 'var(--bg-base)', filter: 'blur(100px)', borderRadius: '50%', pointerEvents: 'none' }}></div>

        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', position: 'relative', zIndex: 10 }}>
          <div>
            <h3 style={{ fontSize: '1.5rem', fontWeight: 900, color: 'var(--text-primary)', marginBottom: '0.25rem' }}>Manage Ingredients</h3>
            <p style={{ color: 'var(--text-secondary)', fontWeight: 500, fontSize: '0.875rem' }}>For: <span style={{ color: 'var(--accent)', fontWeight: 900 }}>{menuItemName}</span></p>
          </div>
          <button onClick={onClose} style={{ padding: '0.5rem', borderRadius: '12px', background: 'transparent', color: 'var(--text-muted)', transition: 'all 0.2s', border: 'none', cursor: 'pointer' }} className="hover:bg-slate-100">
            <X size={24} />
          </button>
        </div>

        {loading ? (
          <div style={{ padding: '3rem 0', display: 'flex', justifyContent: 'center' }}><Loader2 className="animate-spin" style={{ color: 'var(--accent)' }} size={32} /></div>
        ) : (
          <div style={{ marginTop: '1.5rem', display: 'flex', flexDirection: 'column', gap: '1.5rem', position: 'relative', zIndex: 10 }}>

            {/* Current Ingredients List */}
            <div style={{ background: 'rgba(248, 249, 250, 0.5)', borderRadius: '16px', border: '1px solid var(--border)', padding: '1rem', display: 'flex', flexDirection: 'column', gap: '0.75rem', maxHeight: '16rem', overflowY: 'auto', boxShadow: 'inset 0 2px 4px rgba(0,0,0,0.02)' }} className="custom-scrollbar">
              <h4 style={{ fontSize: '0.75rem', fontWeight: 800, color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.1em', padding: '0 0.5rem' }}>Current Ingredients</h4>
              {ingredients.length === 0 ? (
                <p style={{ fontSize: '0.875rem', fontWeight: 500, color: 'var(--text-muted)', fontStyle: 'italic', padding: '1rem 0.5rem' }}>No ingredients linked. This item will not deduct stock.</p>
              ) : (
                <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
                  {ingredients.map(ing => (
                    <div key={ing.id} style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '0.75rem', background: 'var(--bg-elevated)', borderRadius: '12px', border: '1px solid var(--border)', boxShadow: 'var(--shadow-sm)', transition: 'all 0.2s' }}>
                      <div>
                        <p style={{ fontWeight: 900, fontSize: '0.875rem', color: 'var(--text-primary)' }}>{ing.inventoryItem?.name}</p>
                        <p style={{ fontSize: '0.75rem', fontWeight: 500, color: 'var(--text-secondary)', marginTop: '0.125rem' }}>Deducts: <span style={{ fontFamily: 'monospace', fontWeight: 800, color: 'var(--accent)' }}>{ing.quantity} {ing.inventoryItem?.unit}</span> per order</p>
                      </div>
                      <button 
                        onClick={() => handleDelete(ing.id)}
                        style={{ padding: '0.5rem', color: 'var(--text-muted)', background: 'transparent', borderRadius: '8px', transition: 'all 0.2s', border: 'none', cursor: 'pointer' }}
                        className="hover:text-red-500 hover:bg-red-50"
                        title="Remove Ingredient"
                      >
                        <Trash2 size={16} />
                      </button>
                    </div>
                  ))}
                </div>
              )}
            </div>

            {/* Add New Form */}
            <form onSubmit={handleAdd} style={{ background: 'var(--bg-base)', padding: '1.25rem', borderRadius: '16px', border: '1px solid var(--border)', display: 'flex', flexWrap: 'wrap', gap: '1rem', alignItems: 'flex-end', boxShadow: 'var(--shadow-sm)' }}>
              <div style={{ flex: 1, minWidth: '200px' }}>
                <label style={{ display: 'block', fontSize: '0.75rem', fontWeight: 800, color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: '0.5rem' }}>Select Item</label>
                <select 
                  className="form-input cursor-pointer"
                  value={selectedInvId}
                  onChange={e => setSelectedInvId(e.target.value)}
                  required
                >
                  <option value="">-- Choose Inventory Item --</option>
                  {filteredInventory.map(i => (
                    <option key={i.id} value={i.id}>{i.name} (In stock: {i.currentStock} {i.unit})</option>
                  ))}
                </select>
              </div>
              <div style={{ width: '8rem' }}>
                <label style={{ display: 'block', fontSize: '0.75rem', fontWeight: 800, color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: '0.5rem' }}>Qty</label>
                <input 
                  type="number" 
                  step="any"
                  min="0.01"
                  className="form-input"
                  style={{ fontFamily: 'monospace', fontWeight: 800 }}
                  placeholder="e.g. 1.5"
                  value={quantity}
                  onChange={e => setQuantity(e.target.value ? Number(e.target.value) : '')}
                  required
                />
              </div>
              <button 
                type="submit" 
                className="btn-primary"
                style={{ height: '3rem', padding: '0 1.5rem', display: 'flex', alignItems: 'center', gap: '0.5rem', borderRadius: '12px', fontWeight: 800, border: 'none', cursor: 'pointer' }}
                disabled={!selectedInvId || !quantity}
              >
                <Plus size={18} /> Add
              </button>
            </form>
          </div>
        )}

      </div>
    </div>
  );
};

export default IngredientEditor;

import React from 'react';

export interface OrderItem {
  name: string;
  quantity: number;
  price: number;
  subtotal: number;
  notes?: string;
}

export interface ReceiptData {
  hotelName: string;
  hotelAddress?: string;
  hotelPhone?: string;
  currency: string;
  receiptFooter?: string;
  orderNumber: string;
  cashierName: string;
  createdAt: string;
  tableRef?: string;
  roomNumber?: string;
  guestName?: string;
  items: OrderItem[];
  subtotal: number;
  taxAmount: number;
  taxRate: number;
  discount?: number;
  total: number;
  paymentMethod?: string;
  amountPaid?: number;
  change?: number;
  shiftId?: string;
}

export interface KOTData {
  hotelName: string;
  orderNumber: string;
  tableRef?: string;
  roomNumber?: string;
  cashierName: string;
  createdAt: string;
  items: { name: string; quantity: number; notes?: string }[];
}

// ─── GUEST RECEIPT / FOLIO ────────────────────────────────────────────────────
export const GuestReceiptTemplate: React.FC<{ data: ReceiptData }> = ({ data }) => {
  const lines = '-'.repeat(40);
  const fmt = (n: number) => `${data.currency} ${n.toFixed(2)}`;
  const pad = (left: string, right: string, total = 38) => {
    const spaces = Math.max(1, total - left.length - right.length);
    return left + ' '.repeat(spaces) + right;
  };

  return (
    <div style={{
      fontFamily: '"Courier New", Courier, monospace',
      fontSize: '12px',
      width: '302px', // 80mm = 302px at 96dpi
      margin: '0 auto',
      background: 'white',
      color: 'black',
      padding: '8px 12px',
      boxSizing: 'border-box',
      lineHeight: 1.5
    }}>
      {/* Header */}
      <div style={{ textAlign: 'center', marginBottom: '8px' }}>
        <div style={{ fontSize: '16px', fontWeight: 700, letterSpacing: '1px' }}>{data.hotelName}</div>
        {data.hotelAddress && <div>{data.hotelAddress}</div>}
        {data.hotelPhone && <div>Tel: {data.hotelPhone}</div>}
      </div>

      <div style={{ textAlign: 'center', fontSize: '10px', marginBottom: '4px' }}>OFFICIAL RECEIPT / TAX INVOICE</div>
      <pre style={{ margin: 0 }}>{lines}</pre>

      {/* Order Info */}
      <pre style={{ margin: 0, fontSize: '11px' }}>
        {pad('Receipt#:', `#${data.orderNumber}`)}
        {'\n'}{pad('Date:', new Date(data.createdAt).toLocaleDateString())}
        {'\n'}{pad('Time:', new Date(data.createdAt).toLocaleTimeString())}
        {'\n'}{pad('Cashier:', data.cashierName)}
        {data.tableRef ? `\n${pad('Table:', data.tableRef)}` : ''}
        {data.roomNumber ? `\n${pad('Room:', data.roomNumber)}` : ''}
        {data.guestName ? `\n${pad('Guest:', data.guestName)}` : ''}
      </pre>

      <pre style={{ margin: '4px 0' }}>{lines}</pre>

      {/* Items */}
      <pre style={{ margin: 0, fontSize: '11px' }}>
        {pad('ITEM', 'TOTAL')}
        {'\n'}{lines}
        {'\n'}
        {data.items.map(item => (
          `  ${item.quantity}x ${item.name}\n${pad('   @' + fmt(item.price) + ' each', fmt(item.subtotal))}${item.notes ? `\n   *** ${item.notes} ***` : ''}\n`
        )).join('')}
      </pre>

      <pre style={{ margin: '4px 0' }}>{lines}</pre>

      {/* Totals */}
      <pre style={{ margin: 0, fontSize: '11px' }}>
        {pad('Subtotal:', fmt(data.subtotal))}
        {'\n'}{pad(`Tax (${data.taxRate}%):`, fmt(data.taxAmount))}
        {data.discount && data.discount > 0 ? `\n${pad('Discount:', '-' + fmt(data.discount))}` : ''}
      </pre>

      <pre style={{ margin: '4px 0' }}>{lines}</pre>

      <pre style={{ margin: 0, fontSize: '14px', fontWeight: 800 }}>
        {pad('TOTAL:', fmt(data.total))}
      </pre>

      <pre style={{ margin: '4px 0', fontSize: '11px' }}>
        {data.paymentMethod ? pad('Payment:', data.paymentMethod.toUpperCase()) : ''}
        {data.amountPaid ? `\n${pad('Amount Paid:', fmt(data.amountPaid))}` : ''}
        {data.change !== undefined && data.change >= 0 ? `\n${pad('Change:', fmt(data.change))}` : ''}
      </pre>

      <pre style={{ margin: '4px 0' }}>{lines}</pre>

      {/* Footer */}
      <div style={{ textAlign: 'center', fontSize: '10px', marginTop: '8px' }}>
        <div>{data.receiptFooter || 'Thank you for your visit!'}</div>
        <div style={{ marginTop: '4px', opacity: 0.6 }}>Powered by ServePoint POS</div>
        {data.shiftId && <div style={{ opacity: 0.5 }}>Shift: {data.shiftId.slice(-8).toUpperCase()}</div>}
      </div>
    </div>
  );
};

// ─── KITCHEN ORDER TICKET (KOT / DOCKET) ─────────────────────────────────────
export const KitchenDocketTemplate: React.FC<{ data: KOTData }> = ({ data }) => {
  const lines = '='.repeat(32);

  return (
    <div style={{
      fontFamily: '"Courier New", Courier, monospace',
      fontSize: '14px',
      width: '302px',
      margin: '0 auto',
      background: 'white',
      color: 'black',
      padding: '8px 12px',
      boxSizing: 'border-box',
      lineHeight: 1.8
    }}>
      <div style={{ textAlign: 'center', marginBottom: '6px' }}>
        <div style={{ fontSize: '11px', letterSpacing: '2px' }}>{data.hotelName.toUpperCase()}</div>
        <div style={{ fontSize: '22px', fontWeight: 900, letterSpacing: '3px' }}>KITCHEN ORDER</div>
      </div>

      <pre style={{ margin: 0 }}>{lines}</pre>

      <pre style={{ margin: '4px 0', fontSize: '12px' }}>
        {`ORDER : #${data.orderNumber}`}
        {'\n'}{`TIME  : ${new Date(data.createdAt).toLocaleTimeString()}`}
        {'\n'}{`BY    : ${data.cashierName}`}
        {data.tableRef ? `\nTABLE : ${data.tableRef}` : ''}
        {data.roomNumber ? `\nROOM  : ${data.roomNumber}` : ''}
      </pre>

      <pre style={{ margin: '4px 0' }}>{lines}</pre>

      <pre style={{ margin: 0, fontSize: '16px', fontWeight: 800 }}>
        {data.items.map(item => (
          `[${item.quantity}x]  ${item.name.toUpperCase()}${item.notes ? `\n      >> ${item.notes}` : ''}\n`
        )).join('\n')}
      </pre>

      <pre style={{ margin: '4px 0' }}>{lines}</pre>
      <div style={{ textAlign: 'center', fontSize: '10px' }}>--- END OF ORDER ---</div>
    </div>
  );
};

// ─── PRINT TRIGGER FUNCTIONS ──────────────────────────────────────────────────
export const printReceipt = async (data: ReceiptData) => {
  const printWindow = window.open('', '_blank', 'width=360,height=700');
  if (!printWindow) return;

  const ReactDOMServer = await import('react-dom/server');
  const html = ReactDOMServer.renderToStaticMarkup(
    React.createElement(GuestReceiptTemplate, { data })
  );

  printWindow.document.write(`
    <!DOCTYPE html>
    <html>
    <head>
      <title>Receipt - ${data.orderNumber}</title>
      <style>
        body { margin: 0; padding: 0; background: white; }
        @media print {
          @page { margin: 0; size: 80mm auto; }
        }
      </style>
    </head>
    <body>${html}</body>
    </html>
  `);
  printWindow.document.close();
  printWindow.focus();
  setTimeout(() => { printWindow.print(); printWindow.close(); }, 500);
};

export const printKOT = async (data: KOTData) => {
  const printWindow = window.open('', '_blank', 'width=360,height=700');
  if (!printWindow) return;

  const ReactDOMServer = await import('react-dom/server');
  const html = ReactDOMServer.renderToStaticMarkup(
    React.createElement(KitchenDocketTemplate, { data })
  );

  printWindow.document.write(`
    <!DOCTYPE html>
    <html>
    <head>
      <title>KOT - ${data.orderNumber}</title>
      <style>
        body { margin: 0; padding: 0; background: white; }
        @media print {
          @page { margin: 0; size: 80mm auto; }
        }
      </style>
    </head>
    <body>${html}</body>
    </html>
  `);
  printWindow.document.close();
  printWindow.focus();
  setTimeout(() => { printWindow.print(); printWindow.close(); }, 500);
};

import React, { useState, useEffect } from 'react';
import { NavLink } from 'react-router-dom';
import { 
  LayoutDashboard, 
  ShoppingCart, 
  Bed, 
  ChefHat, 
  BarChart4, 
  Settings, 
  LogOut,
  Building2,
  Package,
  UtensilsCrossed,
  Users,
  MessageSquare,
  Receipt,
  LayoutGrid,
  Truck,
  Sparkles,
  ChevronRight,
  Banknote,
  X
} from 'lucide-react';
import { useAuth } from '../context/AuthContext';
import api from '../api';


interface NavItem {
  to: string;
  icon: React.ElementType;
  label: string;
  roles: string[];
  badge?: number;
}

interface SidebarProps {
  isOpen?: boolean;
  onClose?: () => void;
}

const Sidebar: React.FC<SidebarProps> = ({ isOpen, onClose }) => {
  const { user, tenant, logout } = useAuth();
  const [unreadCount, setUnreadCount] = useState(0);

  // Shift Management State
  const [activeShift, setActiveShift] = useState<any>(null);
  const [showCloseModal, setShowCloseModal] = useState(false);
  const [actualCash, setActualCash] = useState('');
  const [closeNotes, setCloseNotes] = useState('');
  const [isClosing, setIsClosing] = useState(false);

  // Dynamically calculate expected cash from live payments
  const expectedCashLive = activeShift ? 
    (activeShift.startingFloat || 0) + (activeShift.payments?.filter((p: any) => p.method === 'cash').reduce((sum: number, p: any) => sum + p.amount, 0) || 0) 
    : 0;

  useEffect(() => {
    if (showCloseModal && activeShift) {
      setActualCash(expectedCashLive.toFixed(2));
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [showCloseModal]);

  useEffect(() => {
    if (!user?.tenantId) return;
    const fetchUnread = async () => {
      try {
        const res = await api.get(`/tenants/${user.tenantId}/messages/unread-count`);
        setUnreadCount(res.data.count || 0);
      } catch {}
    };

    const fetchShift = async () => {
      try {
        const res = await api.get(`/tenants/${user.tenantId}/shifts/current`);
        setActiveShift(res.data);
      } catch {}
    };

    fetchUnread();
    fetchShift();

    const interval = setInterval(fetchUnread, 30000);
    const shiftInterval = setInterval(fetchShift, 30000);

    return () => {
      clearInterval(interval);
      clearInterval(shiftInterval);
    };
  }, [user?.tenantId]);

  const handleCloseShift = async () => {
    setIsClosing(true);
    try {
      await api.post(`/tenants/${user?.tenantId}/shifts/${activeShift.id}/close`, {
        actualCash: Number(actualCash),
        notes: closeNotes
      });
      setActiveShift(null);
      setShowCloseModal(false);
      setActualCash('');
      setCloseNotes('');
    } catch (err: any) {
      alert(err.response?.data?.error || 'Failed to close shift');
    } finally {
      setIsClosing(false);
    }
  };

  const mainItems: NavItem[] = [
    { to: '/', icon: LayoutDashboard, label: 'Dashboard', roles: ['super_admin', 'hotel_admin', 'cashier'] },
    { to: '/pos', icon: ShoppingCart, label: 'Food & Drinks', roles: ['hotel_admin', 'cashier'] },
    { to: '/messages', icon: MessageSquare, label: 'Messages', roles: ['hotel_admin', 'cashier'], badge: unreadCount > 0 ? unreadCount : undefined },
    { to: '/bills', icon: Receipt, label: 'Bills', roles: ['hotel_admin', 'cashier'] },
    { to: '/settings', icon: Settings, label: 'Settings', roles: ['hotel_admin'] },
  ];

  const advancedItems: NavItem[] = [
    { to: '/rooms', icon: Bed, label: 'Rooms', roles: ['hotel_admin', 'cashier'] },
    { to: '/menu', icon: ChefHat, label: 'Menu Mgmt', roles: ['hotel_admin'] },
    { to: '/inventory', icon: Package, label: 'Inventory', roles: ['hotel_admin'] },
    { to: '/kds', icon: UtensilsCrossed, label: 'Kitchen (KDS)', roles: ['hotel_admin', 'cashier'] },
    { to: '/floor-plan', icon: LayoutGrid, label: 'Floor Plan', roles: ['hotel_admin', 'cashier'] },
    { to: '/guests', icon: Users, label: 'Guests', roles: ['hotel_admin', 'cashier'] },
    { to: '/procurement', icon: Truck, label: 'Procurement', roles: ['hotel_admin'] },
    { to: '/reports', icon: BarChart4, label: 'Reports & Finances', roles: ['hotel_admin'] },
  ];

  if (user?.role === 'super_admin') {
    mainItems.push({ to: '/super-admin', icon: Building2, label: 'Tenants', roles: ['super_admin'] });
  }

  const filterItems = (items: NavItem[]) =>
    items.filter(i => i.roles.includes(user?.role || ''));

  const filteredMain = filterItems(mainItems);
  const filteredAdvanced = filterItems(advancedItems);

  return (
    <>
    <aside className={`sidebar ${isOpen ? 'open' : ''}`}>
      {/* Brand Logo */}
      <div className="sidebar-header" style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.875rem' }}>
          <div style={{ 
            width: '40px', height: '40px', borderRadius: '12px', 
            background: 'linear-gradient(135deg, #b8860b 0%, #8b6508 100%)',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            boxShadow: '0 4px 12px rgba(184,134,11,0.3)'
          }}>
            <Sparkles size={22} color="white" />
          </div>
          <h1 style={{ fontSize: '1.25rem', fontWeight: 800, letterSpacing: '-0.02em', color: 'white' }}>
            ServePoint
          </h1>
        </div>

        {/* Mobile Close Button */}
        <button 
          className="mobile-only"
          onClick={onClose}
          style={{ background: 'rgba(255,255,255,0.1)', border: 'none', color: 'white', padding: '8px', borderRadius: '10px', cursor: 'pointer' }}
        >
          <X size={20} />
        </button>
      </div>

      {/* Navigation */}
      <nav style={{ flex: 1, overflowY: 'auto', paddingRight: '4px' }}>
        {/* Main Menu */}
        {filteredMain.length > 0 && (
          <>
            <p className="sidebar-section-title">Main Menu</p>
            {filteredMain.map(item => (
              <NavLink
                key={item.to}
                to={item.to}
                end={item.to === '/'}
                className={({ isActive }) => `sidebar-link${isActive ? ' active' : ''}`}
              >
                <item.icon size={20} />
                <span>{item.label}</span>
                {item.badge && (
                  <span style={{ 
                    marginLeft: 'auto', background: '#b8860b', color: 'white', 
                    fontSize: '0.7rem', fontWeight: 800, padding: '2px 8px', borderRadius: '99px' 
                  }}>{item.badge}</span>
                )}
              </NavLink>
            ))}
          </>
        )}

        {/* Advanced Ops */}
        {filteredAdvanced.length > 0 && (
          <>
