          <div className="card" style={{ width: '100%', maxWidth: '32rem', padding: '2.5rem', animation: 'fadeUp 0.3s ease-out' }}>

            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.75rem' }}>
