import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Plus, Trash2, Pencil, Save, LayoutGrid, RefreshCw, Layers } from 'lucide-react';
import api from '../api';
import { useAuth } from '../context/AuthContext';
import { useToast } from '../context/ToastContext';

interface TableData {
  id: string;
  number: string;
  capacity: number;
  x: number;
  y: number;
  status: 'available' | 'occupied' | 'reserved';
  isActive: boolean;
}

const statusColors: Record<string, { bg: string; border: string; label: string; dot: string; glow: string }> = {
  available: { bg: '#ffffff', border: '#22c55e', label: '#22c55e', dot: '#22c55e', glow: 'rgba(34,197,94,0.15)' },
  occupied:  { bg: '#ffffff', border: '#ef4444', label: '#ef4444', dot: '#ef4444', glow: 'rgba(239,68,68,0.15)' },
  reserved:  { bg: '#ffffff', border: '#fbbf24', label: '#fbbf24', dot: '#fbbf24', glow: 'rgba(251,191,36,0.15)' },
};

const TABLE_W = 100;
const TABLE_H = 100;

const FloorPlan: React.FC = () => {
  const { user } = useAuth();
  const { showToast } = useToast();
  const canvasRef = useRef<HTMLDivElement>(null);

  const [tables, setTables] = useState<TableData[]>([]);
  const [loading, setLoading] = useState(true);
  const [editMode, setEditMode] = useState(false);
  const [selected, setSelected] = useState<string | null>(null);
  const [showAddModal, setShowAddModal] = useState(false);
  const [newTable, setNewTable] = useState({ number: '', capacity: 2 });
  const [dragging, setDragging] = useState<{ id: string; startX: number; startY: number; tableX: number; tableY: number } | null>(null);

  const fetchTables = useCallback(async () => {
    if (!user?.tenantId) return;
    try {
      const res = await api.get(`/tenants/${user.tenantId}/tables`);
      setTables(res.data);
    } catch (e) {
      showToast('Failed to load tables', 'error');
    } finally {
      setLoading(false);
    }
  }, [user?.tenantId]);

  useEffect(() => {
    fetchTables();
    const interval = setInterval(fetchTables, 15000);
    return () => clearInterval(interval);
  }, [fetchTables]);

  const handleMouseDown = (e: React.MouseEvent, id: string) => {
    if (!editMode) return;
    e.preventDefault();
    const table = tables.find(t => t.id === id);
    if (!table) return;
    setSelected(id);
    setDragging({ id, startX: e.clientX, startY: e.clientY, tableX: table.x, tableY: table.y });
  };

  const handleMouseMove = useCallback((e: MouseEvent) => {
    if (!dragging || !canvasRef.current) return;
    const dx = e.clientX - dragging.startX;
    const dy = e.clientY - dragging.startY;
    const rect = canvasRef.current.getBoundingClientRect();

    // Bounds check within flexible container
    const maxX = rect.width - TABLE_W;
    const maxY = rect.height - TABLE_H;

    const newX = Math.max(0, Math.min(maxX, dragging.tableX + dx));
    const newY = Math.max(0, Math.min(maxY, dragging.tableY + dy));

    setTables(prev => prev.map(t => t.id === dragging.id ? { ...t, x: newX, y: newY } : t));
  }, [dragging]);

  const handleMouseUp = useCallback(async () => {
    if (!dragging) return;
    const table = tables.find(t => t.id === dragging.id);
    if (table) {
      try {
        await api.patch(`/tenants/${user?.tenantId}/tables/${dragging.id}/coordinates`, { x: table.x, y: table.y });
      } catch { /* non-critical */ }
    }
    setDragging(null);
  }, [dragging, tables, user?.tenantId]);

  useEffect(() => {
    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [handleMouseMove, handleMouseUp]);

  const handleAddTable = async () => {
    if (!newTable.number.trim()) {
      showToast('Table number or name is required', 'error');
      return;
    }
    const safeX = Math.floor(Math.random() * 300) + 100;
    const safeY = Math.floor(Math.random() * 200) + 100;
    try {
      const res = await api.post(`/tenants/${user?.tenantId}/tables`, {
        number: newTable.number,
        capacity: newTable.capacity,
        x: safeX,
        y: safeY,
      });
      setTables(prev => [...prev, res.data]);
      setShowAddModal(false);
      setNewTable({ number: '', capacity: 2 });
      showToast(`Table ${newTable.number} added`, 'success');
    } catch {
      showToast('Failed to add table', 'error');
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Delete this table?')) return;
    try {
      await api.delete(`/tenants/${user?.tenantId}/tables/${id}`);
      setTables(prev => prev.filter(t => t.id !== id));
      if (selected === id) setSelected(null);
      showToast('Table deleted', 'success');
    } catch {
      showToast('Failed to delete table', 'error');
    }
  };

  const summary = { available: 0, occupied: 0, reserved: 0 };
  tables.forEach(t => { if (t.isActive) summary[t.status]++; });

  if (loading) return (
    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', height: '60vh', color: 'var(--text-secondary)' }}>
      <RefreshCw size={28} style={{ animation: 'spin 1s linear infinite', marginRight: 12, color: 'var(--accent)' }} />
      <span style={{ fontWeight: 600, fontSize: '1.1rem' }}>Loading Workspace...</span>
    </div>
  );

  return (
    <div style={{ padding: '0', height: 'calc(100vh - 2rem)', position: 'relative', overflow: 'hidden', display: 'flex', flexDirection: 'column' }}>

      {/* Title & Canvas Container merged for seamless edge-to-edge feel */}
      <div 
        ref={canvasRef}
        style={{
          flex: 1,
          position: 'relative',
          background: 'var(--bg-elevated)',
          backgroundImage: `
            linear-gradient(to right, rgba(0,0,0,0.03) 1px, transparent 1px),
            linear-gradient(to bottom, rgba(0,0,0,0.03) 1px, transparent 1px)
          `,
          backgroundSize: '40px 40px',
          boxShadow: 'inset 0 0 60px rgba(0,0,0,0.02)',
          overflow: 'hidden',
          borderRadius: '1.5rem',
          margin: '1rem',
          border: '1px solid var(--border)',
          cursor: editMode ? 'crosshair' : 'default',
        }}
        onClick={() => setSelected(null)}
      >

        {/* Floating Header Inside Canvas */}
        <div style={{ position: 'absolute', top: 0, left: 0, right: 0, padding: '1.5rem 2rem', pointerEvents: 'none', display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', zIndex: 10 }}>
          <div style={{ pointerEvents: 'auto' }}>
            <h1 style={{ fontSize: '1.5rem', fontWeight: 800, color: 'var(--text-primary)', display: 'flex', alignItems: 'center', gap: '0.625rem', letterSpacing: '-0.02em' }}>
              <Layers size={24} color="var(--accent)" /> Workspace
            </h1>
            <p style={{ fontSize: '0.85rem', color: 'var(--text-secondary)', marginTop: '0.25rem', fontWeight: 500 }}>
              Live interactive restaurant topology
            </p>
          </div>

          {/* Floating Glass Status Legend */}
          <div style={{ display: 'flex', gap: '0.75rem', pointerEvents: 'auto' }}>
            {Object.entries(summary).map(([status, count]) => {
              const c = statusColors[status];
              return (
                <div key={status} style={{ background: 'rgba(255,255,255,0.7)', backdropFilter: 'blur(12px)', border: '1px solid rgba(255,255,255,0.5)', borderRadius: '99px', padding: '0.4rem 1rem', display: 'flex', alignItems: 'center', gap: '0.5rem', boxShadow: '0 4px 15px rgba(0,0,0,0.04)' }}>
                  <span style={{ width: 8, height: 8, borderRadius: '50%', background: c.dot, display: 'inline-block', boxShadow: `0 0 8px ${c.dot}` }} />
                  <span style={{ fontSize: '0.75rem', fontWeight: 600, color: 'var(--text-secondary)', textTransform: 'uppercase', letterSpacing: '0.05em' }}>{status}</span>
                  <span style={{ fontSize: '0.9rem', fontWeight: 800, color: 'var(--text-primary)', marginLeft: '0.25rem' }}>{count}</span>
                </div>
              );
            })}
          </div>
        </div>

        {/* Tables */}
        {tables.filter(t => t.isActive).map(table => {
          const c = statusColors[table.status] || statusColors.available;
          const isSelected = selected === table.id;
          return (
            <div
              key={table.id}
              onMouseDown={e => { e.stopPropagation(); handleMouseDown(e, table.id); }}
              onClick={e => { e.stopPropagation(); setSelected(table.id); }}
              style={{
                position: 'absolute',
                left: table.x,
                top: table.y,
                width: TABLE_W,
                height: TABLE_H,
                background: c.bg,
                border: editMode ? '1px dashed #d1d5db' : `1px solid ${c.border}`,
                borderRadius: '50%',
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                justifyContent: 'center',
                cursor: editMode ? 'grab' : 'pointer',
                userSelect: 'none',
                transition: dragging?.id === table.id ? 'none' : 'all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1)',
                boxShadow: isSelected 
                  ? `0 0 0 3px #ffffff, 0 0 0 6px var(--accent), 0 20px 40px rgba(0,0,0,0.15)` 
                  : `0 10px 30px ${c.glow}, 0 4px 12px rgba(0,0,0,0.05)`,
                zIndex: dragging?.id === table.id ? 100 : (isSelected ? 50 : 1),
                transform: dragging?.id === table.id ? 'scale(1.05)' : 'scale(1)',
              }}
            >
              <div style={{ position: 'absolute', top: '-6px', right: '-6px', background: c.bg, borderRadius: '50%', padding: '0.2rem', boxShadow: '0 2px 8px rgba(0,0,0,0.1)' }}>
                <span style={{ width: 10, height: 10, borderRadius: '50%', background: c.dot, display: 'block' }} />
              </div>

              <span style={{ fontSize: '1.25rem', fontWeight: 800, color: 'var(--text-primary)', letterSpacing: '-0.03em' }}>T{table.number}</span>
              <span style={{ fontSize: '0.65rem', fontWeight: 600, color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.05em', marginTop: '0.25rem' }}>{table.capacity} PAX</span>

              {/* Delete button in edit mode + selected */}
              {editMode && isSelected && (
                <button
                  onClick={e => { e.stopPropagation(); handleDelete(table.id); }}
                  style={{
                    position: 'absolute',
                    bottom: -10,
                    width: 28, height: 28,
                    background: '#ef4444',
                    border: '2px solid white',
                    borderRadius: '50%',
                    display: 'flex', alignItems: 'center', justifyContent: 'center',
                    cursor: 'pointer', color: 'var(--text-inverted)',
                    boxShadow: '0 4px 12px rgba(239, 68, 68, 0.4)',
                    transition: 'transform 0.2s',
                  }}
                  onMouseEnter={e => e.currentTarget.style.transform = 'scale(1.1)'}
                  onMouseLeave={e => e.currentTarget.style.transform = 'scale(1)'}
                >
                  <Trash2 size={13} />
                </button>
              )}
            </div>
          );
        })}

        {/* Empty State */}
        {tables.length === 0 && (
          <div style={{ position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', flexDirection: 'column', gap: '1rem', color: 'var(--text-muted)', pointerEvents: 'none' }}>
            <div style={{ width: 100, height: 100, borderRadius: '50%', background: 'var(--input-bg)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
              <LayoutGrid size={40} style={{ opacity: 0.5 }} />
            </div>
            <p style={{ fontSize: '1rem', fontWeight: 500, letterSpacing: '-0.01em' }}>Empty blueprint. Enter edit mode to add tables.</p>
          </div>
        )}

        {/* Floating Control Dock */}
        <div style={{ 
          position: 'absolute', 
          bottom: '2.5rem', 
          left: '50%', 
          transform: 'translateX(-50%)',
          background: 'rgba(255, 255, 255, 0.85)',
          backdropFilter: 'blur(16px)',
          border: '1px solid var(--border)',
          borderRadius: '99px',
          padding: '0.5rem',
          display: 'flex',
          gap: '0.5rem',
          boxShadow: '0 20px 50px -10px rgba(0,0,0,0.1), 0 0 0 1px rgba(255,255,255,0.5) inset',
          zIndex: 200,
          pointerEvents: 'auto'
        }}>
          <button
            onClick={(e) => { e.stopPropagation(); setEditMode(!editMode); setSelected(null); }}
            style={{ 
              display: 'flex', alignItems: 'center', gap: '0.5rem', 
              padding: '0.625rem 1.25rem', 
              borderRadius: '99px',
              border: 'none',
              background: editMode ? 'var(--bg-inverted)' : 'transparent',
              color: editMode ? 'var(--text-inverted)' : 'var(--text-secondary)',
              fontSize: '0.85rem', fontWeight: 600,
              cursor: 'pointer',
              transition: 'all 0.2s',
            }}
          >
            <Pencil size={16} />
            {editMode ? 'Done Editing' : 'Edit Layout'}
          </button>

          <button
            onClick={(e) => { e.stopPropagation(); setShowAddModal(true); }}
            style={{ 
              display: 'flex', alignItems: 'center', gap: '0.5rem', 
              padding: '0.625rem 1.25rem', 
              borderRadius: '99px',
              border: 'none',
              background: 'var(--accent)',
              color: 'var(--text-inverted)',
              fontSize: '0.85rem', fontWeight: 600,
              cursor: 'pointer',
              boxShadow: '0 4px 15px var(--accent-glow)',
              transition: 'all 0.2s',
            }}
            onMouseEnter={e => e.currentTarget.style.transform = 'translateY(-2px)'}
            onMouseLeave={e => e.currentTarget.style.transform = 'translateY(0)'}
          >
            <Plus size={16} />
            Add Table
          </button>
        </div>

        {/* Edit Mode Overlay Indicator */}
        {editMode && (
          <div style={{
            position: 'absolute', top: 0, left: 0, right: 0, bottom: 0,
            boxShadow: 'inset 0 0 0 4px var(--accent)',
            pointerEvents: 'none',
            borderRadius: '1.5rem',
            zIndex: 15
          }} />
        )}

      </div>

      {/* Add Table Modal (Glassmorphic) */}
      {showAddModal && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.4)', backdropFilter: 'blur(8px)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 }}>
          <div style={{ background: 'var(--bg-elevated)', border: '1px solid rgba(255,255,255,0.5)', borderRadius: '1.25rem', padding: '2rem', width: '24rem', boxShadow: '0 25px 50px -12px rgba(0,0,0,0.25)' }}>
            <h2 style={{ fontSize: '1.25rem', fontWeight: 800, color: 'var(--text-primary)', marginBottom: '1.5rem', letterSpacing: '-0.02em' }}>Configure Table</h2>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>
              <div>
                <label style={{ fontSize: '0.75rem', fontWeight: 700, color: 'var(--text-secondary)', textTransform: 'uppercase', letterSpacing: '0.05em', display: 'block', marginBottom: '0.5rem' }}>Identifier</label>
                <input type="text" className="form-input" style={{ fontSize: '1rem', padding: '0.75rem 1rem' }} placeholder="e.g. 1" value={newTable.number} onChange={e => setNewTable(n => ({ ...n, number: e.target.value }))} autoFocus />
              </div>
              <div>
                <label style={{ fontSize: '0.75rem', fontWeight: 700, color: 'var(--text-secondary)', textTransform: 'uppercase', letterSpacing: '0.05em', display: 'block', marginBottom: '0.5rem' }}>Capacity (PAX)</label>
                <input type="number" className="form-input" style={{ fontSize: '1rem', padding: '0.75rem 1rem' }} min={1} max={20} value={newTable.capacity} onChange={e => setNewTable(n => ({ ...n, capacity: Number(e.target.value) }))} />
              </div>
            </div>
            <div style={{ display: 'flex', gap: '0.75rem', marginTop: '2rem' }}>
              <button onClick={() => setShowAddModal(false)} style={{ flex: 1, padding: '0.75rem', borderRadius: '0.75rem', border: '1px solid var(--border)', background: 'transparent', fontWeight: 700, color: 'var(--text-secondary)', cursor: 'pointer' }}>Cancel</button>
              <button onClick={handleAddTable} style={{ flex: 1, padding: '0.75rem', borderRadius: '0.75rem', border: 'none', background: 'var(--bg-inverted)', color: 'var(--text-inverted)', fontWeight: 700, cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.5rem' }}>
                <Save size={16} /> Deploy
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default FloorPlan;

/**
 * GuestMenu.tsx — Public guest-facing menu view.
 *
 * Accessible at /menu/:slug (no login required).
 * Guests can browse the menu and tap "Call Waiter" to send a message.
 */

import React, { useState, useEffect } from 'react';
import { useParams, useSearchParams } from 'react-router-dom';
import { Loader2, ChefHat, Bell } from 'lucide-react';

interface MenuItemPublic {
  id: string;
  name: string;
  description?: string;
  price: number;
  emoji: string;
  imageUrl?: string;
}

interface CategoryPublic {
  id: string;
  name: string;
  icon: string;
  menuItems: MenuItemPublic[];
}

interface TenantPublic {
  name: string;
  currency: string;
  logoUrl?: string;
  footer?: string;
}

const GuestMenu: React.FC = () => {
  const { slug } = useParams<{ slug: string }>();
  const [searchParams] = useSearchParams();
  const tableToken = searchParams.get('table');

  const [tenant, setTenant] = useState<TenantPublic | null>(null);
  const [categories, setCategories] = useState<CategoryPublic[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [activeCategory, setActiveCategory] = useState('');
  const [waiterCalled, setWaiterCalled] = useState(false);

  const API_BASE = (import.meta as any).env?.VITE_API_URL || window.location.origin;

  useEffect(() => {
    const fetchMenu = async () => {
      try {
        const res = await fetch(`${API_BASE}/api/menu/${slug}`);
        if (!res.ok) { setError('Menu not found.'); return; }
        const data = await res.json();
        setTenant(data.tenant);
        setCategories(data.categories);
        if (data.categories.length > 0) setActiveCategory(data.categories[0].id);
      } catch {
        setError('Failed to load menu. Please try again.');
      } finally {
        setLoading(false);
      }
    };
    fetchMenu();
  }, [slug]);

  const handleCallWaiter = async () => {
    if (!tableToken) { alert('No table QR detected. Please scan your table QR code.'); return; }
    setWaiterCalled(true);
    setTimeout(() => setWaiterCalled(false), 5000);
  };

  if (loading) {
    return (
      <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', minHeight: '100vh', background: '#f8fafc', gap: '1rem' }}>
        <Loader2 size={40} style={{ color: '#0f766e', animation: 'spin 1s linear infinite' }} />
        <p style={{ color: '#64748b', fontSize: '0.9rem' }}>Loading menu…</p>
      </div>
    );
  }

  if (error || !tenant) {
    return (
      <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', minHeight: '100vh', background: '#f8fafc', gap: '1rem', padding: '2rem', textAlign: 'center' }}>
        <ChefHat size={56} style={{ color: '#cbd5e1' }} />
        <h2 style={{ fontSize: '1.25rem', fontWeight: 700, color: '#1e293b' }}>Menu Not Found</h2>
        <p style={{ color: '#64748b' }}>{error || 'This menu is not available.'}</p>
      </div>
    );
  }

  const activeCat = categories.find(c => c.id === activeCategory);

  return (
    <div style={{ minHeight: '100vh', background: '#f8fafc', fontFamily: "'Outfit', 'Inter', sans-serif" }}>
      {/* Header */}
      <div style={{ background: 'linear-gradient(135deg, #0f766e 0%, #065f46 100%)', padding: '2rem 1.5rem 1.5rem', color: 'white', textAlign: 'center', position: 'sticky', top: 0, zIndex: 10 }}>
        {tenant.logoUrl && (
          <img src={tenant.logoUrl} alt={tenant.name} style={{ width: '60px', height: '60px', borderRadius: '16px', objectFit: 'cover', marginBottom: '0.75rem', border: '2px solid rgba(255,255,255,0.3)' }} />
        )}
        {!tenant.logoUrl && (
          <div style={{ width: '60px', height: '60px', borderRadius: '16px', background: 'rgba(255,255,255,0.2)', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 0.75rem', fontSize: '1.75rem' }}>
            🍽️
          </div>
        )}
        <h1 style={{ fontSize: '1.4rem', fontWeight: 800, margin: 0 }}>{tenant.name}</h1>
        <p style={{ fontSize: '0.8rem', opacity: 0.75, marginTop: '0.25rem' }}>Browse our menu</p>
      </div>

      {/* Category Tabs */}
      <div style={{ overflowX: 'auto', background: 'white', borderBottom: '1px solid #e2e8f0', position: 'sticky', top: '158px', zIndex: 9 }}>
        <div style={{ display: 'flex', padding: '0 1rem', gap: '0.25rem', minWidth: 'max-content' }}>
          {categories.map(cat => (
            <button
              key={cat.id}
              onClick={() => setActiveCategory(cat.id)}
              style={{
                padding: '0.875rem 1rem', border: 'none', cursor: 'pointer',
                background: 'transparent', fontFamily: 'inherit', fontWeight: 700,
                fontSize: '0.8rem', whiteSpace: 'nowrap', transition: 'all 0.2s',
                borderBottom: `3px solid ${activeCategory === cat.id ? '#0f766e' : 'transparent'}`,
                color: activeCategory === cat.id ? '#0f766e' : '#64748b',
              }}
            >
              {cat.icon} {cat.name}
            </button>
          ))}
        </div>
      </div>

      {/* Menu Items */}
      <div style={{ padding: '1.25rem', maxWidth: '640px', margin: '0 auto' }}>
        {activeCat && activeCat.menuItems.length > 0 ? (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '0.875rem' }}>
            {activeCat.menuItems.map(item => (
              <div key={item.id} style={{ background: 'white', borderRadius: '16px', padding: '1.125rem', display: 'flex', gap: '1rem', alignItems: 'center', boxShadow: '0 1px 3px rgba(0,0,0,0.06)', border: '1px solid #f1f5f9' }}>
                <div style={{ width: '52px', height: '52px', borderRadius: '12px', background: '#f0fdf4', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.75rem', flexShrink: 0 }}>
                  {item.emoji}
                </div>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <p style={{ fontWeight: 700, fontSize: '0.95rem', margin: 0, color: '#1e293b' }}>{item.name}</p>
                  {item.description && (
                    <p style={{ fontSize: '0.75rem', color: '#64748b', marginTop: '0.2rem', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{item.description}</p>
                  )}
                </div>
                <span style={{ fontWeight: 800, fontSize: '1rem', color: '#0f766e', flexShrink: 0 }}>
                  {tenant.currency} {item.price.toLocaleString()}
                </span>
              </div>
            ))}
          </div>
        ) : (
          <p style={{ textAlign: 'center', color: '#94a3b8', padding: '3rem 0' }}>No items in this category.</p>
        )}
      </div>

      {/* Footer */}
      {tenant.footer && (
        <p style={{ textAlign: 'center', padding: '1.5rem', fontSize: '0.75rem', color: '#94a3b8' }}>{tenant.footer}</p>
      )}

      {/* Call Waiter FAB */}
      {tableToken && (
        <button
          onClick={handleCallWaiter}
          style={{
            position: 'fixed', bottom: '1.5rem', right: '1.5rem',
            padding: '0.875rem 1.5rem', borderRadius: '99px', border: 'none',
            background: waiterCalled ? '#10b981' : '#0f766e',
            color: 'white', fontWeight: 800, fontSize: '0.875rem',
            cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '0.5rem',
            boxShadow: '0 4px 24px rgba(15,118,110,0.45)',
            transition: 'all 0.3s ease', fontFamily: 'inherit',
            transform: waiterCalled ? 'scale(1.05)' : 'scale(1)',
          }}
        >
          <Bell size={18} />
          {waiterCalled ? '✓ Waiter notified!' : 'Call Waiter'}
        </button>
      )}
    </div>
  );
};

export default GuestMenu;

import React, { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { 
  Loader2, Users, Search, Plus, Star, Mail, Phone, 
  History, Trash2, Edit2, X, Save
} from 'lucide-react';
import api from '../api';
import { useAuth } from '../context/AuthContext';
import { useToast } from '../context/ToastContext';

interface Guest {
  id: string;
  firstName: string;
  lastName: string;
  email: string | null;
  phone: string | null;
  loyaltyPoints: number;
}

const Guests: React.FC = () => {
  const { user } = useAuth();
  const { showToast } = useToast();
  const [guests, setGuests] = useState<Guest[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState<Partial<Guest>>({ firstName: '', lastName: '', email: '', phone: '' });

  const fetchGuests = async () => {
    try {
      const res = await api.get(`/tenants/${user?.tenantId}/guests`);
      setGuests(res.data);
    } catch (err) {
      console.error('Failed to fetch guests', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (user?.tenantId) fetchGuests();
  }, [user?.tenantId]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      if (formData.id) {
        await api.patch(`/tenants/${user?.tenantId}/guests/${formData.id}`, formData);
        showToast('Guest profile updated successfully', 'success');
      } else {
        await api.post(`/tenants/${user?.tenantId}/guests`, formData);
        showToast('Guest added to directory', 'success');
      }
      setIsModalOpen(false);
      fetchGuests();
    } catch (err) {
      console.error('Failed to save guest', err);
      showToast('Failed to save guest profile', 'error');
    }
  };

  const handleDelete = async (id: string, name: string) => {
    if (!window.confirm(`Are you sure you want to delete ${name}?`)) return;
    try {
      await api.delete(`/tenants/${user?.tenantId}/guests/${id}`);
      showToast('Guest removed from directory', 'success');
      fetchGuests();
    } catch (err) {
      console.error('Failed to delete guest', err);
      showToast('Failed to delete guest', 'error');
    }
  };

  const openEdit = (guest: Guest) => {
    setFormData(guest);
    setIsModalOpen(true);
  };

  const openAdd = () => {
    setFormData({ firstName: '', lastName: '', email: '', phone: '' });
    setIsModalOpen(true);
  };

  const filteredGuests = guests.filter(g => 
    `${g.firstName} ${g.lastName}`.toLowerCase().includes(searchQuery.toLowerCase()) || 
    (g.email && g.email.toLowerCase().includes(searchQuery.toLowerCase())) ||
    (g.phone && g.phone.includes(searchQuery))
  );

  if (loading) return (
    <div style={{ display: 'flex', height: '100%', alignItems: 'center', justifyContent: 'center', flexDirection: 'column', gap: '1rem' }}>
      <Loader2 className="animate-spin" size={32} color="var(--accent)" />
      <span style={{ fontSize: '0.9rem', color: 'var(--text-secondary)', fontWeight: 600 }}>Loading Directory...</span>
    </div>
  );

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '2rem', paddingBottom: '3rem', animation: 'fadeUp 0.4s ease-out' }}>

      {/* Header */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '1rem', borderBottom: '1px solid var(--border)', paddingBottom: '1.5rem' }}>
        <div>
          <h2 style={{ fontSize: '1.75rem', fontWeight: 800, color: 'var(--text-primary)', display: 'flex', gap: '0.75rem', alignItems: 'center', letterSpacing: '-0.02em' }}>
            <div style={{ padding: '0.5rem', background: 'var(--accent-soft)', borderRadius: '12px' }}><Users className="text-accent" size={26}/></div>
            Guest CRM
          </h2>
          <p style={{ color: 'var(--text-secondary)', marginTop: '0.5rem', fontWeight: 500, fontSize: '0.9rem' }}>Profiles, contact details, and loyalty rewards.</p>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
          <div style={{ position: 'relative', width: '300px' }}>
            <Search size={16} strokeWidth={3} style={{ position: 'absolute', left: '1.25rem', top: '50%', transform: 'translateY(-50%)', color: 'var(--text-muted)' }} />
            <input 
              type="text" 
              placeholder="Search by name, email, or phone..." 
              className="form-input"
              style={{ paddingLeft: '3rem', borderRadius: '99px', background: 'var(--bg-elevated)', border: 'none', boxShadow: 'var(--shadow-sm)', fontSize: '0.9rem', padding: '0.75rem 1rem 0.75rem 3rem' }}
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
          <button 
            className="btn btn-primary"
            style={{ borderRadius: '99px', padding: '0.75rem 1.5rem', display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.9rem', boxShadow: '0 8px 20px rgba(0,0,0,0.1)' }}
            onClick={openAdd}
          >
            <Plus size={18} /> New Guest
          </button>
        </div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: '1.5rem' }}>
        {filteredGuests.map((guest, i) => (
          <div key={guest.id} className="card" style={{ padding: '1.75rem', display: 'flex', flexDirection: 'column', position: 'relative', animationDelay: `${(i % 12) * 0.05}s` }}>

            <div style={{ position: 'absolute', top: '1.5rem', right: '1.5rem', display: 'flex', gap: '0.5rem' }}>
               <button onClick={() => openEdit(guest)} style={{ width: '2rem', height: '2rem', borderRadius: '8px', background: 'var(--bg-deep)', border: '1px solid var(--border)', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'var(--text-secondary)', transition: 'all 0.2s', cursor: 'pointer' }}><Edit2 size={14}/></button>
               <button onClick={() => handleDelete(guest.id, `${guest.firstName} ${guest.lastName}`)} style={{ width: '2rem', height: '2rem', borderRadius: '8px', background: 'var(--bg-deep)', border: '1px solid var(--border)', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#f43f5e', transition: 'all 0.2s', cursor: 'pointer' }}><Trash2 size={14}/></button>
            </div>

            <div style={{ width: '4rem', height: '4rem', borderRadius: '16px', background: 'var(--accent)', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'white', fontSize: '1.5rem', fontWeight: 800, marginBottom: '1.25rem', boxShadow: 'inset 0 4px 10px rgba(0,0,0,0.1)' }}>
              {guest.firstName[0]}{guest.lastName[0]}
            </div>

            <h3 style={{ fontSize: '1.25rem', fontWeight: 900, color: 'var(--text-primary)', marginBottom: '0.5rem', letterSpacing: '-0.01em' }}>{guest.firstName} {guest.lastName}</h3>

            <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem', marginTop: '0.5rem', flex: 1 }}>
              {guest.email && (
                <div style={{ display: 'flex', alignItems: 'center', gap: '0.625rem', fontSize: '0.85rem', fontWeight: 600, color: 'var(--text-secondary)' }}>
                  <Mail size={14} color="var(--text-muted)"/> {guest.email}
                </div>
              )}
              {guest.phone && (
                <div style={{ display: 'flex', alignItems: 'center', gap: '0.625rem', fontSize: '0.85rem', fontWeight: 600, color: 'var(--text-secondary)' }}>
                  <Phone size={14} color="var(--text-muted)"/> {guest.phone}
                </div>
              )}
            </div>

            <div style={{ marginTop: '1.5rem', paddingTop: '1.25rem', borderTop: '1px solid var(--border)', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '0.375rem', color: 'var(--accent)', background: 'var(--accent-soft)', padding: '0.3rem 0.75rem', borderRadius: '8px', border: '1px solid var(--accent-border)' }}>
                <Star size={14} style={{ fill: 'var(--accent)' }}/> 
                <span style={{ fontWeight: 800, fontSize: '0.8rem' }}>{guest.loyaltyPoints} pts</span>
              </div>
              <button style={{ display: 'flex', alignItems: 'center', gap: '0.375rem', fontSize: '0.75rem', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.05em', color: 'var(--text-secondary)', background: 'var(--bg-deep)', padding: '0.4rem 0.75rem', borderRadius: '8px', border: '1px solid var(--border)', cursor: 'pointer' }}>
                <History size={14}/> Folio
              </button>
            </div>

          </div>
        ))}
      </div>

      {filteredGuests.length === 0 && (
         <div className="card" style={{ padding: '4rem', textAlign: 'center', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '1rem' }}>
           <div style={{ width: 80, height: 80, borderRadius: '50%', background: 'var(--bg-deep)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
             <Users size={36} color="var(--text-muted)" />
           </div>
           <h3 style={{ fontSize: '1.25rem', fontWeight: 800, color: 'var(--text-primary)' }}>No Guest Profiles</h3>
           <p style={{ color: 'var(--text-secondary)', fontWeight: 500 }}>No guests match your current filters.</p>
         </div>
      )}

      {isModalOpen && createPortal(
        <div style={{ position: 'fixed', inset: 0, zIndex: 100, display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'rgba(0,0,0,0.6)', backdropFilter: 'blur(12px)' }}>
          <form onSubmit={handleSubmit} className="card" style={{ width: '100%', maxWidth: '28rem', padding: '2.5rem', animation: 'fadeUp 0.3s ease-out' }}>

            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.75rem' }}>
              <h3 style={{ fontSize: '1.35rem', fontWeight: 800, color: 'var(--text-primary)', letterSpacing: '-0.01em', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                <Users className="text-accent" size={24}/> {formData.id ? 'Edit Client Profile' : 'New Client Registration'}
              </h3>
              <button type="button" onClick={() => setIsModalOpen(false)} style={{ background: 'var(--bg-deep)', border: 'none', width: '2rem', height: '2rem', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'var(--text-secondary)', cursor: 'pointer' }}>
                <X size={16} />
              </button>
            </div>

            <div style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>
                <div>
                  <label style={{ fontSize: '0.75rem', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.05em', color: 'var(--text-secondary)', display: 'block', marginBottom: '0.5rem' }}>First Name *</label>
                  <input required type="text" value={formData.firstName || ''} onChange={e => setFormData({...formData, firstName: e.target.value})} className="form-input" placeholder="John" style={{ padding: '0.875rem' }} />
                </div>
                <div>
                  <label style={{ fontSize: '0.75rem', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.05em', color: 'var(--text-secondary)', display: 'block', marginBottom: '0.5rem' }}>Last Name *</label>
                  <input required type="text" value={formData.lastName || ''} onChange={e => setFormData({...formData, lastName: e.target.value})} className="form-input" placeholder="Doe" style={{ padding: '0.875rem' }} />
                </div>
              </div>

              <div>
                <label style={{ fontSize: '0.75rem', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.05em', color: 'var(--text-secondary)', display: 'block', marginBottom: '0.5rem' }}>Email Address</label>
                <input type="email" value={formData.email || ''} onChange={e => setFormData({...formData, email: e.target.value})} className="form-input" placeholder="john.doe@example.com" style={{ padding: '0.875rem' }} />
              </div>

              <div>
                <label style={{ fontSize: '0.75rem', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.05em', color: 'var(--text-secondary)', display: 'block', marginBottom: '0.5rem' }}>Mobile Number</label>
                <input type="tel" value={formData.phone || ''} onChange={e => setFormData({...formData, phone: e.target.value})} className="form-input" placeholder="+254 7XX XXX XXX" style={{ padding: '0.875rem' }} />
              </div>
            </div>

            <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '1rem', marginTop: '2rem', paddingTop: '1.5rem', borderTop: '1px solid var(--border)' }}>
              <button type="button" onClick={() => setIsModalOpen(false)} className="btn btn-secondary" style={{ flex: 1 }}>Discard</button>
              <button type="submit" className="btn btn-primary" style={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.5rem' }}><Save size={18}/> {formData.id ? 'Save Changes' : 'Register'}</button>
            </div>
          </form>
        </div>,
        document.body
      )}
    </div>
  );
};

export default Guests;

import React, { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { useToast } from '../context/ToastContext';
import { 
  Plus, Search, Trash2, Edit2, Loader2, Package, 
  ArrowDownUp, Save, X, AlertTriangle, CheckCircle
} from 'lucide-react';
import api from '../api';
import { useAuth } from '../context/AuthContext';

interface InventoryItem {
  id: string;
  name: string;
  sku: string | null;
  currentStock: number;
  lowStockThreshold: number;
  unit: string;
  costPrice: number;
}

const Inventory: React.FC = () => {
  const { user, tenant } = useAuth();
  const { showToast } = useToast();
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [isAdjustModalOpen, setIsAdjustModalOpen] = useState<{ isOpen: boolean, itemId: string | null }>({ isOpen: false, itemId: null });
  const [adjustData, setAdjustData] = useState({ type: 'IN', quantity: 0, notes: '' });

  const fetchData = async () => {
    try {
      const res = await api.get(`/tenants/${user?.tenantId}/inventory`);
      setItems(res.data);
    } catch (err) {
      console.error('Failed to fetch inventory', err);
      showToast('Failed to fetch inventory data', 'error');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (user?.tenantId) fetchData();
  }, [user?.tenantId]);

  const handleAdjustSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!isAdjustModalOpen.itemId) return;
    try {
      let finalQuantity = adjustData.quantity;
      if (adjustData.type === 'OUT' && finalQuantity > 0) finalQuantity = -finalQuantity;

      await api.post(`/tenants/${user?.tenantId}/inventory/${isAdjustModalOpen.itemId}/adjust`, {
         ...adjustData, quantity: finalQuantity
      });
      showToast('Stock adjusted successfully', 'success');
      setIsAdjustModalOpen({ isOpen: false, itemId: null });
      setAdjustData({ type: 'IN', quantity: 0, notes: '' });
      fetchData();
    } catch (err) {
      console.error('Adjustment failed', err);
      showToast('Failed to adjust stock', 'error');
    }
  };

  const handleDelete = async (id: string, name: string) => {
    if (!window.confirm(`Are you sure you want to delete ${name}?`)) return;
    try {
      await api.delete(`/tenants/${user?.tenantId}/inventory/${id}`);
      showToast('Inventory item deleted', 'success');
      fetchData();
    } catch (err) {
      console.error('Delete failed', err);
      showToast('Failed to delete item. It may be linked to a menu recipe.', 'error');
    }
  };

  const [isItemModalOpen, setIsItemModalOpen] = useState(false);
  const [itemFormData, setItemFormData] = useState<Partial<InventoryItem>>({});

  const handleItemSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      if (itemFormData.id) {
        await api.patch(`/tenants/${user?.tenantId}/inventory/${itemFormData.id}`, itemFormData);
        showToast('Inventory item updated', 'success');
      } else {
        await api.post(`/tenants/${user?.tenantId}/inventory`, itemFormData);
        showToast('Inventory item added', 'success');
      }
      setIsItemModalOpen(false);
      setItemFormData({});
      fetchData();
    } catch (err) {
      console.error('Save failed', err);
      showToast('Failed to save inventory item', 'error');
    }
  };

  const filteredItems = items.filter(item => 
    item.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
    (item.sku && item.sku.toLowerCase().includes(searchQuery.toLowerCase()))
  );

  if (loading) return (
    <div style={{ display: 'flex', height: '100%', alignItems: 'center', justifyContent: 'center', flexDirection: 'column', gap: '1rem' }}>
      <Loader2 className="animate-spin" size={32} color="var(--accent)" />
      <span style={{ fontSize: '0.9rem', color: 'var(--text-secondary)', fontWeight: 600 }}>Loading Stock Data...</span>
    </div>
  );

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '2rem', paddingBottom: '3rem', animation: 'fadeUp 0.4s ease-out' }}>

      {/* Header */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '1rem', borderBottom: '1px solid var(--border)', paddingBottom: '1.5rem' }}>
        <div>
          <h2 style={{ fontSize: '1.75rem', fontWeight: 800, color: 'var(--text-primary)', display: 'flex', gap: '0.75rem', alignItems: 'center', letterSpacing: '-0.02em' }}>
            <div style={{ padding: '0.5rem', background: 'var(--accent-soft)', borderRadius: '12px' }}><Package className="text-accent" size={26}/></div>
            Inventory Command
          </h2>
          <p style={{ color: 'var(--text-secondary)', marginTop: '0.5rem', fontWeight: 500, fontSize: '0.9rem' }}>Real-time stock tracking and auditing.</p>
        </div>

        <div className="responsive-stack" style={{ alignItems: 'center' }}>
          <div style={{ position: 'relative', width: '300px' }}>
            <Search size={16} strokeWidth={3} style={{ position: 'absolute', left: '1.25rem', top: '50%', transform: 'translateY(-50%)', color: 'var(--text-muted)' }} />
            <input 
              type="text" 
              placeholder="Search by name or SKU..." 
              className="form-input"
              style={{ paddingLeft: '3rem', borderRadius: '99px', background: 'var(--bg-elevated)', border: '1px solid var(--border)', boxShadow: 'var(--shadow-sm)', fontSize: '0.9rem', padding: '0.75rem 1rem 0.75rem 3rem' }}
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
          <button 
            className="btn btn-primary"
            style={{ borderRadius: '99px', padding: '0.75rem 1.5rem', display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.9rem', boxShadow: '0 8px 20px rgba(0,0,0,0.1)' }}
            onClick={() => { setItemFormData({}); setIsItemModalOpen(true); }}
          >
            <Plus size={18} /> New Item
          </button>
        </div>
      </div>

      {/* Data Table */}
      <div className="card" style={{ padding: 0, overflow: 'hidden' }}>
        <div style={{ overflowX: 'auto' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
            <thead>
              <tr style={{ background: 'var(--bg-deep)', borderBottom: '1px solid var(--border)' }}>
                <th style={{ padding: '1.25rem 1.5rem', fontSize: '0.75rem', fontWeight: 800, color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.05em' }}>Item Details</th>
                <th style={{ padding: '1.25rem 1.5rem', fontSize: '0.75rem', fontWeight: 800, color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.05em' }}>Identifiers</th>
                <th style={{ padding: '1.25rem 1.5rem', fontSize: '0.75rem', fontWeight: 800, color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.05em', textAlign: 'right' }}>Stock Level</th>
                <th style={{ padding: '1.25rem 1.5rem', fontSize: '0.75rem', fontWeight: 800, color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.05em', textAlign: 'right' }}>Unit Cost</th>
                <th style={{ padding: '1.25rem 1.5rem', fontSize: '0.75rem', fontWeight: 800, color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.05em', textAlign: 'center' }}>Health</th>
                <th style={{ padding: '1.25rem 1.5rem', fontSize: '0.75rem', fontWeight: 800, color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.05em', textAlign: 'right' }}>Actions</th>
              </tr>
            </thead>
            <tbody>
              {filteredItems.map((item, index) => {
                const isLowStock = item.currentStock <= item.lowStockThreshold;
                return (
                  <tr key={item.id} style={{ borderBottom: index === filteredItems.length - 1 ? 'none' : '1px solid var(--border)', transition: 'background-color 0.2s' }}>

                    <td style={{ padding: '1.25rem 1.5rem', display: 'flex', alignItems: 'center', gap: '1rem' }}>
                      <div style={{ width: '2.5rem', height: '2.5rem', borderRadius: '8px', background: 'var(--bg-deep)', display: 'flex', alignItems: 'center', justifyContent: 'center', border: '1px solid var(--border)', color: 'var(--text-secondary)' }}>
                        <Package size={18} />
                      </div>
                      <span style={{ fontWeight: 800, color: 'var(--text-primary)', fontSize: '0.95rem' }}>{item.name}</span>
                    </td>

                    <td style={{ padding: '1.25rem 1.5rem' }}>
                      <span style={{ padding: '0.2rem 0.6rem', borderRadius: '6px', background: 'var(--input-bg)', color: 'var(--text-secondary)', fontSize: '0.75rem', fontWeight: 700, fontFamily: 'monospace', letterSpacing: '0.05em', border: '1px solid var(--border)' }}>
                        {item.sku || 'NO-SKU'}
                      </span>
                    </td>

                    <td style={{ padding: '1.25rem 1.5rem', textAlign: 'right' }}>
                      <div style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'flex-end', gap: '0.25rem' }}>
                        <span style={{ fontSize: '1.1rem', fontWeight: 900, color: isLowStock ? '#ef4444' : 'var(--text-primary)', letterSpacing: '-0.02em' }}>{item.currentStock.toLocaleString()}</span>
                        <span style={{ fontSize: '0.75rem', fontWeight: 700, color: 'var(--text-muted)', textTransform: 'lowercase' }}>{item.unit}</span>
                      </div>
                    </td>

                    <td style={{ padding: '1.25rem 1.5rem', textAlign: 'right', fontWeight: 800, color: 'var(--text-secondary)', fontSize: '0.9rem' }}>
                      {tenant?.currency} {Number(item.costPrice).toLocaleString()}
                    </td>

                    <td style={{ padding: '1.25rem 1.5rem', textAlign: 'center' }}>
                      {isLowStock ? (
                        <span style={{ display: 'inline-flex', alignItems: 'center', gap: '0.375rem', padding: '0.3rem 0.75rem', borderRadius: '99px', background: 'rgba(239,68,68,0.1)', color: '#ef4444', border: '1px solid rgba(239,68,68,0.2)', fontSize: '0.7rem', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.05em' }}>
                          <AlertTriangle size={12}/> Low
                        </span>
                      ) : (
                        <span style={{ display: 'inline-flex', alignItems: 'center', gap: '0.375rem', padding: '0.3rem 0.75rem', borderRadius: '99px', background: 'rgba(34,197,94,0.1)', color: '#10b981', border: '1px solid rgba(34,197,94,0.2)', fontSize: '0.7rem', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.05em' }}>
                          <CheckCircle size={12}/> Optimal
                        </span>
                      )}
                    </td>

                    <td style={{ padding: '1.25rem 1.5rem', textAlign: 'right' }}>
                      <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '0.5rem' }}>
                        <button 
                          aria-label={`Adjust Stock for ${item.name}`}
                          onClick={() => setIsAdjustModalOpen({ isOpen: true, itemId: item.id })}
                          style={{ display: 'flex', alignItems: 'center', gap: '0.375rem', padding: '0.4rem 0.75rem', background: 'var(--accent-soft)', color: 'var(--accent)', border: 'none', borderRadius: '8px', fontSize: '0.75rem', fontWeight: 800, cursor: 'pointer', transition: 'all 0.2s' }}
                        >
                          <ArrowDownUp size={14} /> Adjust
                        </button>
                        <button
                          aria-label={`Edit ${item.name}`}
                          onClick={() => { setItemFormData(item); setIsItemModalOpen(true); }}
                          style={{ width: '2.25rem', height: '2.25rem', borderRadius: '8px', background: 'var(--bg-deep)', border: '1px solid var(--border)', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'var(--text-secondary)', cursor: 'pointer', transition: 'all 0.2s' }}
                        >
                          <Edit2 size={14} />
                        </button>
                        <button
                          aria-label={`Delete ${item.name}`}
                          onClick={() => handleDelete(item.id, item.name)}
                          style={{ width: '2.25rem', height: '2.25rem', borderRadius: '8px', background: 'var(--bg-deep)', border: '1px solid var(--border)', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#f43f5e', cursor: 'pointer', transition: 'all 0.2s' }}
                        >
                          <Trash2 size={14} />
                        </button>
                      </div>
                    </td>
                  </tr>
                );
              })}
              {filteredItems.length === 0 && (
                 <tr>
                   <td colSpan={6} style={{ padding: '4rem', textAlign: 'center', color: 'var(--text-muted)' }}>
                      <Package size={48} style={{ margin: '0 auto 1rem', opacity: 0.3 }} />
                      <p style={{ fontSize: '1.1rem', fontWeight: 700 }}>No inventory items located.</p>
                      <p style={{ fontSize: '0.85rem' }}>Adjust your exact search criteria.</p>
                   </td>
                 </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Adjust Stock Modal */}
      {isAdjustModalOpen.isOpen && createPortal(
        <div style={{ position: 'fixed', inset: 0, zIndex: 100, display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'rgba(0,0,0,0.6)', backdropFilter: 'blur(12px)' }}>
          <form onSubmit={handleAdjustSubmit} className="card" style={{ width: '100%', maxWidth: '28rem', padding: '2.5rem', animation: 'fadeUp 0.3s ease-out' }}>

             <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.75rem' }}>
                <h3 style={{ fontSize: '1.35rem', fontWeight: 800, color: 'var(--text-primary)', display: 'flex', alignItems: 'center', gap: '0.625rem', letterSpacing: '-0.01em' }}>
                  <div style={{ background: 'var(--accent-soft)', padding: '0.5rem', borderRadius: '10px' }}><ArrowDownUp size={20} color="var(--accent)"/></div>
                  Adjust Stock Level
                </h3>
                <button type="button" onClick={() => setIsAdjustModalOpen({ isOpen: false, itemId: null })} style={{ background: 'var(--bg-deep)', border: 'none', width: '2rem', height: '2rem', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'var(--text-secondary)', cursor: 'pointer' }}><X size={16} /></button>
             </div>

             <div style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>
                <div>
                  <label style={{ fontSize: '0.75rem', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.05em', color: 'var(--text-secondary)', display: 'block', marginBottom: '0.5rem' }}>Adjustment Directive</label>
                  <select 
                    value={adjustData.type}
                    onChange={e => setAdjustData({...adjustData, type: e.target.value})}
                    className="form-input"
                    style={{ padding: '1rem', fontSize: '0.9rem', fontWeight: 700 }}
                  >
                    <option value="IN">Receive Inventory (+)</option>
                    <option value="OUT">Deduct Inventory (-)</option>
                    <option value="ADJUSTMENT">Manual Override / Audit</option>
                  </select>
                </div>

                <div>
                  <label style={{ fontSize: '0.75rem', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.05em', color: 'var(--text-secondary)', display: 'block', marginBottom: '0.5rem' }}>Quantity Delta</label>
                  <input 
                    type="number" required min={adjustData.type !== 'ADJUSTMENT' ? 1 : undefined}
                    value={adjustData.quantity || ''}
                    onChange={e => setAdjustData({...adjustData, quantity: Number(e.target.value)})}
                    className="form-input"
                    placeholder="0"
                    style={{ padding: '1rem', fontSize: '1.5rem', fontWeight: 900, fontFamily: 'monospace' }}
                  />
                  <span style={{ fontSize: '0.7rem', fontWeight: 600, color: 'var(--text-muted)' }}>
                    {adjustData.type === 'ADJUSTMENT' ? 'Provide negative values to decrease.' : `Units to ${adjustData.type === 'OUT' ? 'deduct from' : 'add to'} current stock.`}
                  </span>
                </div>

                <div>
                  <label style={{ fontSize: '0.75rem', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.05em', color: 'var(--text-secondary)', display: 'block', marginBottom: '0.5rem' }}>Audit Notes (Optional)</label>
                  <input 
                    type="text" value={adjustData.notes} onChange={e => setAdjustData({...adjustData, notes: e.target.value})}
                    className="form-input" placeholder="Reason for adjustment..." style={{ padding: '0.875rem' }}
                  />
                </div>
             </div>

             <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '1rem', marginTop: '2rem' }}>
                <button type="button" onClick={() => setIsAdjustModalOpen({ isOpen: false, itemId: null })} className="btn btn-secondary">Discard</button>
                <button type="submit" className="btn btn-primary" style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}><Save size={18} /> Confirm Change</button>
             </div>
          </form>
        </div>,
        document.body
      )}

      {/* Item Modal (Create/Edit) */}
      {isItemModalOpen && createPortal(
