      {/* Search & Add Row */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem', '@media (min-width: 640px)': { flexDirection: 'row' } } as any}>
        <div style={{ position: 'relative', flex: 1 }}>
