                  <div style={{ display: 'flex', gap: '0.25rem' }}>
                    <button
                      onClick={() => openEdit(cat)}
                      style={{ padding: '0.5rem', background: 'transparent', color: 'var(--text-secondary)', borderRadius: '8px', transition: 'all 0.2s', border: 'none', cursor: 'pointer' }}
                    >
                      <Edit2 size={14} />
                    </button>
                    <button
                      onClick={() => handleDeleteCategory(cat.id, cat._count.menuItems)}
                      style={{ padding: '0.5rem', background: 'transparent', color: 'var(--text-secondary)', borderRadius: '8px', transition: 'all 0.2s', border: 'none', cursor: 'pointer' }}
                      title={cat._count.menuItems > 0 ? "Cannot delete category with items" : "Delete category"}
                    >
                      <Trash2 size={14} />
                    </button>
                  </div>
                </div>
                <div style={{ marginTop: '1rem' }}>
                  <h4 style={{ fontWeight: 900, color: 'var(--text-primary)', fontSize: '1.1rem' }}>{cat.name}</h4>
                  <p style={{ fontSize: '0.75rem', fontWeight: 800, color: 'var(--text-muted)', marginTop: '0.25rem', textTransform: 'uppercase', letterSpacing: '0.05em' }}>{cat._count.menuItems} Items</p>
                </div>
              </div>
            ))}
            {categories.length === 0 && (
               <div style={{ gridColumn: '1 / -1', padding: '3rem', textAlign: 'center', color: 'var(--text-muted)', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center' }}>
                  <LayoutGrid size={48} style={{ marginBottom: '1rem', opacity: 0.5 }}/>
                  <p>No categories created yet.</p>
               </div>
            )}
          </div>
        )}
      </div>

      {/* Add/Edit Modal */}
      {isModalOpen && createPortal(
        <div style={{ position: 'fixed', inset: 0, zIndex: 100, display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'rgba(15, 23, 42, 0.4)', backdropFilter: 'blur(4px)', padding: '1rem', animation: 'fadeIn 0.2s ease-out' }}>
          <form
            onSubmit={handleSubmit}
            style={{ width: '100%', maxWidth: '32rem', background: 'var(--bg-elevated)', borderRadius: '32px', padding: '2rem', boxShadow: '0 20px 60px -15px rgba(0,0,0,0.1)', border: '1px solid var(--border)', position: 'relative', animation: 'scaleIn 0.2s ease-out' }}
          >
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.5rem' }}>
              <h3 style={{ fontSize: '1.5rem', fontWeight: 900, color: 'var(--text-primary)', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                {formData.id ? 'Edit' : 'Add New'} {activeTab === 'items' ? 'Menu Item' : 'Category'}
              </h3>
              <button
                type="button"
                onClick={() => setIsModalOpen(false)}
                style={{ width: '2.5rem', height: '2.5rem', display: 'flex', alignItems: 'center', justifyContent: 'center', borderRadius: '50%', background: 'var(--bg-elevated)', color: 'var(--text-muted)', border: 'none', transition: 'all 0.2s', cursor: 'pointer' }}
                className="hover:bg-slate-200"
              >
                <X size={18} />
              </button>
            </div>

            <div style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem', maxHeight: '60vh', overflowY: 'auto', paddingRight: '0.5rem' }} className="custom-scrollbar">
              {activeTab === 'items' ? (
                <>
                  <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>
                    <div>
                      <label style={{ display: 'block', fontSize: '0.75rem', fontWeight: 800, color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: '0.5rem' }}>Item Name</label>
                      <input required type="text" value={formData.name || ''} onChange={e => setFormData({...formData, name: e.target.value})} className="form-input" placeholder="Classic Burger" />
                    </div>
                    <div>
                      <label style={{ display: 'block', fontSize: '0.75rem', fontWeight: 800, color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: '0.5rem' }}>Price ({tenant?.currency})</label>
                      <input required type="number" step="0.01" value={formData.price || ''} onChange={e => setFormData({...formData, price: e.target.value})} className="form-input" style={{ fontFamily: 'monospace', fontWeight: 800 }} placeholder="10.00" />
                    </div>
                  </div>
                  <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>
                    <div>
                      <label style={{ display: 'block', fontSize: '0.75rem', fontWeight: 800, color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: '0.5rem' }}>Category</label>
                      <select required value={formData.categoryId || ''} onChange={e => setFormData({...formData, categoryId: e.target.value})} className="input-field cursor-pointer">
                        <option value="" disabled>Select Category</option>
                        {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                      </select>
                    </div>
                    <div>
                      <label style={{ display: 'block', fontSize: '0.75rem', fontWeight: 800, color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: '0.5rem' }}>Emoji Icon</label>
                      <input required type="text" value={formData.emoji || ''} onChange={e => setFormData({...formData, emoji: e.target.value})} className="form-input" style={{ fontSize: '1.25rem' }} placeholder="🍔" />
                    </div>
                  </div>
                  <div>
                    <label style={{ display: 'block', fontSize: '0.75rem', fontWeight: 800, color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: '0.5rem' }}>Description</label>
                    <input type="text" value={formData.description || ''} onChange={e => setFormData({...formData, description: e.target.value})} className="form-input" placeholder="Delicious beef patty with cheese..." />
                  </div>
                  <label style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', padding: '1rem', background: 'var(--bg-elevated)', borderRadius: '16px', border: '1px solid var(--border)', cursor: 'pointer', transition: 'background 0.2s' }} className="hover:bg-slate-100">
                    <input
                      type="checkbox"
                      checked={formData.isAvailable ?? true}
                      onChange={e => setFormData({...formData, isAvailable: e.target.checked})}
                      style={{ width: '1.25rem', height: '1.25rem', accentColor: 'var(--accent)' }}
                    />
                    <span style={{ fontSize: '0.9rem', fontWeight: 800, color: 'var(--text-primary)' }}>Item is currently available for ordering</span>
                  </label>
                </>
              ) : (
                <>
                  <div>
                    <label style={{ display: 'block', fontSize: '0.75rem', fontWeight: 800, color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: '0.5rem' }}>Category Name</label>
                    <input required type="text" value={formData.name || ''} onChange={e => setFormData({...formData, name: e.target.value})} className="form-input" placeholder="Beverages" />
                  </div>
                  <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>
                     <div>
                       <label style={{ display: 'block', fontSize: '0.75rem', fontWeight: 800, color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: '0.5rem' }}>Emoji Icon</label>
                       <input required type="text" value={formData.icon || ''} onChange={e => setFormData({...formData, icon: e.target.value})} className="form-input" style={{ fontSize: '1.25rem' }} placeholder="🥤" />
                     </div>
                     <div>
                       <label style={{ display: 'block', fontSize: '0.75rem', fontWeight: 800, color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: '0.5rem' }}>Sort Display Order</label>
                       <input required type="number" value={formData.sortOrder ?? 0} onChange={e => setFormData({...formData, sortOrder: Number(e.target.value)})} className="form-input" style={{ fontFamily: 'monospace', fontWeight: 800 }} placeholder="0" />
                     </div>
                  </div>
                </>
              )}
            </div>

            <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '0.75rem', marginTop: '2rem', paddingTop: '1.5rem', borderTop: '1px solid var(--border)' }}>
              <button
                type="button"
                onClick={() => setIsModalOpen(false)}
                style={{ padding: '0.75rem 1.5rem', borderRadius: '12px', border: '1px solid var(--border)', background: 'transparent', color: 'var(--text-secondary)', fontWeight: 800, transition: 'background 0.2s', cursor: 'pointer' }}
                className="hover:bg-slate-50"
               >
                Cancel
              </button>
              <button
                type="submit"
                className="btn-primary"
                style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', padding: '0.75rem 1.5rem', borderRadius: '12px', fontWeight: 800 }}
              >
                <Save size={18} /> Save {activeTab === 'items' ? 'Item' : 'Category'}
              </button>
            </div>
          </form>
        </div>,
        document.body
      )}

      {editingIngredientsFor && createPortal(
        <IngredientEditor
          menuItemId={editingIngredientsFor.id}
          menuItemName={editingIngredientsFor.name}
          onClose={() => setEditingIngredientsFor(null)}
        />,
        document.body
      )}
    </div>
  );
};

export default Menu;

import React, { useState, useRef, useEffect } from 'react';
import { Send, Search, Phone, Video, MoreVertical, Smile } from 'lucide-react';
import { useAuth } from '../context/AuthContext';
import api from '../api';

interface Message {
  id: string;
  sender: string;
  senderInitials: string;
  senderColor: string;
  text: string;
  time: string;
  isMe: boolean;
}

interface Channel {
  id: string;
  name: string;
  type: 'team' | 'personal';
  lastMessage: string;
  time: string;
  unread: number;
  initials: string;
  color: string;
}

const CHANNELS: Channel[] = [
  { id: 'foh', name: 'Front of House', type: 'team', lastMessage: "Table 12 is asking for the bill.", time: '2m ago', unread: 2, initials: 'FH', color: '#3b82f6' },
  { id: 'kitchen', name: 'Kitchen', type: 'team', lastMessage: "Two medium steaks for Table 7.", time: 'Just now', unread: 1, initials: 'KT', color: '#f97316' },
  { id: 'maria', name: 'Maria Gomez', type: 'personal', lastMessage: "Can you approve the void on Order #284?", time: '12m ago', unread: 0, initials: 'MG', color: '#8b5cf6' },
  { id: 'daniel', name: 'Daniel Okafor', type: 'personal', lastMessage: "I'll handle the large party at 6 PM.", time: '20m ago', unread: 2, initials: 'DO', color: '#10b981' },
];

const Messages: React.FC = () => {
  const { user } = useAuth();
  const [selectedChannel, setSelectedChannel] = useState<Channel>(CHANNELS[0]);
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputText, setInputText] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [channels, setChannels] = useState<Channel[]>(CHANNELS);
  const bottomRef = useRef<HTMLDivElement>(null);

  // Fetch messages from backend repeatedly
  useEffect(() => {
    let isCancelled = false;
    const fetchMessages = async () => {
      if (!user?.tenantId) return;
      try {
        const res = await api.get(`/tenants/${user.tenantId}/messages/${selectedChannel.id}`);
        if (!isCancelled) {
          const parsed: Message[] = res.data.map((m: any) => ({
            id: m.id,
            sender: m.sender.name,
            senderInitials: m.sender.name.split(' ').map((n: string) => n[0]).join('').slice(0, 2).toUpperCase(),
            senderColor: m.sender.id === user?.id ? 'var(--accent)' : '#94a3b8',
            text: m.content,
            time: new Date(m.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
            isMe: m.sender.id === user?.id
          }));
          setMessages(parsed);
        }
      } catch (err) {
        console.error("Failed to load live messages", err);
      }
    };

    fetchMessages();
    const interval = setInterval(fetchMessages, 3000); // Poll every 3 seconds
    return () => {
      isCancelled = true;
      clearInterval(interval);
    };
  }, [selectedChannel.id, user?.tenantId, user?.id]);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSend = async () => {
    if (!inputText.trim() || !user?.tenantId) return;
    const content = inputText.trim();
    setInputText('');

    // Optimistic UI update
    const optimisticMsg: Message = {
      id: Date.now().toString(),
      sender: user.name || 'You',
      senderInitials: (user.name || 'ME').split(' ').map((n: string) => n[0]).join('').slice(0, 2).toUpperCase(),
      senderColor: 'var(--accent)',
      text: content,
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      isMe: true,
    };
    setMessages(prev => [...prev, optimisticMsg]);
    setChannels(prev => prev.map(c => c.id === selectedChannel.id ? { ...c, unread: 0, lastMessage: content, time: 'Just now' } : c));

    try {
      await api.post(`/tenants/${user.tenantId}/messages`, {
        channel: selectedChannel.id,
        content
      });
    } catch (err) {
      console.error("Failed to send message", err);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const handleSelectChannel = (ch: Channel) => {
    setSelectedChannel(ch);
    setChannels(prev => prev.map(c => c.id === ch.id ? { ...c, unread: 0 } : c));
  };

  const teams = channels.filter(c => c.type === 'team' && c.name.toLowerCase().includes(searchQuery.toLowerCase()));
  const personal = channels.filter(c => c.type === 'personal' && c.name.toLowerCase().includes(searchQuery.toLowerCase()));

  const currentMsgs = messages;

  const Avatar = ({ initials, color, size = 36 }: { initials: string; color: string; size?: number }) => (
    <div style={{
      width: size, height: size, borderRadius: '50%', background: color,
      display: 'flex', alignItems: 'center', justifyContent: 'center',
      fontSize: size * 0.35, fontWeight: 700, color: 'white', flexShrink: 0
    }}>
      {initials}
    </div>
  );

  const ChannelRow = ({ ch }: { ch: Channel }) => {
    const isActive = selectedChannel.id === ch.id;
    return (
      <div
        onClick={() => handleSelectChannel(ch)}
        style={{
          display: 'flex', alignItems: 'center', gap: '0.75rem',
          padding: '0.75rem 1rem', borderRadius: 'var(--radius-md)',
          cursor: 'pointer', marginBottom: '2px',
          background: isActive ? 'var(--accent-soft)' : 'transparent',
          border: `1px solid ${isActive ? 'var(--accent-border)' : 'transparent'}`,
          transition: 'all 0.15s'
        }}
        onMouseEnter={e => { if (!isActive) (e.currentTarget as HTMLDivElement).style.background = 'rgba(255,255,255,0.03)'; }}
        onMouseLeave={e => { if (!isActive) (e.currentTarget as HTMLDivElement).style.background = 'transparent'; }}
      >
        <div style={{ position: 'relative' }}>
          <Avatar initials={ch.initials} color={ch.color} size={38} />
          {ch.unread > 0 && (
            <span style={{
              position: 'absolute', top: -3, right: -3,
              width: '1.1rem', height: '1.1rem', borderRadius: '50%',
              background: 'var(--accent)', color: 'white', fontSize: '0.55rem',
              fontWeight: 800, display: 'flex', alignItems: 'center', justifyContent: 'center',
              border: '2px solid var(--bg-elevated)'
            }}>{ch.unread}</span>
          )}
        </div>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '2px' }}>
            <span style={{ fontWeight: 600, fontSize: '0.875rem', color: isActive ? 'var(--accent)' : 'var(--text-primary)' }}>{ch.name}</span>
            <span style={{ fontSize: '0.7rem', color: 'var(--text-secondary)', whiteSpace: 'nowrap' }}>{ch.time}</span>
          </div>
          <p style={{ fontSize: '0.75rem', color: 'var(--text-secondary)', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{ch.lastMessage}</p>
        </div>
      </div>
    );
  };

  return (
    <div style={{ display: 'flex', height: 'calc(100vh - 4rem)', gap: '1rem', overflow: 'hidden' }}>

      {/* ── Channel List ── */}
      <div style={{
        width: '300px', flexShrink: 0, display: 'flex', flexDirection: 'column',
        background: 'var(--bg-elevated)', border: '1px solid var(--border)',
        borderRadius: 'var(--radius-xl)', overflow: 'hidden'
      }}>
        <div style={{ padding: '1.125rem 1.25rem 0.75rem', borderBottom: '1px solid var(--border)', flexShrink: 0 }}>
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '0.875rem' }}>
            <h2 style={{ fontWeight: 700, fontSize: '1.05rem' }}>Messages</h2>
            <div style={{ display: 'flex', gap: '0.25rem' }}>
              <button style={{ padding: '0.375rem', borderRadius: '7px', background: 'none', border: 'none', cursor: 'pointer', color: 'var(--text-secondary)' }}>
                <Search size={16} />
              </button>
            </div>
          </div>
          <div style={{ position: 'relative' }}>
            <Search size={14} style={{ position: 'absolute', left: '0.7rem', top: '50%', transform: 'translateY(-50%)', color: 'var(--text-secondary)' }} />
            <input
              type="text"
              placeholder="Search conversations..."
              className="form-input"
              style={{ paddingLeft: '2.1rem', fontSize: '0.8rem', padding: '0.55rem 0.75rem 0.55rem 2.1rem' }}
              value={searchQuery}
              onChange={e => setSearchQuery(e.target.value)}
            />
          </div>
        </div>

        <div style={{ flex: 1, overflowY: 'auto', padding: '0.75rem' }}>
          {teams.length > 0 && (
            <>
              <p style={{ fontSize: '0.65rem', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.08em', color: 'var(--text-muted)', padding: '0.375rem 0.25rem 0.5rem' }}>Teams</p>
              {teams.map(ch => <ChannelRow key={ch.id} ch={ch} />)}
            </>
          )}
          {personal.length > 0 && (
            <>
              <p style={{ fontSize: '0.65rem', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.08em', color: 'var(--text-muted)', padding: '0.75rem 0.25rem 0.5rem' }}>Personal</p>
              {personal.map(ch => <ChannelRow key={ch.id} ch={ch} />)}
            </>
          )}
        </div>
      </div>

      {/* ── Chat Window ── */}
      <div style={{
        flex: 1, display: 'flex', flexDirection: 'column',
        background: 'var(--bg-elevated)', border: '1px solid var(--border)',
        borderRadius: 'var(--radius-xl)', overflow: 'hidden'
      }}>
        {/* Chat Header */}
        <div style={{
          padding: '0.875rem 1.25rem', borderBottom: '1px solid var(--border)',
          display: 'flex', alignItems: 'center', justifyContent: 'space-between', flexShrink: 0,
          background: 'rgba(255,255,255,0.02)'
        }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
            <Avatar initials={selectedChannel.initials} color={selectedChannel.color} size={36} />
            <div>
              <p style={{ fontWeight: 700, fontSize: '0.95rem' }}>{selectedChannel.name}</p>
              <p style={{ fontSize: '0.72rem', color: 'var(--text-secondary)' }}>
                {selectedChannel.type === 'team' ? 'Team channel' : 'Staff member'}
              </p>
            </div>
          </div>
          <div style={{ display: 'flex', gap: '0.375rem' }}>
            {[Phone, Video, MoreVertical].map((Icon, i) => (
              <button key={i} style={{
                padding: '0.5rem', borderRadius: '8px', background: 'none', border: 'none',
                cursor: 'pointer', color: 'var(--text-secondary)', transition: 'all 0.15s',
                display: 'flex', alignItems: 'center', justifyContent: 'center'
              }}
                onMouseEnter={e => { (e.currentTarget as HTMLButtonElement).style.background = 'rgba(255,255,255,0.07)'; (e.currentTarget as HTMLButtonElement).style.color = 'white'; }}
                onMouseLeave={e => { (e.currentTarget as HTMLButtonElement).style.background = 'none'; (e.currentTarget as HTMLButtonElement).style.color = 'var(--text-secondary)'; }}
              >
                <Icon size={17} />
              </button>
            ))}
          </div>
        </div>

        {/* Messages */}
        <div style={{ flex: 1, overflowY: 'auto', padding: '1.25rem', display: 'flex', flexDirection: 'column', gap: '0.875rem' }}>
          {currentMsgs.length === 0 && (
            <div style={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'var(--text-secondary)', opacity: 0.4, flexDirection: 'column', gap: '0.75rem' }}>
              <Send size={40} />
              <p style={{ fontSize: '0.875rem' }}>No messages yet. Say hello!</p>
            </div>
          )}

          {/* Date label */}
          {currentMsgs.length > 0 && (
            <div style={{ textAlign: 'center', marginBottom: '0.5rem' }}>
              <span style={{ fontSize: '0.7rem', color: 'var(--text-secondary)', background: 'rgba(255,255,255,0.06)', padding: '0.25rem 0.875rem', borderRadius: '99px', border: '1px solid var(--border)' }}>
                Today
              </span>
            </div>
          )}

          {currentMsgs.map(msg => (
            <div key={msg.id} style={{ display: 'flex', gap: '0.625rem', flexDirection: msg.isMe ? 'row-reverse' : 'row', alignItems: 'flex-end' }}>
              {!msg.isMe && <Avatar initials={msg.senderInitials} color={msg.senderColor} size={28} />}
              <div style={{ maxWidth: '65%', display: 'flex', flexDirection: 'column', alignItems: msg.isMe ? 'flex-end' : 'flex-start' }}>
                {!msg.isMe && (
                  <p style={{ fontSize: '0.7rem', fontWeight: 600, color: 'var(--text-secondary)', marginBottom: '0.25rem', marginLeft: '0.25rem' }}>
                    {msg.sender}
                  </p>
                )}
                <div style={{
                  padding: '0.6rem 0.875rem',
                  borderRadius: msg.isMe ? '14px 14px 4px 14px' : '14px 14px 14px 4px',
                  background: msg.isMe ? 'var(--accent)' : 'rgba(255,255,255,0.07)',
                  border: `1px solid ${msg.isMe ? 'transparent' : 'var(--border)'}`,
                  color: msg.isMe ? 'white' : 'var(--text-primary)',
                  fontSize: '0.875rem',
                  lineHeight: 1.5,
                }}>
                  {msg.text}
                </div>
                <p style={{ fontSize: '0.65rem', color: 'var(--text-secondary)', marginTop: '0.2rem', textAlign: msg.isMe ? 'right' : 'left', paddingInline: '0.25rem' }}>
                  {msg.time}
                </p>
              </div>
            </div>
          ))}
          <div ref={bottomRef} />
        </div>

        {/* Input */}
        <div style={{
          padding: '0.875rem 1.25rem', borderTop: '1px solid var(--border)',
          display: 'flex', alignItems: 'center', gap: '0.625rem', flexShrink: 0
        }}>
          <button style={{ padding: '0.5rem', background: 'none', border: 'none', cursor: 'pointer', color: 'var(--text-secondary)', display: 'flex', alignItems: 'center' }}>
            <Smile size={18} />
          </button>
          <input
            type="text"
            placeholder="Write a message..."
            className="form-input"
            style={{ flex: 1, fontSize: '0.9rem' }}
            value={inputText}
            onChange={e => setInputText(e.target.value)}
            onKeyDown={handleKeyDown}
          />
          <button
            onClick={handleSend}
            disabled={!inputText.trim()}
            className="btn btn-primary"
            style={{ padding: '0.6rem 1rem', flexShrink: 0, opacity: inputText.trim() ? 1 : 0.4 }}
          >
            <Send size={16} />
          </button>
        </div>
      </div>
    </div>
  );
};

export default Messages;

import React, { useState, useEffect } from 'react';
import { 
  Search, Plus, Minus, CreditCard, Banknote, Smartphone, 
  BedSingle, Loader2, CheckCircle2, ShoppingBag, ChevronRight, 
  Tag, X, FileText, Sparkles, LayoutGrid
} from 'lucide-react';
import api from '../api';
import { useAuth } from '../context/AuthContext';
import { useCart } from '../hooks/useCart';
import { useToast } from '../context/ToastContext';

interface Category {
  id: string;
  name: string;
  icon: string;
}

interface MenuItem {
  id: string;
  name: string;
  price: number;
  categoryId: string;
  emoji: string;
  description: string; // Used for weights/subtitles like "170g"
}

const POSTerminal: React.FC = () => {
  const { user, tenant } = useAuth();
  const { items, addItem, updateQuantity, clearCart, subtotal } = useCart();
  const { showToast } = useToast();

  // ── SSE: Real-time order-ready notifications ───────────────────────
  useEffect(() => {
    if (!user?.tenantId) return;
    const token = localStorage.getItem('token') || sessionStorage.getItem('token') || '';
    const API_BASE = (import.meta as any).env?.VITE_API_URL || window.location.origin;
    // SSE connection with JWT token as query param for EventSource (no custom headers)
    const es = new EventSource(`${API_BASE}/api/tenants/${user.tenantId}/sse?token=${token}`);

    es.addEventListener('order:ready', (e: MessageEvent) => {
      try {
        const data = JSON.parse(e.data);
        showToast(`🍽️ Order ${data.orderNumber} is READY for pickup!`, 'success');
      } catch {}
    });

    es.addEventListener('order:new', (e: MessageEvent) => {
      try {
        const data = JSON.parse(e.data);
        showToast(`🛎️ New order ${data.orderNumber} received`, 'info');
      } catch {}
    });

    es.addEventListener('low_stock', (e: MessageEvent) => {
      try {
        const data = JSON.parse(e.data);
        showToast(`⚠️ Low stock: ${data.name} (${data.currentStock} left)`, 'error');
      } catch {}
    });

    es.onerror = () => { /* silently reconnect */ };
    return () => es.close();
  }, [user?.tenantId]);

  const [categories, setCategories] = useState<Category[]>([]);
  const [menuItems, setMenuItems] = useState<MenuItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [guests, setGuests] = useState<any[]>([]);
  const [tables, setTables] = useState<any[]>([]);
  const [rooms, setRooms] = useState<any[]>([]);
  const [selectedGuestId, setSelectedGuestId] = useState<string | null>(null);
  const [selectedRoomId, setSelectedRoomId] = useState<string | null>(null);
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  const [isCheckingOut, setIsCheckingOut] = useState(false);
  const [checkoutStatus, setCheckoutStatus] = useState<'idle' | 'processing' | 'success' | 'error'>('idle');
  const [errorMessage, setErrorMessage] = useState('');
  const [redeemPoints, setRedeemPoints] = useState(false);

  const [activeShift, setActiveShift] = useState<any>(null);
  const [startingFloat, setStartingFloat] = useState<string>('');
  const [isOpeningShift, setIsOpeningShift] = useState(false);

  // M-Pesa STK Push State
  const [showMpesaModal, setShowMpesaModal] = useState(false);
  const [mpesaPhone, setMpesaPhone] = useState('');
  const [mpesaStatus, setMpesaStatus] = useState<'idle' | 'waiting' | 'success' | 'error'>('idle');
  const [, setPendingOrderId] = useState<string | null>(null);
  // M-Pesa tenant config
  const [mpesaStkConfigured, setMpesaStkConfigured] = useState(false);
  const [mpesaTillDisplay, setMpesaTillDisplay] = useState<string | null>(null);
  // Manual M-Pesa ref entry state
  const [showManualMpesaModal, setShowManualMpesaModal] = useState(false);
  const [mpesaRef, setMpesaRef] = useState('');

  const [showDiscountModal, setShowDiscountModal] = useState(false);
  const [discountFixed, setDiscountFixed] = useState(0);
  const [discountPercent, setDiscountPercent] = useState(0);
  const [tableRef, setTableRef] = useState('');

  useEffect(() => {
    setRedeemPoints(false);
  }, [selectedGuestId]);

  const selectedGuest = guests.find(g => g.id === selectedGuestId);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [catsRes, itemsRes, guestsRes, tablesRes, roomsRes, shiftRes, mpesaRes] = await Promise.all([
          api.get(`/tenants/${user?.tenantId}/menu/categories`),
          api.get(`/tenants/${user?.tenantId}/menu/items?available=true`),
          api.get(`/tenants/${user?.tenantId}/guests`),
          api.get(`/tenants/${user?.tenantId}/tables`),
          api.get(`/tenants/${user?.tenantId}/rooms`),
          api.get(`/tenants/${user?.tenantId}/shifts/current`),
          api.get(`/tenants/${user?.tenantId}/mpesa/status`),
        ]);
        setCategories(catsRes.data);
        setMenuItems(itemsRes.data);
        setGuests(guestsRes.data);
        setTables(tablesRes.data);
        setRooms(roomsRes.data);
        setActiveShift(shiftRes.data);
        setMpesaStkConfigured(!!mpesaRes.data?.isConfigured);
        setMpesaTillDisplay(mpesaRes.data?.tillDisplay || null);
      } catch (err) {
        console.error('Failed to fetch POS data', err);
      } finally {
        setLoading(false);
      }
    };
    if (user?.tenantId) fetchData();
  }, [user?.tenantId]);

  const filteredItems = menuItems.filter(item => {
    const matchesCategory = !selectedCategory || item.categoryId === selectedCategory;
    const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  const handleCheckout = async (method: 'cash' | 'card' | 'mpesa' | 'room_charge') => {
    if (items.length === 0) return;

    // For M-Pesa, check if tenant has STK configured
    if (method === 'mpesa') {
      if (mpesaStkConfigured) {
        setShowMpesaModal(true);
      } else {
        setShowManualMpesaModal(true);
      }
      return;
    }

    setCheckoutStatus('processing');
    try {
      await api.post(`/tenants/${user?.tenantId}/orders`, {
        items: items.map(i => ({ menuItemId: i.id, quantity: i.quantity })),
        orderType: method === 'room_charge' ? 'room_service' : 'dine_in',
        tableRef: tableRef || undefined,
        roomId: selectedRoomId || undefined,
        guestId: selectedGuestId,
        payment: { method },
        redeemPoints,
        discountFixed,
        discountPercent
      });
      setCheckoutStatus('success');
      setTimeout(() => {
        clearCart();
        setCheckoutStatus('idle');
        setIsCheckingOut(false);
        setDiscountFixed(0);
        setDiscountPercent(0);
        setTableRef('');
      }, 2000);
    } catch (err: any) {
      console.error('Checkout failed', err);
      setErrorMessage(err.response?.data?.error || 'Failed to place order');
      setCheckoutStatus('error');
    }
  };

  const taxRate = Number(tenant?.taxRate || 0);
  const tax = subtotal * (taxRate / 100);

  let currentDiscount = 0;
  if (selectedGuest && redeemPoints) currentDiscount += selectedGuest.loyaltyPoints;
  if (discountPercent > 0) currentDiscount += (subtotal * (discountPercent / 100));
  if (discountFixed > 0) currentDiscount += discountFixed;

  const total = Math.max(0, subtotal + tax - currentDiscount);

  const [isCartOpen, setIsCartOpen] = useState(false);

  if (loading) return (
    <div style={{ display: 'flex', height: '100%', alignItems: 'center', justifyContent: 'center', flexDirection: 'column', gap: '1rem' }}>
      <Loader2 className="animate-spin text-accent" size={32} />
      <span style={{ fontSize: '0.9rem', color: 'var(--text-secondary)', fontWeight: 600 }}>Syncing Terminal...</span>
    </div>
  );

  const handleOpenShift = async () => {
    if (!startingFloat) return;
    setIsOpeningShift(true);
    try {
      const res = await api.post(`/tenants/${user?.tenantId}/shifts/open`, { startingFloat: Number(startingFloat) });
      setActiveShift(res.data);
    } catch (err: any) {
      alert(err.response?.data?.error || 'Failed to open shift');
    } finally {
      setIsOpeningShift(false);
    }
  };

  if (!activeShift) {
    return (
      <div style={{ display: 'flex', height: 'calc(100vh - 2rem)', alignItems: 'center', justifyContent: 'center', padding: '1rem' }}>
        <div className="card" style={{ padding: '4rem 3rem', maxWidth: '480px', width: '100%', textAlign: 'center', display: 'flex', flexDirection: 'column', alignItems: 'center', background: 'var(--bg-elevated)', borderRadius: '32px', border: '1px solid var(--border)', boxShadow: '0 20px 40px rgba(0,0,0,0.08)' }}>
           <div style={{ width: '80px', height: '80px', borderRadius: '24px', background: 'rgba(184, 134, 11, 0.1)', color: 'var(--accent)', display: 'flex', alignItems: 'center', justifyContent: 'center', marginBottom: '2rem' }}>
              <Banknote size={40} />
           </div>
           <h2 style={{ fontSize: '2rem', fontWeight: 900, marginBottom: '1rem', letterSpacing: '-0.03em' }}>Register Closed</h2>
           <p style={{ color: 'var(--text-secondary)', fontWeight: 600, fontSize: '1rem', marginBottom: '3.5rem', lineHeight: 1.6 }}>You must declare your starting float to begin accepting cash transactions on this station.</p>

           <div style={{ width: '100%', textAlign: 'left', marginBottom: '2.5rem' }}>
             <label style={{ fontSize: '0.85rem', fontWeight: 800, color: 'var(--text-muted)', textTransform: 'uppercase', marginBottom: '0.875rem', display: 'block', letterSpacing: '0.05em' }}>Starting Cash Drawer Float</label>
             <div style={{ position: 'relative' }}>
                <span style={{ position: 'absolute', left: '1.5rem', top: '50%', transform: 'translateY(-50%)', fontWeight: 900, color: 'var(--text-muted)', fontSize: '1.25rem' }}>{tenant?.currency}</span>
                <input 
                  type="number" 
                  className="form-input" 
                  placeholder="0.00"
                  style={{ paddingLeft: '4rem', height: '72px', borderRadius: '20px', fontWeight: 800, fontSize: '1.5rem' }} 
                  value={startingFloat} 
                  onChange={e => setStartingFloat(e.target.value)} 
                />
             </div>
           </div>

           <button 
             onClick={handleOpenShift}
             disabled={isOpeningShift || !startingFloat}
             className="btn btn-primary"
             style={{ width: '100%', height: '64px', borderRadius: '20px', fontSize: '1.1rem', fontWeight: 800, gap: '10px' }}
           >
             {isOpeningShift ? <Loader2 className="animate-spin" size={24} /> : <CheckCircle2 size={24} />}
             Open Register Shift
           </button>
        </div>
      </div>
    );
  }

  return (
    <div className="pos-container">

      {/* Mobile Cart Toggle Overlay */}
      {isCartOpen && (
        <div 
          className="mobile-only"
          onClick={() => setIsCartOpen(false)}
          style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.5)', zIndex: 1050, backdropFilter: 'blur(4px)' }}
        />
      )}

      {/* ── Left: Menu Browser ── */}
      <div style={{ flex: 1, display: 'flex', flexDirection: 'column', minWidth: 0 }}>

        {/* Header & Categories */}
        <div style={{ marginBottom: '2.5rem' }}>
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '1.5rem' }}>
            <div>
              <div style={{ display: 'flex', alignItems: 'center', gap: '6px', color: 'var(--accent)', fontWeight: 800, fontSize: '0.7rem', textTransform: 'uppercase', letterSpacing: '0.08em', marginBottom: '0.5rem' }}>
                 <Sparkles size={14} /> POS TERMINAL
              </div>
              <h1 style={{ fontSize: '2rem', fontWeight: 800, letterSpacing: '-0.03em' }}>Checkout Hub</h1>
            </div>

            <div style={{ position: 'relative', width: '300px' }}>
              <Search style={{ position: 'absolute', right: '1.25rem', top: '50%', transform: 'translateY(-50%)', color: 'var(--text-muted)' }} size={18} />
              <input 
                type="text" 
                placeholder="Search menu..." 
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="form-input"
                style={{ borderRadius: '14px', background: 'var(--bg-elevated)', border: '1px solid var(--border)', boxShadow: 'var(--shadow-sm)' }}
              />
            </div>
          </div>

          <div style={{ display: 'flex', gap: '0.875rem', overflowX: 'auto', paddingBottom: '0.5rem', scrollbarWidth: 'none' }}>
            <button
              onClick={() => setSelectedCategory(null)}
              style={{
                padding: '0.875rem 1.75rem', borderRadius: '16px', border: 'none', whiteSpace: 'nowrap',
                background: !selectedCategory ? 'var(--accent)' : 'white',
                color: !selectedCategory ? 'var(--text-inverted)' : 'var(--text-secondary)',
                fontWeight: 800, fontSize: '0.9rem', cursor: 'pointer',
                boxShadow: 'var(--shadow-sm)',
                transition: 'all 0.3s cubic-bezier(0.16, 1, 0.3, 1)',
                display: 'flex', alignItems: 'center', gap: '0.625rem'
              }}
            >
              <LayoutGrid size={18} /> All Items
            </button>
            {categories.map(cat => {
              const isActive = selectedCategory === cat.id;
              return (
                <button
                  key={cat.id}
                  onClick={() => setSelectedCategory(cat.id)}
                  style={{
                    padding: '0.875rem 1.75rem', borderRadius: '16px', border: 'none', whiteSpace: 'nowrap',
                    background: isActive ? 'var(--accent)' : 'white',
                    color: isActive ? 'var(--text-inverted)' : 'var(--text-secondary)',
                    fontWeight: 800, fontSize: '0.9rem', cursor: 'pointer',
                    boxShadow: 'var(--shadow-sm)',
                    transition: 'all 0.3s cubic-bezier(0.16, 1, 0.3, 1)',
                    display: 'flex', alignItems: 'center', gap: '0.625rem'
                  }}
                >
                  <span style={{ fontSize: '1.25rem' }}>{cat.icon}</span> {cat.name}
                </button>
              );
            })}
          </div>
        </div>

        {/* Menu Grid */}
        <div style={{ flex: 1, overflowY: 'auto', padding: '0.5rem', display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(180px, 1fr))', gap: '1rem', alignContent: 'start' }}>
          {filteredItems.map((item, i) => (
            <div 
              key={item.id} 
              className="card" 
              onClick={() => addItem({ id: item.id, name: item.name, price: Number(item.price), emoji: item.emoji })}
              style={{ 
                padding: '1.5rem', cursor: 'pointer', display: 'flex', flexDirection: 'column', 
                alignItems: 'center', textAlign: 'center', borderRadius: '28px', 
                background: 'var(--bg-elevated)', border: '1px solid var(--border)',
                animationDelay: `${(i % 12) * 0.05}s` 
              }}
            >
              <div style={{ 
                width: '6rem', height: '6rem', borderRadius: '24px', 
                background: 'var(--bg-deep)', display: 'flex', alignItems: 'center', 
                justifyContent: 'center', fontSize: '3rem', marginBottom: '1.25rem'
              }}>
                {item.emoji}
              </div>
              <h3 style={{ fontSize: '1rem', fontWeight: 800, marginBottom: '0.25rem' }}>{item.name}</h3>
              <p style={{ fontSize: '0.75rem', color: 'var(--text-muted)', fontWeight: 700, marginBottom: '0.75rem' }}>{item.description || 'Standard'}</p>
              <div style={{ fontSize: '1.15rem', fontWeight: 900, color: 'var(--accent)' }}>
                {tenant?.currency} {Number(item.price).toLocaleString()}
              </div>
            </div>
          ))}
        </div>
      </div>

      <button className="mobile-cart-toggle" onClick={() => setIsCartOpen(true)}>
        <ShoppingBag size={24} />
        View Order Ticket 
        <span style={{ background: 'rgba(255,255,255,0.2)', padding: '4px 10px', borderRadius: '10px', fontSize: '1rem' }}>{items.length}</span>
      </button>

      {/* ── Right: Ticket Panel (White / High-Contrast) ── */}
      <div className={`pos-cart-sidebar ${isCartOpen ? 'open' : ''}`}>

        {/* Ticket Header */}
        <div style={{ padding: '2rem', borderBottom: '1px solid var(--bg-deep)', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <h2 style={{ fontSize: '1.5rem', fontWeight: 800, display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
            <FileText size={24} color="var(--accent)" /> Ticket
          </h2>
          <div style={{ display: 'flex', gap: '10px' }}>
            <button 
              className="mobile-only"
              onClick={() => setIsCartOpen(false)}
              style={{ background: 'var(--bg-deep)', border: 'none', padding: '8px', borderRadius: '50%', cursor: 'pointer' }}
            >
              <X size={20} />
            </button>
            {items.length > 0 && (
              <button 
                onClick={clearCart}
                style={{ background: '#fff1f2', color: '#f43f5e', border: 'none', padding: '8px 14px', borderRadius: '10px', fontSize: '0.8rem', fontWeight: 800, cursor: 'pointer' }}
              >
                Clear
              </button>
            )}
            <span style={{ fontSize: '0.85rem', fontWeight: 800, padding: '8px 14px', borderRadius: '99px', background: 'var(--bg-deep)', color: 'var(--text-primary)' }}>
              {items.length} Items
            </span>
          </div>
        </div>

        {/* Cart Items */}
        <div style={{ flex: 1, overflowY: 'auto', padding: '1.5rem', display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
          {items.length === 0 ? (
            <div style={{ height: '100%', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', opacity: 0.4 }}>
              <ShoppingBag size={64} color="var(--text-muted)" />
              <p style={{ marginTop: '1.25rem', fontSize: '1.1rem', fontWeight: 800, color: 'var(--text-muted)' }}>Ready for orders</p>
            </div>
          ) : items.map(item => (
            <div key={item.id} style={{ display: 'flex', gap: '1.25rem', background: 'var(--bg-base)', padding: '1.15rem', borderRadius: '20px', border: '1px solid var(--border)', alignItems: 'center' }}>
              <div style={{ fontSize: '1.75rem' }}>{item.emoji}</div>
              <div style={{ flex: 1, minWidth: 0 }}>
                <p style={{ fontSize: '0.95rem', fontWeight: 800, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', marginBottom: '2px' }}>{item.name}</p>
                <p style={{ fontSize: '0.85rem', color: 'var(--accent)', fontWeight: 900 }}>{tenant?.currency} {item.price.toLocaleString()}</p>
              </div>
              <div style={{ display: 'flex', alignItems: 'center', gap: '12px', background: 'var(--bg-elevated)', padding: '6px', borderRadius: '12px', border: '1px solid var(--border)' }}>
                <button onClick={() => updateQuantity(item.id, -1)} style={{ width: '32px', height: '32px', borderRadius: '8px', border: 'none', background: 'var(--bg-deep)', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center' }}><Minus size={16} /></button>
                <span style={{ fontSize: '1rem', fontWeight: 900, minWidth: '1.5rem', textAlign: 'center' }}>{item.quantity}</span>
                <button onClick={() => updateQuantity(item.id, 1)} style={{ width: '32px', height: '32px', borderRadius: '8px', border: 'none', background: 'var(--accent)', color: 'white', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center' }}><Plus size={16} /></button>
              </div>
            </div>
          ))}
        </div>

        {/* Checkout Section */}
        <div style={{ padding: '2.5rem', background: 'var(--bg-deep)', borderTop: '1px solid var(--bg-deep)' }}>

          {/* Summary */}
          <div style={{ marginBottom: '2rem', display: 'flex', flexDirection: 'column', gap: '0.875rem' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.95rem', color: 'var(--text-secondary)', fontWeight: 700 }}>
              <span style={{ opacity: 0.7 }}>Subtotal</span>
              <span style={{ fontWeight: 800 }}>{tenant?.currency} {subtotal.toLocaleString()}</span>
            </div>
            <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.95rem', color: 'var(--text-secondary)', fontWeight: 700 }}>
              <span style={{ opacity: 0.7 }}>Tax ({taxRate}%)</span>
              <span style={{ fontWeight: 800 }}>{tenant?.currency} {tax.toLocaleString()}</span>
            </div>
            {currentDiscount > 0 && (
              <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.95rem', color: '#10b981', fontWeight: 900 }}>
                <span>Loyalty/Discount</span>
                <span>-{tenant?.currency} {currentDiscount.toLocaleString()}</span>
              </div>
            )}

            <div style={{ borderTop: '1px solid rgba(0,0,0,0.08)', margin: '1rem 0', paddingTop: '1.5rem', display: 'flex', justifyContent: 'space-between', alignItems: 'end' }}>
               <div>
                 <p style={{ fontSize: '0.8rem', fontWeight: 800, color: 'var(--text-muted)', textTransform: 'uppercase', marginBottom: '0.25rem' }}>Total Amount</p>
                 <span style={{ fontSize: '2.5rem', fontWeight: 900, letterSpacing: '-0.03em' }}>{tenant?.currency} {total.toLocaleString()}</span>
               </div>
               <button 
                  onClick={() => setShowDiscountModal(true)}
                  style={{ background: 'var(--bg-elevated)', border: '1px solid var(--border)', color: 'var(--text-secondary)', padding: '10px 16px', borderRadius: '12px', fontSize: '0.8rem', fontWeight: 800, display: 'flex', alignItems: 'center', gap: '6px', cursor: 'pointer', boxShadow: 'var(--shadow-sm)' }}
                >
                  <Tag size={16} /> Discount
                </button>
            </div>
          </div>

          {!isCheckingOut ? (
            <button
               disabled={items.length === 0}
               onClick={() => setIsCheckingOut(true)}
               className="btn btn-primary"
               style={{ width: '100%', height: '72px', borderRadius: '20px', fontSize: '1.25rem', fontWeight: 800, boxShadow: '0 12px 24px var(--accent-glow)' }}
            >
               Order Now <ChevronRight size={24} style={{ marginLeft: '8px' }} />
            </button>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>
               <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
                    <label style={{ fontSize: '0.7rem', fontWeight: 800, color: 'var(--text-muted)' }}>Order Type</label>
                    <select className="form-input" value={tableRef} onChange={e => setTableRef(e.target.value)} style={{ background: 'var(--bg-elevated)', fontWeight: 800 }}>
                      <option value="">Takeaway</option>
                      {tables.map(t => <option key={t.id} value={t.number}>Table {t.number}</option>)}
                    </select>
                  </div>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
                    <label style={{ fontSize: '0.7rem', fontWeight: 800, color: 'var(--text-muted)' }}>Customer</label>
                    <select className="form-input" value={selectedGuestId || ''} onChange={e => setSelectedGuestId(e.target.value || null)} style={{ background: 'var(--bg-elevated)', fontWeight: 800 }}>
                      <option value="">Walk-in</option>
                      {guests.map(g => <option key={g.id} value={g.id}>{g.firstName} {g.lastName}</option>)}
                    </select>
                  </div>
               </div>

               <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
                 <label style={{ fontSize: '0.7rem', fontWeight: 800, color: 'var(--text-muted)' }}>Apply Room Charge To</label>
                 <select className="form-input" value={selectedRoomId || ''} onChange={e => setSelectedRoomId(e.target.value || null)} style={{ background: 'var(--bg-elevated)', fontWeight: 800 }}>
                   <option value="">Not Applicable / Select Room...</option>
                   {rooms.filter(r => r.status === 'occupied').map(r => (
                     <option key={r.id} value={r.id}>Room {r.number} ({r.guestName})</option>
                   ))}
                 </select>
               </div>

               <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: '0.875rem' }}>
                  <button onClick={() => handleCheckout('cash')} className="btn" style={{ background: 'var(--bg-elevated)', border: '1px solid var(--border)', height: '58px', borderRadius: '14px', gap: '8px' }}>
                    <Banknote size={20} /> <span style={{ fontWeight: 800 }}>Cash</span>
                  </button>
                  <button onClick={() => handleCheckout('card')} className="btn" style={{ background: 'var(--bg-elevated)', border: '1px solid var(--border)', height: '58px', borderRadius: '14px', gap: '8px' }}>
                    <CreditCard size={20} /> <span style={{ fontWeight: 800 }}>Card</span>
                  </button>
                  <button onClick={() => handleCheckout('mpesa')} className="btn" style={{ background: 'var(--bg-elevated)', border: '1px solid var(--border)', height: '58px', borderRadius: '14px', gap: '8px' }}>
                    <Smartphone size={20} /> <span style={{ fontWeight: 800 }}>M-Pesa</span>
                  </button>
                  <button onClick={() => handleCheckout('room_charge')} className="btn btn-primary" style={{ height: '58px', borderRadius: '14px', gap: '8px' }}>
                    <BedSingle size={20} /> <span style={{ fontWeight: 800 }}>Room</span>
                  </button>
               </div>

               <button onClick={() => setIsCheckingOut(false)} style={{ background: 'none', border: 'none', color: 'var(--text-muted)', fontSize: '0.9rem', fontWeight: 800, cursor: 'pointer', padding: '0.5rem' }}>
                  Modify Order
               </button>
            </div>
          )}
        </div>
      </div>

      {/* Overlays (Modal/Status) */}
      {checkoutStatus !== 'idle' && (
        <div style={{ position: 'fixed', inset: 0, zIndex: 1000, display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'rgba(0,0,0,0.4)', backdropFilter: 'blur(16px)' }}>
           <div className="card" style={{ padding: '3.5rem', textAlign: 'center', maxWidth: '420px', width: '90%', borderRadius: '40px', background: 'var(--bg-elevated)', border: '1px solid var(--border)' }}>
              {checkoutStatus === 'processing' ? (
                <>
                  <Loader2 className="animate-spin text-accent" size={56} style={{ margin: '0 auto 2rem' }} />
                  <h3 style={{ fontSize: '1.75rem', fontWeight: 900 }}>Finalizing Order</h3>
                  <p style={{ color: 'var(--text-secondary)', marginTop: '0.75rem', fontWeight: 600 }}>Kitchen is being notified...</p>
                </>
              ) : checkoutStatus === 'success' ? (
                <>
                  <div style={{ width: '80px', height: '80px', borderRadius: '50%', background: '#ecfdf5', color: '#10b981', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 2rem' }}>
                    <CheckCircle2 size={40} />
                  </div>
                  <h3 style={{ fontSize: '1.75rem', fontWeight: 900 }}>Order Success</h3>
                  <p style={{ color: 'var(--text-secondary)', marginTop: '0.75rem', fontWeight: 600 }}>Transaction completed successfully.</p>
                </>
              ) : (
                <>
                  <div style={{ width: '80px', height: '80px', borderRadius: '50%', background: '#fff1f2', color: '#f43f5e', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 2rem' }}>
                    <X size={40} />
                  </div>
                  <h3 style={{ fontSize: '1.75rem', fontWeight: 900 }}>Checkout Failed</h3>
                  <p style={{ color: 'var(--text-secondary)', marginTop: '0.75rem', fontWeight: 600 }}>{errorMessage}</p>
                  <button onClick={() => setCheckoutStatus('idle')} className="btn btn-primary" style={{ width: '100%', height: '60px', marginTop: '2.5rem' }}>Try Again</button>
                </>
              )}
           </div>
        </div>
      )}

      {showDiscountModal && (
        <div style={{ position: 'fixed', inset: 0, zIndex: 1100, display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'rgba(0,0,0,0.4)', backdropFilter: 'blur(16px)' }}>
           <div className="card" style={{ width: '400px', padding: '2.5rem', borderRadius: '32px', background: 'var(--bg-elevated)' }}>
              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '2.5rem' }}>
                 <h3 style={{ fontSize: '1.5rem', fontWeight: 800 }}>Apply Deduction</h3>
                 <button onClick={() => setShowDiscountModal(false)} style={{ background: 'var(--bg-deep)', border: 'none', padding: '10px', borderRadius: '50%', cursor: 'pointer' }}><X size={18} /></button>
              </div>

              <div style={{ display: 'flex', flexDirection: 'column', gap: '1.75rem' }}>
                 <div>
                    <label style={{ fontSize: '0.75rem', fontWeight: 800, color: 'var(--text-muted)', textTransform: 'uppercase', marginBottom: '0.875rem', display: 'block' }}>Fixed Amount</label>
                    <div style={{ position: 'relative' }}>
                       <span style={{ position: 'absolute', left: '1.25rem', top: '50%', transform: 'translateY(-50%)', fontWeight: 900, color: 'var(--text-muted)' }}>{tenant?.currency}</span>
                       <input type="number" className="form-input" style={{ paddingLeft: '3.5rem', height: '60px', borderRadius: '16px', fontWeight: 800 }} value={discountFixed || ''} onChange={e => { setDiscountFixed(Number(e.target.value)); setDiscountPercent(0); }} />
                    </div>
                 </div>
                 <div style={{ textAlign: 'center', fontSize: '0.75rem', fontWeight: 800, color: 'var(--text-muted)' }}>— OR —</div>
                 <div>
                    <label style={{ fontSize: '0.75rem', fontWeight: 800, color: 'var(--text-muted)', textTransform: 'uppercase', marginBottom: '0.875rem', display: 'block' }}>Percentage</label>
                    <div style={{ position: 'relative' }}>
                       <span style={{ position: 'absolute', right: '1.25rem', top: '50%', transform: 'translateY(-50%)', fontWeight: 900, color: 'var(--text-muted)' }}>%</span>
                       <input type="number" className="form-input" style={{ height: '60px', borderRadius: '16px', fontWeight: 800 }} value={discountPercent || ''} onChange={e => { setDiscountPercent(Number(e.target.value)); setDiscountFixed(0); }} />
                    </div>
                 </div>
                 <button onClick={() => setShowDiscountModal(false)} className="btn btn-primary" style={{ width: '100%', height: '64px', borderRadius: '18px', fontSize: '1.1rem', fontWeight: 800 }}>Apply Discount</button>
                 <button onClick={() => { setDiscountFixed(0); setDiscountPercent(0); setShowDiscountModal(false); }} style={{ background: 'none', border: 'none', color: '#f43f5e', fontWeight: 800, textDecoration: 'underline', cursor: 'pointer' }}>Clear All</button>
              </div>
           </div>
        </div>
      )}

      {/* M-Pesa STK Push Modal */}
      {showMpesaModal && (
        <div style={{ position: 'fixed', inset: 0, zIndex: 1200, display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'rgba(0,0,0,0.5)', backdropFilter: 'blur(16px)' }}>
          <div className="card" style={{ width: '400px', padding: '2.5rem', borderRadius: '32px', background: 'var(--bg-elevated)', textAlign: 'center' }}>
            {mpesaStatus === 'idle' && (
              <>
                <div style={{ width: '72px', height: '72px', borderRadius: '20px', background: 'rgba(0, 163, 68, 0.12)', color: '#00A344', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 1.5rem', fontSize: '2.5rem' }}>📱</div>
                <h3 style={{ fontSize: '1.5rem', fontWeight: 900, marginBottom: '0.5rem' }}>M-Pesa Payment</h3>
                <p style={{ color: 'var(--text-secondary)', fontWeight: 600, marginBottom: '2rem' }}>Enter the customer's Safaricom number to send a payment prompt.</p>
                <div style={{ textAlign: 'left', marginBottom: '1.5rem' }}>
                  <label style={{ fontSize: '0.75rem', fontWeight: 800, color: 'var(--text-muted)', display: 'block', marginBottom: '0.5rem' }}>PHONE NUMBER</label>
                  <input type="tel" className="form-input" placeholder="07XXXXXXXX" style={{ height: '56px', borderRadius: '16px', fontWeight: 800, fontSize: '1.2rem' }} value={mpesaPhone} onChange={e => setMpesaPhone(e.target.value)} />
                </div>
                <div style={{ display: 'flex', gap: '1rem' }}>
                  <button onClick={() => { setShowMpesaModal(false); setMpesaPhone(''); setMpesaStatus('idle'); }} className="btn" style={{ flex: 1, height: '52px', borderRadius: '14px', background: 'var(--bg-deep)', border: '1px solid var(--border)' }}>Cancel</button>
                  <button className="btn btn-primary" style={{ flex: 2, height: '52px', borderRadius: '14px', background: '#00A344' }} disabled={!mpesaPhone}
                    onClick={async () => {
                      setMpesaStatus('waiting');
                      try {
                        const orderRes = await api.post(`/tenants/${user?.tenantId}/orders`, { items: items.map(i => ({ menuItemId: i.id, quantity: i.quantity })), orderType: 'dine_in', tableRef: tableRef || undefined, guestId: selectedGuestId, redeemPoints, discountFixed, discountPercent });
                        const orderId = orderRes.data.id;
                        setPendingOrderId(orderId);
                        await api.post(`/tenants/${user?.tenantId}/mpesa/stk-push`, { phone: mpesaPhone, amount: total, orderId });
                        let attempts = 0;
                        const poll = setInterval(async () => {
                          attempts++;
                          if (attempts > 20) { clearInterval(poll); setMpesaStatus('error'); return; }
                          try {
                            const check = await api.get(`/tenants/${user?.tenantId}/orders/${orderId}`);
                            if (check.data.status === 'completed') {
                              clearInterval(poll);
                              setMpesaStatus('success');
                              setTimeout(() => { clearCart(); setShowMpesaModal(false); setMpesaPhone(''); setMpesaStatus('idle'); setIsCheckingOut(false); setPendingOrderId(null); }, 2500);
                            }
                          } catch { /* continue polling */ }
                        }, 3000);
                      } catch { setMpesaStatus('error'); }
                    }}>
                    Send to Phone
                  </button>
                </div>
              </>
            )}
            {mpesaStatus === 'waiting' && (
              <>
                <Loader2 className="animate-spin" size={56} style={{ margin: '0 auto 2rem', color: '#00A344' }} />
                <h3 style={{ fontSize: '1.5rem', fontWeight: 900 }}>Awaiting Confirmation</h3>
                <p style={{ color: 'var(--text-secondary)', fontWeight: 600, marginTop: '0.75rem' }}>Prompt sent to <strong>{mpesaPhone}</strong>. Customer should enter their M-Pesa PIN...</p>
              </>
            )}
            {mpesaStatus === 'success' && (
              <>
                <div style={{ width: '80px', height: '80px', borderRadius: '50%', background: '#ecfdf5', color: '#10b981', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 2rem' }}><CheckCircle2 size={40} /></div>
                <h3 style={{ fontSize: '1.75rem', fontWeight: 900 }}>Payment Confirmed!</h3>
                <p style={{ color: 'var(--text-secondary)', marginTop: '0.75rem' }}>M-Pesa payment received.</p>
              </>
            )}
            {mpesaStatus === 'error' && (
              <>
                <div style={{ width: '80px', height: '80px', borderRadius: '50%', background: '#fff1f2', color: '#f43f5e', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 2rem' }}><X size={40} /></div>
                <h3 style={{ fontSize: '1.75rem', fontWeight: 900 }}>Payment Timed Out</h3>
                <p style={{ color: 'var(--text-secondary)', marginTop: '0.75rem' }}>The customer did not confirm. Order is saved as pending.</p>
                <button onClick={() => { setShowMpesaModal(false); setMpesaStatus('idle'); }} className="btn btn-primary" style={{ width: '100%', height: '56px', marginTop: '2rem' }}>Close</button>
              </>
            )}
          </div>
        </div>
      )}

      {/* Manual M-Pesa Modal (for tenants without STK Push configured) */}
      {showManualMpesaModal && (
        <div style={{ position: 'fixed', inset: 0, zIndex: 1200, display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'rgba(0,0,0,0.5)', backdropFilter: 'blur(16px)' }}>
          <div className="card" style={{ width: '400px', padding: '2.5rem', borderRadius: '32px', background: 'var(--bg-elevated)', textAlign: 'center' }}>
            <div style={{ width: '72px', height: '72px', borderRadius: '20px', background: 'rgba(0, 163, 68, 0.12)', margin: '0 auto 1.5rem', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '2.5rem' }}>📱</div>
            <h3 style={{ fontSize: '1.5rem', fontWeight: 900, marginBottom: '0.5rem' }}>Manual M-Pesa</h3>

            {/* Till number display if set */}
            {mpesaTillDisplay && (
              <div style={{ background: 'rgba(0,163,68,0.08)', border: '1px solid #00A344', borderRadius: '16px', padding: '1.25rem', marginBottom: '1.5rem', marginTop: '1rem' }}>
                <p style={{ fontSize: '0.75rem', fontWeight: 800, color: '#00A344', textTransform: 'uppercase', marginBottom: '0.25rem' }}>Customer pays to till:</p>
                <p style={{ fontSize: '2.5rem', fontWeight: 900, letterSpacing: '0.1em', color: '#00A344' }}>{mpesaTillDisplay}</p>
                <p style={{ fontSize: '0.85rem', color: 'var(--text-muted)', fontWeight: 600 }}>Amount: <strong>{tenant?.currency} {total.toLocaleString()}</strong></p>
              </div>
            )}

            <p style={{ color: 'var(--text-secondary)', fontWeight: 600, marginBottom: '1.5rem', fontSize: '0.9rem' }}>
              Ask the customer to pay via their M-Pesa menu, then enter the confirmation code below.
            </p>

            <div style={{ textAlign: 'left', marginBottom: '1.5rem' }}>
              <label style={{ fontSize: '0.75rem', fontWeight: 800, color: 'var(--text-muted)', display: 'block', marginBottom: '0.5rem' }}>M-PESA CONFIRMATION CODE</label>
              <input
                type="text"
                className="form-input"
                placeholder="e.g. QJL12ABCDE"
                style={{ height: '56px', borderRadius: '16px', fontWeight: 900, fontSize: '1.3rem', letterSpacing: '0.08em', textTransform: 'uppercase' }}
                value={mpesaRef}
                onChange={e => setMpesaRef(e.target.value.toUpperCase())}
              />
            </div>

            <div style={{ display: 'flex', gap: '1rem' }}>
              <button onClick={() => { setShowManualMpesaModal(false); setMpesaRef(''); }} className="btn" style={{ flex: 1, height: '52px', borderRadius: '14px', background: 'var(--bg-deep)', border: '1px solid var(--border)' }}>Cancel</button>
              <button
                className="btn btn-primary"
                style={{ flex: 2, height: '52px', borderRadius: '14px', background: '#00A344' }}
                disabled={mpesaRef.length < 6}
                onClick={async () => {
                  setCheckoutStatus('processing');
                  setShowManualMpesaModal(false);
                  try {
                    await api.post(`/tenants/${user?.tenantId}/orders`, {
                      items: items.map(i => ({ menuItemId: i.id, quantity: i.quantity })),
                      orderType: tableRef ? 'dine_in' : 'takeaway',
                      tableRef: tableRef || undefined,
                      guestId: selectedGuestId,
                      payment: { method: 'mpesa' },
                      redeemPoints, discountFixed, discountPercent,
                      mpesaReference: mpesaRef
                    });
                    setCheckoutStatus('success');
                    setTimeout(() => { clearCart(); setCheckoutStatus('idle'); setIsCheckingOut(false); setMpesaRef(''); }, 2000);
                  } catch (err: any) {
                    setErrorMessage(err.response?.data?.error || 'Failed to record M-Pesa payment');
                    setCheckoutStatus('error');
                  }
                }}
              >
                Confirm Payment
              </button>
            </div>
          </div>
        </div>
      )}

    </div>
  );
};

export default POSTerminal;

import React, { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { Package, Truck, Plus, CheckCircle2, Clock, XCircle, Send, RefreshCw, ArrowDown, Save, X } from 'lucide-react';
import api from '../api';
import { useAuth } from '../context/AuthContext';
import { useToast } from '../context/ToastContext';

interface Supplier { id: string; name: string; contact?: string; email?: string; phone?: string; }
interface InventoryItem { id: string; name: string; unit: string; currentStock: number; }
interface POItem { inventoryItemId: string; quantity: number; unitPrice: number; inventoryItem?: InventoryItem; }
interface PurchaseOrder {
  id: string; supplierId: string; status: string; totalAmount: number;
  notes?: string; orderDate: string; receiveDate?: string;
  supplier: Supplier; items: POItem[];
}

const statusBadge: Record<string, { label: string; color: string; bg: string; icon: any; border: string }> = {
  draft:     { label: 'Draft',     color: '#64748b', bg: '#f1f5f9', border: '#cbd5e1', icon: Clock },
  sent:      { label: 'Outbound',  color: 'var(--accent)', bg: 'var(--accent-soft)', border: 'var(--accent-border)', icon: Send },
  received:  { label: 'Received',  color: '#10b981', bg: '#ecfdf5', border: '#a7f3d0', icon: CheckCircle2 },
  cancelled: { label: 'Voided', color: '#ef4444', bg: '#fef2f2', border: '#fecaca', icon: XCircle },
};

const Procurement: React.FC = () => {
  const { user, tenant } = useAuth();
  const { showToast } = useToast();
  const [tab, setTab] = useState<'orders' | 'suppliers'>('orders');
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [inventory, setInventory] = useState<InventoryItem[]>([]);
  const [orders, setOrders] = useState<PurchaseOrder[]>([]);
  const [loading, setLoading] = useState(true);

  const [showPOModal, setShowPOModal] = useState(false);
  const [showSupplierModal, setShowSupplierModal] = useState(false);

  const [newSupplier, setNewSupplier] = useState({ name: '', contact: '', email: '', phone: '' });
  const [poForm, setPOForm] = useState({ supplierId: '', notes: '', items: [{ inventoryItemId: '', quantity: 1, unitPrice: 0 }] });

  // Filters
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');
  const [supplierFilter, setSupplierFilter] = useState('all');

  const tid = user?.tenantId;

  const fetchAll = async () => {
    try {
      const [sRes, poRes, invRes] = await Promise.all([
        api.get(`/tenants/${tid}/procurement/suppliers`),
        api.get(`/tenants/${tid}/procurement/purchase-orders`),
        api.get(`/tenants/${tid}/inventory`),
      ]);
      setSuppliers(sRes.data);
      setOrders(poRes.data);
      setInventory(invRes.data);
    } catch {
      showToast('Failed to load procurement data', 'error');
    } finally { setLoading(false); }
  };

  useEffect(() => { if (tid) fetchAll(); }, [tid]);

  const handleCreateSupplier = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newSupplier.name.trim()) {
      showToast('Supplier name is required', 'error');
      return;
    }
    try {
      await api.post(`/tenants/${tid}/procurement/suppliers`, newSupplier);
      showToast('Supplier registry updated', 'success');
      setShowSupplierModal(false);
      setNewSupplier({ name: '', contact: '', email: '', phone: '' });
      fetchAll();
    } catch { showToast('Registry fail', 'error'); }
  };

  const handleCreatePO = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!poForm.supplierId) {
      showToast('Select a supplier', 'error');
      return;
    }
    const validItems = poForm.items.filter(i => i.inventoryItemId && i.quantity > 0);
    if (!validItems.length) { showToast('Add valid items', 'error'); return; }
    try {
      await api.post(`/tenants/${tid}/procurement/purchase-orders`, { ...poForm, items: validItems });
      showToast('PO Issued', 'success');
      setShowPOModal(false);
      setPOForm({ supplierId: '', notes: '', items: [{ inventoryItemId: '', quantity: 1, unitPrice: 0 }] });
      fetchAll();
    } catch { showToast('Failed dispatching PO', 'error'); }
  };

  const handleStatusChange = async (poId: string, newStatus: string) => {
    try {
      await api.patch(`/tenants/${tid}/procurement/purchase-orders/${poId}/status`, { status: newStatus });
      showToast(`Purchase order updated to ${newStatus}`, 'success');
      fetchAll();
    } catch { showToast('Execution failure', 'error'); }
  };

  const addPOLine = () => setPOForm(f => ({ ...f, items: [...f.items, { inventoryItemId: '', quantity: 1, unitPrice: 0 }] }));
  const updatePOLine = (idx: number, key: string, val: any) =>
    setPOForm(f => ({ ...f, items: f.items.map((item, i) => i === idx ? { ...item, [key]: val } : item) }));

  const summary = { total: orders.length, draft: 0, sent: 0, received: 0, cancelled: 0 };
  orders.forEach(o => { if (o.status in summary) (summary as any)[o.status]++; });

  const filteredOrders = orders.filter(po => {
    const matchesSearch = !searchTerm || po.supplier.name.toLowerCase().includes(searchTerm.toLowerCase()) || (po.notes && po.notes.toLowerCase().includes(searchTerm.toLowerCase()));
    const matchesStatus = statusFilter === 'all' || po.status === statusFilter;
    const matchesSupplier = supplierFilter === 'all' || po.supplierId === supplierFilter;
    return matchesSearch && matchesStatus && matchesSupplier;
  });

  if (loading) return (
    <div style={{ display: 'flex', height: '100%', alignItems: 'center', justifyContent: 'center', flexDirection: 'column', gap: '1rem' }}>
      <RefreshCw className="animate-spin" size={32} color="var(--accent)" />
      <span style={{ fontSize: '0.9rem', color: 'var(--text-secondary)', fontWeight: 600 }}>Syncing Supply Chain...</span>
    </div>
  );

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '2rem', paddingBottom: '3rem', animation: 'fadeUp 0.4s ease-out' }}>

      {/* Header */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '1rem', borderBottom: '1px solid var(--border)', paddingBottom: '1.5rem' }}>
        <div>
          <h2 style={{ fontSize: '1.75rem', fontWeight: 800, color: 'var(--text-primary)', display: 'flex', gap: '0.75rem', alignItems: 'center', letterSpacing: '-0.02em' }}>
            <div style={{ padding: '0.5rem', background: 'var(--accent-soft)', borderRadius: '12px' }}><Truck className="text-accent" size={26}/></div>
            Procurement
          </h2>
          <p style={{ color: 'var(--text-secondary)', marginTop: '0.5rem', fontWeight: 500, fontSize: '0.9rem' }}>Purchase orders and external vendor logistics.</p>
        </div>

        <div style={{ display: 'flex', gap: '1rem' }}>
          <button 
            className="btn btn-secondary"
            style={{ borderRadius: '99px', padding: '0.75rem 1.5rem', display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.9rem' }}
            onClick={() => setShowSupplierModal(true)}
          >
            <Plus size={18} /> Add Supplier
          </button>
          <button 
            className="btn btn-primary"
            style={{ borderRadius: '99px', padding: '0.75rem 1.5rem', display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.9rem', boxShadow: '0 8px 20px rgba(0,0,0,0.1)' }}
            onClick={() => setShowPOModal(true)}
          >
            <Plus size={18} /> Create PO
          </button>
        </div>
      </div>

      {/* KPI Strip */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '1.25rem' }}>
        {(['draft', 'sent', 'received', 'cancelled'] as const).map(s => {
          const cfg = statusBadge[s];
          const Icon = cfg.icon;
          return (
            <div key={s} onClick={() => setTab('orders')} className="card" style={{ padding: '1.25rem', cursor: 'pointer', display: 'flex', flexDirection: 'column' }}>
              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '1rem' }}>
                <span style={{ fontSize: '0.75rem', fontWeight: 800, textTransform: 'uppercase', color: 'var(--text-muted)', letterSpacing: '0.05em' }}>{cfg.label}</span>
                <div style={{ width: '2rem', height: '2rem', borderRadius: '8px', background: cfg.bg, border: `1px solid ${cfg.border}`, display: 'flex', alignItems: 'center', justifyContent: 'center', color: cfg.color }}>
                  <Icon size={14} />
                </div>
              </div>
