                <span style={{ fontSize: '1.25rem', fontWeight: 900, color: 'var(--accent)', background: 'rgba(184, 134, 11, 0.1)', border: '1px solid var(--accent)', padding: '0.5rem 1rem', borderRadius: '8px' }}>
