                    borderRadius: '12px', 
                    fontSize: '0.8rem', 
                    fontWeight: 700,
                    textTransform: 'capitalize',
                    cursor: 'pointer',
                    background: 'var(--bg-deep)',
                    color: 'var(--text-primary)',
                    border: '1px solid var(--border)',
