                    backgroundRepeat: 'no-repeat',
                    backgroundPosition: 'right 0.75rem center',
                    backgroundSize: '1em',
                    outline: 'none',
                    boxShadow: 'var(--shadow-sm)'
                  }}
                >
                  {roomTypes.map(type => (
                    <option key={type} value={type} style={{ textTransform: 'capitalize' }}>
                      {type === 'all' ? 'All Categories' : type}
                    </option>
                  ))}
                </select>
              </div>
            </div>
          )}
