            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
              {bookings.map((booking, i) => {
                const statusColor = { confirmed: '#22c55e', checked_in: 'var(--accent)', checked_out: '#94a3b8', cancelled: '#ef4444' }[booking.status] || '#94a3b8';
                return (
                  <div key={booking.id} className="card" style={{ padding: '1.25rem 1.5rem', display: 'flex', alignItems: 'center', gap: '1.5rem', animationDelay: `${i * 0.05}s` }}>
                    <div style={{ width: 48, height: 48, borderRadius: '12px', background: 'var(--bg-deep)', border: '1px solid var(--border)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.5rem', flexShrink: 0 }}>🛏️</div>
                    <div style={{ flex: 1 }}>
                      <p style={{ fontWeight: 800, color: 'var(--text-primary)', fontSize: '1.1rem', marginBottom: '0.125rem' }}>{booking.guestName}</p>
                      <p style={{ fontSize: '0.85rem', color: 'var(--text-secondary)', fontWeight: 500 }}>
                        <span style={{ color: 'var(--text-primary)', fontWeight: 700 }}>Room {booking.room?.number}</span> ({booking.room?.type}) &nbsp;&bull;&nbsp; 
                        {new Date(booking.checkIn).toLocaleDateString()} &rarr; {new Date(booking.checkOut).toLocaleDateString()}
                      </p>
                    </div>
                    <div style={{ textAlign: 'right' }}>
                      <span style={{ display: 'inline-block', padding: '0.3rem 0.75rem', borderRadius: '99px', fontSize: '0.7rem', fontWeight: 800, background: `${statusColor}1a`, color: statusColor, textTransform: 'uppercase', letterSpacing: '0.05em', border: `1px solid ${statusColor}` }}>
                        {booking.status.replace('_', ' ')}
                      </span>
                      <p style={{ fontSize: '0.9rem', fontWeight: 800, color: 'var(--text-primary)', marginTop: '0.5rem' }}>
                        KES {booking.totalPrice?.toLocaleString()}
                      </p>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      )}

      {/* Booking Modal */}
      {showBookingModal && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.6)', backdropFilter: 'blur(12px)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 }}>
          <div className="card" style={{ width: '32rem', maxHeight: '90vh', overflowY: 'auto', padding: '2.5rem' }}>
            <h2 style={{ fontSize: '1.5rem', fontWeight: 800, color: 'var(--text-primary)', marginBottom: '1.5rem', letterSpacing: '-0.02em', display: 'flex', alignItems: 'center', gap: '0.625rem' }}>
              <Calendar size={24} color="var(--accent)" /> Establish Reservation
            </h2>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>
              <div>
                <label style={{ fontSize: '0.75rem', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.05em', color: 'var(--text-secondary)', display: 'block', marginBottom: '0.4rem' }}>Room Designation</label>
                <select className="form-input" style={{ padding: '0.875rem' }} value={bookingForm.roomId} onChange={e => setBookingForm(f => ({ ...f, roomId: e.target.value }))}>
                  <option value="">Select Room Selection...</option>
                  {rooms.filter(r => r.status === 'available').map(r => <option key={r.id} value={r.id}>Room {r.number} ({r.type})</option>)}
                </select>
              </div>
              <div>
                <label style={{ fontSize: '0.75rem', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.05em', color: 'var(--text-secondary)', display: 'block', marginBottom: '0.4rem' }}>Principal Guest</label>
                <input type="text" className="form-input" style={{ padding: '0.875rem' }} placeholder="Full formal name" value={bookingForm.guestName} onChange={e => setBookingForm(f => ({ ...f, guestName: e.target.value }))} />
              </div>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>
                <div>
                  <label style={{ fontSize: '0.75rem', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.05em', color: 'var(--text-secondary)', display: 'block', marginBottom: '0.4rem' }}>Arrival</label>
                  <input type="date" className="form-input" style={{ padding: '0.875rem' }} value={bookingForm.checkIn} onChange={e => setBookingForm(f => ({ ...f, checkIn: e.target.value }))} />
                </div>
                <div>
                  <label style={{ fontSize: '0.75rem', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.05em', color: 'var(--text-secondary)', display: 'block', marginBottom: '0.4rem' }}>Departure</label>
                  <input type="date" className="form-input" style={{ padding: '0.875rem' }} value={bookingForm.checkOut} onChange={e => setBookingForm(f => ({ ...f, checkOut: e.target.value }))} />
                </div>
              </div>
              <div>
                <label style={{ fontSize: '0.75rem', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.05em', color: 'var(--text-secondary)', display: 'block', marginBottom: '0.4rem' }}>Tariff (KES)</label>
                <input type="number" className="form-input" style={{ padding: '0.875rem' }} min={0} value={bookingForm.totalPrice || ''} placeholder="0" onChange={e => setBookingForm(f => ({ ...f, totalPrice: Number(e.target.value) }))} />
              </div>
              <div>
                <label style={{ fontSize: '0.75rem', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.05em', color: 'var(--text-secondary)', display: 'block', marginBottom: '0.4rem' }}>Requests / Notes</label>
                <textarea className="form-input" rows={3} value={bookingForm.notes} onChange={e => setBookingForm(f => ({ ...f, notes: e.target.value }))} style={{ resize: 'none', padding: '0.875rem' }} />
              </div>
            </div>
            <div style={{ display: 'flex', gap: '1rem', marginTop: '2rem' }}>
              <button className="btn btn-secondary" style={{ flex: 1 }} onClick={() => setShowBookingModal(false)}>Discard</button>
              <button className="btn btn-primary" style={{ flex: 1 }} onClick={handleCreateBooking}>Confirm Reservation</button>
            </div>
          </div>
        </div>
      )}


      {/* Rooms Grid View */}
      {activeTab === 'rooms' && (
        filteredRooms.length === 0 ? (
          <div className="card" style={{ padding: '4rem', textAlign: 'center', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '1rem' }}>
            <div style={{ width: 80, height: 80, borderRadius: '50%', background: 'var(--bg-deep)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
              <AlertCircle size={36} color="var(--text-muted)" />
            </div>
            <h3 style={{ fontSize: '1.25rem', fontWeight: 800, color: 'var(--text-primary)' }}>No inventory matching criteria</h3>
            <p style={{ color: 'var(--text-secondary)', fontWeight: 500 }}>Try altering your segment filters.</p>
            <button onClick={() => { setStatusFilter('all'); setTypeFilter('all'); }} className="btn btn-secondary" style={{ marginTop: '1rem' }}>Clear Filters</button>
          </div>
        ) : (
          <div className="dashboard-kpi-grid">
            {filteredRooms.map((room, i) => {
              const sc = statusColors[room.status];
              const isSelected = selectedRoom?.id === room.id;
              return (
                <div 
                  key={room.id}
                  onClick={() => setSelectedRoom(room)}
                  className="card"
                  style={{
                    padding: '1.5rem', cursor: 'pointer', display: 'flex', flexDirection: 'column', 
                    animationDelay: `${(i % 12) * 0.05}s`,
                    boxShadow: isSelected ? `0 0 0 2px white, 0 0 0 4px ${sc.border}, 0 20px 40px rgba(0,0,0,0.1)` : undefined,
                    transform: isSelected ? 'translateY(-4px)' : undefined,
                    borderColor: isSelected ? sc.border : undefined,
                  }}
                >
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '1.25rem' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '0.375rem', background: sc.bg, border: `1px solid ${sc.border}`, color: sc.text, padding: '0.2rem 0.6rem', borderRadius: '99px', fontSize: '0.65rem', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.05em' }}>
                      {statusIcons[room.status]} {room.status}
                    </div>
                    <MoreVertical size={16} color="var(--text-muted)" />
                  </div>

                  <div style={{ marginBottom: '1.5rem' }}>
                    <p style={{ fontSize: '2.5rem', fontWeight: 900, color: 'var(--text-primary)', letterSpacing: '-0.05em', lineHeight: 1 }}>#{room.number}</p>
                    <p style={{ fontSize: '0.75rem', fontWeight: 800, color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.05em', marginTop: '0.4rem' }}>{room.type}</p>
                  </div>

                  <div style={{ marginTop: 'auto', borderTop: '1px solid var(--border)', paddingTop: '1rem' }}>
                    {room.status === 'occupied' ? (
                      <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
                        <p style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.9rem', fontWeight: 800, color: 'var(--text-primary)', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                           <div style={{ background: 'var(--accent-soft)', width: 20, height: 20, borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center' }}><User size={12} color="var(--accent)" /></div> 
                           {room.guestName}
                        </p>
                        {room.roomCharges.length > 0 && (
                          <p style={{ display: 'flex', alignItems: 'center', gap: '0.375rem', fontSize: '0.75rem', fontWeight: 800, color: 'var(--accent)', textTransform: 'uppercase', letterSpacing: '0.05em' }}>
                            <Banknote size={12} /> TAB: {tenant?.currency} {room.roomCharges.reduce((sum, c) => sum + Number(c.amount), 0).toLocaleString()}
                          </p>
                        )}
                      </div>
                    ) : room.status === 'maintenance' ? (
                      <span style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.8rem', fontWeight: 700, color: '#ef4444' }}>
                         <AlertCircle size={14}/> Action Required
                      </span>
                    ) : (
                      <span style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.8rem', fontWeight: 700, color: 'var(--text-muted)' }}>
                         <Bed size={14}/> Ready for allocation
                      </span>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        )
      )}

      {/* Create Room Modal */}
      {showRoomModal && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.6)', backdropFilter: 'blur(12px)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 }}>
          <div className="card" style={{ width: '30rem', padding: '2.5rem' }}>
            <h2 style={{ fontSize: '1.5rem', fontWeight: 900, color: 'var(--text-primary)', marginBottom: '1.5rem', letterSpacing: '-0.02em', display: 'flex', alignItems: 'center', gap: '0.625rem' }}>
              <Bed size={24} color="var(--accent)" /> Establish New Room
            </h2>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>
              <div className="responsive-grid">
                <div>
                  <label style={{ fontSize: '0.75rem', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.05em', color: 'var(--text-secondary)', display: 'block', marginBottom: '0.4rem' }}>Room Identifier</label>
                  <input type="text" className="form-input" style={{ padding: '0.875rem' }} placeholder="e.g. 501" value={roomForm.number} onChange={e => setRoomForm(f => ({ ...f, number: e.target.value }))} />
                </div>
                <div>
                  <label style={{ fontSize: '0.75rem', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.05em', color: 'var(--text-secondary)', display: 'block', marginBottom: '0.4rem' }}>Floor Level</label>
                  <input type="number" className="form-input" style={{ padding: '0.875rem' }} placeholder="e.g. 5" value={roomForm.floor} onChange={e => setRoomForm(f => ({ ...f, floor: e.target.value }))} />
                </div>
              </div>
              <div>
                <label style={{ fontSize: '0.75rem', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.05em', color: 'var(--text-secondary)', display: 'block', marginBottom: '0.4rem' }}>Room Category / Type</label>
                <input type="text" list="room-types" className="form-input" style={{ padding: '0.875rem' }} placeholder="Type new or select existing" value={roomForm.type} onChange={e => setRoomForm(f => ({ ...f, type: e.target.value }))} />
                <datalist id="room-types">
                  {roomTypes.filter(t => t !== 'all').map(t => <option key={t} value={t} />)}
                </datalist>
                <p style={{ fontSize: '0.75rem', color: 'var(--text-muted)', marginTop: '0.5rem', fontWeight: 600 }}>Tip: Creating a new category here automatically adds it to the system filters.</p>
              </div>
            </div>
            <div style={{ display: 'flex', gap: '1rem', marginTop: '2rem' }}>
              <button className="btn btn-secondary" style={{ flex: 1 }} onClick={() => setShowRoomModal(false)}>Cancel</button>
              <button className="btn btn-primary" style={{ flex: 1 }} onClick={handleCreateRoom}>Confirm Creation</button>
            </div>
          </div>
        </div>
      )}

      {/* Room Detail Sidebar Interface (Glassmorphic) */}
      {selectedRoom && createPortal(
        <div style={{ position: 'fixed', inset: 0, zIndex: 100, display: 'flex', justifyContent: 'flex-end', background: 'rgba(0,0,0,0.4)', backdropFilter: 'blur(8px)' }}>
          <div style={{ position: 'absolute', inset: 0 }} onClick={() => setSelectedRoom(null)}></div>

          <div className="glass" style={{ width: '100%', maxWidth: '28rem', height: '100%', display: 'flex', flexDirection: 'column', animation: 'slideLeft 0.4s cubic-bezier(0.16, 1, 0.3, 1)', borderRight: 'none', borderTop: 'none', borderBottom: 'none', borderRadius: '24px 0 0 24px' }}>

            <div style={{ padding: '2.5rem 2.5rem 1.5rem', borderBottom: '1px solid var(--border)', display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
              <div>
                <p style={{ fontSize: '0.75rem', fontWeight: 800, color: 'var(--accent)', textTransform: 'uppercase', letterSpacing: '0.1em', marginBottom: '0.25rem' }}>{selectedRoom.type} &bull; Lvl {Math.floor(Number(selectedRoom.number)/100)}</p>
                <h3 style={{ fontSize: '2.5rem', fontWeight: 900, color: 'var(--text-primary)', letterSpacing: '-0.04em', lineHeight: 1 }}>Room {selectedRoom.number}</h3>
              </div>
              <button 
                onClick={() => setSelectedRoom(null)}
                style={{ background: 'var(--bg-elevated)', border: '1px solid var(--border)', width: '3rem', height: '3rem', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', color: 'var(--text-secondary)', boxShadow: 'var(--shadow-sm)', transition: 'all 0.2s' }}
              >
                <XCircle size={24} />
              </button>
            </div>

            <div style={{ flex: 1, overflowY: 'auto', padding: '2.5rem', display: 'flex', flexDirection: 'column', gap: '2rem' }}>
              {/* Status Section */}
              <div>
                <h4 style={{ fontSize: '0.7rem', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.1em', color: 'var(--text-muted)', marginBottom: '0.75rem', borderBottom: '1px solid var(--border)', paddingBottom: '0.5rem' }}>System Status</h4>
                <div style={{ padding: '1rem', borderRadius: '16px', border: `1px solid ${statusColors[selectedRoom.status].border}`, background: statusColors[selectedRoom.status].bg, display: 'flex', alignItems: 'center', gap: '1rem' }}>
                  <div style={{ background: 'rgba(255,255,255,0.7)', padding: '0.75rem', borderRadius: '12px', color: statusColors[selectedRoom.status].text }}>
                    {statusIcons[selectedRoom.status]}
                  </div>
                  <span style={{ fontWeight: 800, textTransform: 'capitalize', fontSize: '1.1rem', color: statusColors[selectedRoom.status].text }}>{selectedRoom.status}</span>
                </div>
              </div>

              {selectedRoom.status === 'occupied' ? (
                <>
                  <div>
                    <h4 style={{ fontSize: '0.7rem', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.1em', color: 'var(--text-muted)', marginBottom: '0.75rem', borderBottom: '1px solid var(--border)', paddingBottom: '0.5rem' }}>Current Guest</h4>
                    <div style={{ background: 'var(--bg-elevated)', border: '1px solid var(--border)', padding: '1.5rem', borderRadius: '20px', display: 'flex', flexDirection: 'column', gap: '1rem', boxShadow: 'var(--shadow-sm)' }}>
                      <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
                        <div style={{ width: '3.5rem', height: '3.5rem', borderRadius: '50%', background: 'var(--accent)', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'white' }}><User size={24} /></div>
                        <div>
                          <p style={{ fontSize: '0.7rem', fontWeight: 800, color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.05em' }}>Primary Occupant</p>
                          <p style={{ fontSize: '1.25rem', fontWeight: 900, color: 'var(--text-primary)', letterSpacing: '-0.01em' }}>{selectedRoom.guestName}</p>
                        </div>
                      </div>
                      <div style={{ borderTop: '1px solid var(--border)', paddingTop: '1rem', display: 'flex', alignItems: 'center', gap: '0.5rem', color: 'var(--text-secondary)' }}>
                        <Calendar size={16} />
                        <span style={{ fontSize: '0.85rem', fontWeight: 700 }}>Arrived: {selectedRoom.checkedInAt ? new Date(selectedRoom.checkedInAt).toLocaleDateString(undefined, { weekday: 'short', month: 'short', day: 'numeric' }) : 'N/A'}</span>
                      </div>
                    </div>
                  </div>

                  <div>
                    <h4 style={{ fontSize: '0.7rem', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.1em', color: 'var(--text-muted)', marginBottom: '0.75rem', borderBottom: '1px solid var(--border)', paddingBottom: '0.5rem' }}>Room Folio</h4>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
                      {!selectedRoom.roomCharges || selectedRoom.roomCharges.length === 0 ? (
                        <div style={{ textAlign: 'center', padding: '2rem', background: 'var(--bg-deep)', borderRadius: '16px', border: '1px dashed var(--border)' }}>
                          <p style={{ fontSize: '0.85rem', fontWeight: 700, color: 'var(--text-muted)' }}>Zero outstanding folio charges.</p>
                        </div>
                      ) : (
                        selectedRoom.roomCharges.map(charge => (
                          <div key={charge.id} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '1.25rem', background: 'var(--bg-elevated)', border: '1px solid var(--border)', borderRadius: '16px', boxShadow: 'var(--shadow-sm)' }}>
                            <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
                              <div style={{ width: '2.5rem', height: '2.5rem', borderRadius: '10px', background: 'var(--accent-soft)', color: 'var(--accent)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}><Banknote size={16}/></div>
                              <div>
                                <p style={{ fontSize: '0.95rem', fontWeight: 800, color: 'var(--text-primary)' }}>{charge.order?.orderNumber}</p>
                                <p style={{ fontSize: '0.7rem', fontWeight: 700, color: 'var(--text-muted)' }}>{charge.order?.createdAt ? new Date(charge.order.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : ''}</p>
                              </div>
                            </div>
                            <span style={{ fontSize: '1.1rem', fontWeight: 900, color: 'var(--text-primary)' }}>{tenant?.currency} {Number(charge.amount).toLocaleString()}</span>
                          </div>
                        ))
                      )}
                    </div>
                  </div>
                </>
              ) : (
                <div style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', background: 'var(--bg-deep)', borderRadius: '24px', border: '1px dashed var(--border)', padding: '2rem', textAlign: 'center' }}>
                  <div style={{ width: '5rem', height: '5rem', borderRadius: '50%', background: 'var(--bg-elevated)', border: '1px solid var(--border)', display: 'flex', alignItems: 'center', justifyContent: 'center', boxShadow: 'var(--shadow-sm)', marginBottom: '1.5rem' }}>
                    <Settings size={32} color="var(--text-muted)" />
                  </div>
                  <p style={{ fontSize: '1.1rem', fontWeight: 800, color: 'var(--text-primary)', marginBottom: '0.5rem' }}>Awaiting Allocation</p>
                  <p style={{ fontSize: '0.85rem', color: 'var(--text-secondary)', fontWeight: 500, marginBottom: '2rem' }}>Room is prepped and flagged available in the system.</p>

                  <button 
                    onClick={() => {
                      setBookingForm(f => ({ ...f, roomId: selectedRoom.id }));
                      setShowBookingModal(true);
                      setSelectedRoom(null); // Close panel to show modal clearly
                    }}
                    className="btn-primary" 
                    style={{ padding: '0.875rem 2rem', borderRadius: '12px', fontSize: '0.95rem', fontWeight: 800, display: 'flex', gap: '0.5rem', alignItems: 'center' }}
                  >
                    <Plus size={18} /> Book This Room
                  </button>
                </div>
              )}
            </div>


            {selectedRoom.status === 'occupied' && (
              <div style={{ padding: '2rem 2.5rem', background: 'var(--bg-elevated)', borderTop: '1px solid var(--border)', borderBottomLeftRadius: '24px' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', marginBottom: '1.5rem' }}>
                  <span style={{ fontSize: '0.75rem', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.1em', color: 'var(--text-muted)' }}>Folio Balance</span>
                  <span style={{ fontSize: '2.5rem', fontWeight: 900, color: 'var(--accent)', letterSpacing: '-0.04em', lineHeight: 1 }}>
                    <span style={{ fontSize: '1.25rem', color: 'var(--text-muted)', marginRight: '0.25rem', verticalAlign: 'top' }}>{tenant?.currency}</span>
                    {(selectedRoom.roomCharges || []).reduce((sum, c) => sum + Number(c.amount), 0).toLocaleString()}
                  </span>
                </div>

                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '0.75rem', marginBottom: '1.5rem' }}>
                  {(['cash', 'card', 'mpesa'] as const).map(m => (
                    <button 
                      key={m}
                      onClick={() => setCheckoutMethod(m)}
                      style={{
                        padding: '1rem 0', borderRadius: '12px', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '0.5rem', fontWeight: 800, textTransform: 'uppercase', fontSize: '0.7rem', letterSpacing: '0.05em', border: '2px solid', transition: 'all 0.2s', cursor: 'pointer',
                        background: checkoutMethod === m ? 'var(--bg-elevated)' : 'var(--bg-deep)',
                        borderColor: checkoutMethod === m ? 'var(--bg-inverted)' : 'transparent',
                        color: checkoutMethod === m ? 'var(--text-primary)' : 'var(--text-secondary)',
                      }}
                    >
                      {m === 'cash' ? <Banknote size={20}/> : m === 'card' ? <CreditCard size={20}/> : <Smartphone size={20}/>}
                      {m}
                    </button>
                  ))}
                </div>

                <button 
                  onClick={handleCheckout} disabled={isCheckingOut} className="btn btn-primary"
                  style={{ width: '100%', padding: '1.25rem', fontSize: '1rem', fontWeight: 800, borderRadius: '16px', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.75rem' }}
                >
                  {isCheckingOut ? <Loader2 className="animate-spin" size={20} /> : <><LogOut size={20} /> Finalize Checkout</>}
                </button>
              </div>
            )}
          </div>

          <style>{`
            @keyframes slideLeft {
              from { transform: translateX(100%); opacity: 0; }
              to { transform: translateX(0); opacity: 1; }
            }
          `}</style>
        </div>,
        document.body
      )}
    </div>
  );
};

export default Rooms;

import React, { useState, useEffect, useCallback } from 'react';
import {
  User, Bell, Palette, ShoppingBag, Shield, Globe,
  Loader2, Monitor, Smartphone, Sun, Moon, ChevronRight, ArrowLeft,
  CreditCard, Banknote, Smartphone as Phone, Building2,
  CheckCircle2, AlertCircle, X as XIcon, UserPlus, Lock, Trash2, Users
} from 'lucide-react';
import api from '../api';
import { useAuth } from '../context/AuthContext';

const SECTIONS = [
  { id: 'profile', label: 'Identity', icon: User },
  { id: 'team', label: 'Team & Staff', icon: Users },
  { id: 'notifications', label: 'Alerts', icon: Bell },
  { id: 'appearance', label: 'Vibe', icon: Palette },
  { id: 'checkout', label: 'POS Flow', icon: ShoppingBag },
  { id: 'mpesa', label: 'M-Pesa', icon: Smartphone },
  { id: 'security', label: 'Vault', icon: Shield },
  { id: 'language', label: 'Region', icon: Globe },
];

const Toggle = ({ checked, onChange }: { checked: boolean; onChange: (v: boolean) => void }) => (
  <button
    onClick={() => onChange(!checked)}
    style={{
      position: 'relative', width: '3.5rem', height: '1.8rem', flexShrink: 0,
      borderRadius: '99px', border: 'none', cursor: 'pointer',
      background: checked ? 'var(--accent)' : '#e2e8f0',
      transition: 'all 0.4s cubic-bezier(0.16, 1, 0.3, 1)', padding: 0,
    }}
  >
    <span style={{
      position: 'absolute', top: '4px',
      left: checked ? 'calc(100% - 25px)' : '4px',
      width: '21px', height: '21px', borderRadius: '50%',
      background: 'var(--bg-elevated)', transition: 'all 0.4s cubic-bezier(0.16, 1, 0.3, 1)',
      boxShadow: '0 2px 6px rgba(0,0,0,0.1)'
    }} />
  </button>
);

const DEFAULT_PREFS = {
  notifications: {
    newMessages: { push: true, email: false },
    weeklyReport: { push: true, email: true },
    paymentSuccess: { push: false, email: true },
    billingAlert: { push: true, email: false },
    newInventory: { push: false, email: true },
  },
  theme: 'light',
  checkout: {
    enableCard: true,
    enableCash: true,
    enableMpesa: true,
    enableRoomCharge: true,
  },
  currency: 'KES',
  timezone: 'Africa/Nairobi',
  language: 'English',
};

const Settings: React.FC = () => {
  const { user } = useAuth();
  const [activeSection, setActiveSection] = useState('profile');
  const [loading, setLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [saveMsg, setSaveMsg] = useState('');

  // Tenant data (profile section)
  const [tenantData, setTenantData] = useState({
    name: '', currency: 'KES', taxRate: 16, receiptFooter: ''
  });
  const [profileName, setProfileName] = useState('');
  const [userStats, setUserStats] = useState({ totalOrders: 0, totalRevenue: 0, memberSince: '' });

  // Preferences (loaded from backend)
  const [prefs, setPrefs] = useState(DEFAULT_PREFS);

  // M-Pesa config state
  const [mpesaConfig, setMpesaConfig] = useState({
    mpesaConsumerKey: '', mpesaConsumerSecret: '', mpesaShortcode: '',
    mpesaPasskey: '', mpesaTillDisplay: ''
  });
  const [mpesaConfigured, setMpesaConfigured] = useState(false);
  const [isSavingMpesa, setIsSavingMpesa] = useState(false);
  const [mpesaSaveMsg, setMpesaSaveMsg] = useState('');

  // Team Management state
  const [teamUsers, setTeamUsers] = useState<any[]>([]);
  const [showAddUserModal, setShowAddUserModal] = useState(false);
  const [newUser, setNewUser] = useState({ name: '', email: '', role: 'cashier', password: '' });
  const [isAddingUser, setIsAddingUser] = useState(false);
  const [teamMsg, setTeamMsg] = useState('');

  // Active Sessions State
  const [sessions, setSessions] = useState<any[]>([]);

  const fetchAll = useCallback(async () => {
    if (!user?.tenantId) return;
    try {
      // 1. Fetch Core Tenant Settings (Critical)
      const [settingsRes, prefsRes, statsRes] = await Promise.all([
        api.get(`/tenants/${user.tenantId}/settings`),
        api.get(`/tenants/${user.tenantId}/users/me/preferences`),
        api.get(`/tenants/${user.tenantId}/users/me/stats`),
      ]);

      // 2. Fetch Team Users (Optional, Admin Only)
      try {
        if ((user?.role as string) === 'hotel_admin' || (user?.role as string) === 'manager') {
          const usersRes = await api.get(`/tenants/${user.tenantId}/users`);
          if (usersRes?.data) setTeamUsers(usersRes.data);
        }
      } catch (userErr) {
        console.error('Failed to fetch team users:', userErr);
      }

      // 3. Fetch Active Security Sessions
      try {
        const sessRes = await api.get(`/tenants/${user.tenantId}/users/me/sessions`);
        if (sessRes?.data) setSessions(sessRes.data);
      } catch (sessErr) {
        console.error('Failed to fetch sessions:', sessErr);
      }

      // Pre-populate visible (non-secret) M-Pesa fields
      const s = settingsRes.data;
      setMpesaConfig(prev => ({
        ...prev,
        mpesaTillDisplay: s.mpesaTillDisplay || '',
        mpesaShortcode: s.mpesaShortcode || '',
        // keys/passkey deliberately left blank — never sent back from server
      }));
      setMpesaConfigured(!!(s.mpesaConsumerKey && s.mpesaShortcode));

      setTenantData({
        name: settingsRes.data.name || '',
        currency: settingsRes.data.currency || 'KES',
        taxRate: settingsRes.data.taxRate || 16,
        receiptFooter: settingsRes.data.receiptFooter || '',
      });
      setProfileName(user?.name || '');

      // Merge saved preferences with defaults
      const savedPrefs = prefsRes.data || {};
      const loadedTheme = savedPrefs.theme || 'light';

      setPrefs(prev => ({
        notifications: savedPrefs.notifications || prev.notifications,
        theme: loadedTheme,
        checkout: savedPrefs.checkout || prev.checkout,
        currency: savedPrefs.currency || settingsRes.data.currency || prev.currency,
        timezone: savedPrefs.timezone || prev.timezone,
        language: savedPrefs.language || prev.language,
      }));

      // Instantly apply the loaded theme
      localStorage.setItem('app_theme', loadedTheme);
      if (loadedTheme === 'dark') {
        document.documentElement.classList.add('dark');
      } else {
        document.documentElement.classList.remove('dark');
      }

      if (statsRes.data) {
        setUserStats({
          totalOrders: statsRes.data.totalOrders || 0,
          totalRevenue: statsRes.data.totalRevenue || 0,
          memberSince: statsRes.data.memberSince || '',
        });
      }
    } catch (err) {
      console.error('Failed to load settings', err);
    } finally {
      setLoading(false);
    }
  }, [user?.tenantId, user?.name]);

  useEffect(() => { fetchAll(); }, [fetchAll]);

  const savePrefs = async (updates: Partial<typeof prefs>) => {
    setIsSaving(true); setSaveMsg('');
    try {
      await api.patch(`/tenants/${user?.tenantId}/users/me/preferences`, updates);
      setPrefs(prev => ({ ...prev, ...updates }));
      setSaveMsg('Saved!');
      setTimeout(() => setSaveMsg(''), 2500);
    } catch { setSaveMsg('Save failed'); }
    finally { setIsSaving(false); }
  };

  const saveTenant = async () => {
    setIsSaving(true); setSaveMsg('');
    try {
      await api.patch(`/tenants/${user?.tenantId}/settings`, tenantData);
      await api.put(`/tenants/${user?.tenantId}/users/profile`, { name: profileName });
      setSaveMsg('Saved!');
      setTimeout(() => setSaveMsg(''), 2500);
    } catch { setSaveMsg('Save failed'); }
    finally { setIsSaving(false); }
  };

  if (loading) return (
    <div style={{ display: 'flex', height: '100%', alignItems: 'center', justifyContent: 'center', flexDirection: 'column', gap: '1rem' }}>
      <Loader2 className="animate-spin" size={32} color="var(--accent)" />
      <span style={{ fontSize: '0.9rem', color: 'var(--text-secondary)', fontWeight: 600 }}>Loading Settings...</span>
    </div>
  );

  const labelStyle: React.CSSProperties = {
    fontSize: '0.72rem', fontWeight: 900, textTransform: 'uppercase',
    letterSpacing: '0.12em', color: '#94a3b8', marginBottom: '0.75rem', display: 'block'
  };

  const SaveBar = () => (
    <div style={{ display: 'flex', justifyContent: 'flex-end', alignItems: 'center', gap: '1.5rem', marginTop: '3rem', paddingTop: '2rem', borderTop: '1px solid var(--border)' }}>
      {saveMsg && <span style={{ fontSize: '0.95rem', fontWeight: 800, color: saveMsg === 'Saved!' ? '#10b981' : '#f43f5e' }}>{saveMsg}</span>}
      <button onClick={saveTenant} className="btn btn-primary" style={{ height: '56px', minWidth: '200px', borderRadius: '16px', fontSize: '1rem', fontWeight: 900 }}>
        {isSaving ? <Loader2 size={20} className="animate-spin" /> : 'Save Changes'}
      </button>
    </div>
  );

  const renderSection = () => {
    switch (activeSection) {

      case 'profile':
        return (
          <div style={{ animation: 'fadeUp 0.4s ease-out' }}>
            <h3 style={{ fontSize: '1.75rem', fontWeight: 900, marginBottom: '2.5rem', letterSpacing: '-0.03em' }}>Identity & Access</h3>
            <div style={{ display: 'flex', gap: '3rem', flexWrap: 'wrap' }}>
              {/* Avatar card */}
              <div style={{ width: '260px', borderRadius: '28px', padding: '2rem', textAlign: 'center', flexShrink: 0, background: 'var(--bg-deep)', border: '1px solid var(--border)' }}>
                <div style={{ width: '7rem', height: '7rem', borderRadius: '50%', background: 'var(--accent)', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 1.25rem', fontSize: '2.5rem', border: '4px solid white', boxShadow: '0 8px 24px var(--accent-glow)' }}>
                  <span style={{ color: 'white', fontWeight: 900 }}>{profileName?.charAt(0) || '?'}</span>
                </div>
                <p style={{ fontWeight: 900, fontSize: '1.2rem', marginBottom: '0.25rem' }}>{profileName}</p>
                <p style={{ fontSize: '0.85rem', color: 'var(--text-secondary)', fontWeight: 700, textTransform: 'capitalize', marginBottom: '1.5rem' }}>{user?.role?.replace('_', ' ')}</p>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1px 1fr', gap: '0', background: 'var(--bg-elevated)', borderRadius: '20px', border: '1px solid var(--border)', padding: '1rem', marginBottom: '1rem' }}>
                  <div style={{ textAlign: 'center' }}>
                    <p style={{ fontWeight: 900, fontSize: '1.25rem', color: 'var(--accent)' }}>{userStats.totalOrders.toLocaleString()}</p>
                    <p style={{ fontSize: '0.7rem', color: 'var(--text-muted)', fontWeight: 800 }}>Orders</p>
                  </div>
                  <div style={{ background: '#e2e8f0' }} />
                  <div style={{ textAlign: 'center' }}>
                    <p style={{ fontWeight: 900, fontSize: '1.25rem', color: 'var(--accent)' }}>{(userStats.totalRevenue / 1000).toFixed(1)}k</p>
                    <p style={{ fontSize: '0.7rem', color: 'var(--text-muted)', fontWeight: 800 }}>Revenue</p>
                  </div>
                </div>
                <p style={{ fontSize: '0.75rem', color: 'var(--text-muted)', fontWeight: 700 }}>
                  Member since {userStats.memberSince ? new Date(userStats.memberSince).toLocaleDateString('en-US', { month: 'short', year: 'numeric' }) : '—'}
                </p>
              </div>

              {/* Fields */}
              <div style={{ flex: 1, minWidth: '300px', display: 'flex', flexDirection: 'column', gap: '1.75rem' }}>
                <div>
                  <label style={labelStyle}>Full Name</label>
                  <input type="text" className="form-input" style={{ height: '56px', borderRadius: '14px', fontWeight: 800, background: 'var(--bg-deep)' }} value={profileName} onChange={e => setProfileName(e.target.value)} />
                </div>
                <div>
                  <label style={labelStyle}>Hotel / Business Name</label>
                  <input type="text" className="form-input" style={{ height: '56px', borderRadius: '14px', fontWeight: 800, background: 'var(--bg-deep)' }} value={tenantData.name} onChange={e => setTenantData({ ...tenantData, name: e.target.value })} />
                </div>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1.25rem' }}>
                  <div>
                    <label style={labelStyle}>Currency</label>
                    <input type="text" className="form-input" style={{ height: '56px', borderRadius: '14px', fontWeight: 900, textAlign: 'center', background: 'var(--bg-deep)' }} value={tenantData.currency} onChange={e => setTenantData({ ...tenantData, currency: e.target.value.toUpperCase() })} />
                  </div>
                  <div>
                    <label style={labelStyle}>Tax Rate (%)</label>
                    <input type="number" className="form-input" style={{ height: '56px', borderRadius: '14px', fontWeight: 900, textAlign: 'center', background: 'var(--bg-deep)' }} value={tenantData.taxRate} onChange={e => setTenantData({ ...tenantData, taxRate: Number(e.target.value) })} />
                  </div>
                </div>
                <div>
                  <label style={labelStyle}>Receipt Footer Message</label>
                  <input type="text" className="form-input" style={{ height: '56px', borderRadius: '14px', fontWeight: 700, background: 'var(--bg-deep)' }} value={tenantData.receiptFooter} onChange={e => setTenantData({ ...tenantData, receiptFooter: e.target.value })} placeholder="Thank you for your visit!" />
                </div>
              </div>
            </div>
            <SaveBar />
          </div>
        );

      case 'team':
        return (
          <div style={{ animation: 'fadeUp 0.4s ease-out' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '2.5rem' }}>
              <h3 style={{ fontSize: '1.75rem', fontWeight: 900, letterSpacing: '-0.03em' }}>Team & Staff</h3>
              <button onClick={() => setShowAddUserModal(true)} className="btn btn-primary" style={{ display: 'flex', alignItems: 'center', gap: '8px', height: '44px', borderRadius: '12px', padding: '0 1.25rem' }}>
                <UserPlus size={18} /> Add Staff
              </button>
            </div>
            <p style={{ fontSize: '1rem', color: 'var(--text-secondary)', marginBottom: '2rem', fontWeight: 600 }}>Manage employee accounts, roles, and access credentials for your system.</p>

            {teamMsg && <p style={{ marginBottom: '1.5rem', fontWeight: 800, color: teamMsg.includes('failed') || teamMsg.includes('error') ? '#f43f5e' : '#10b981' }}>{teamMsg}</p>}

            <div style={{ border: '1px solid var(--border)', borderRadius: '20px', overflow: 'hidden' }}>
              <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
                <thead style={{ background: 'var(--bg-deep)' }}>
                  <tr>
                    <th style={{ padding: '1.25rem 1.5rem', fontSize: '0.75rem', fontWeight: 900, color: '#94a3b8', textTransform: 'uppercase', letterSpacing: '0.1em' }}>Name</th>
                    <th style={{ padding: '1.25rem 1.5rem', fontSize: '0.75rem', fontWeight: 900, color: '#94a3b8', textTransform: 'uppercase', letterSpacing: '0.1em' }}>Role</th>
                    <th style={{ padding: '1.25rem 1.5rem', fontSize: '0.75rem', fontWeight: 900, color: '#94a3b8', textTransform: 'uppercase', letterSpacing: '0.1em', textAlign: 'center' }}>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {teamUsers.map((u) => (
                    <tr key={u.id} style={{ borderTop: '1px solid var(--border)', background: 'var(--bg-elevated)' }}>
                      <td style={{ padding: '1.25rem 1.5rem' }}>
                        <p style={{ fontWeight: 800, fontSize: '0.95rem' }}>{u.name} {u.id === user?.id && <span style={{ marginLeft: '8px', fontSize: '0.65rem', background: 'var(--accent)', color: 'white', padding: '2px 8px', borderRadius: '99px' }}>YOU</span>}</p>
                        <p style={{ fontSize: '0.8rem', color: 'var(--text-muted)' }}>{u.email}</p>
                      </td>
                      <td style={{ padding: '1.25rem 1.5rem' }}>
                        <span style={{ fontSize: '0.75rem', fontWeight: 800, padding: '4px 10px', borderRadius: '8px', textTransform: 'uppercase', background: u.role === 'hotel_admin' ? '#fce7f3' : u.role === 'manager' ? '#e0e7ff' : '#f1f5f9', color: u.role === 'hotel_admin' ? '#be185d' : u.role === 'manager' ? '#4338ca' : '#475569' }}>
                          {u.role.replace('_', ' ')}
                        </span>
                      </td>
                      <td style={{ padding: '1.25rem 1.5rem', textAlign: 'center' }}>
                        {u.id !== user?.id && u.role !== 'super_admin' && (
                          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.5rem' }}>
                            <button onClick={async () => {
                              const newPass = prompt(`Enter new password for ${u.name}`);
                              if (!newPass) return;
                              if (newPass.length < 6) return alert('Password must be at least 6 characters');
                              try {
                                await api.patch(`/tenants/${user?.tenantId}/users/${u.id}/password`, { password: newPass });
                                setTeamMsg('✓ Password safely reset!');
                                setTimeout(() => setTeamMsg(''), 3000);
                              } catch { setTeamMsg('Reset failed'); }
                            }} style={{ border: 'none', background: '#f1f5f9', color: '#64748b', padding: '8px', borderRadius: '8px', cursor: 'pointer' }} title="Reset Password">
                              <Lock size={16} />
                            </button>
                            <button onClick={async () => {
                              if (!window.confirm(`Are you sure you want to permanently delete ${u.name}?`)) return;
                              try {
                                await api.delete(`/tenants/${user?.tenantId}/users/${u.id}`);
                                setTeamUsers(teamUsers.filter(x => x.id !== u.id));
                                setTeamMsg('✓ Account permanently deleted');
                                setTimeout(() => setTeamMsg(''), 3000);
                              } catch { setTeamMsg('Deletion failed'); }
                            }} style={{ border: 'none', background: '#fff1f2', color: '#f43f5e', padding: '8px', borderRadius: '8px', cursor: 'pointer' }} title="Delete Account">
                              <Trash2 size={16} />
                            </button>
                          </div>
                        )}
                      </td>
                    </tr>
                  ))}
                  {teamUsers.length === 0 && (
                    <tr><td colSpan={3} style={{ padding: '2rem', textAlign: 'center', color: 'var(--text-muted)' }}>No staff members found.</td></tr>
                  )}
                </tbody>
              </table>
            </div>

            {showAddUserModal && (
              <div style={{ position: 'fixed', inset: 0, zIndex: 9999, display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'rgba(0,0,0,0.4)', backdropFilter: 'blur(4px)' }}>
                <div style={{ background: 'var(--bg-elevated)', borderRadius: '24px', padding: '2.5rem', width: '90%', maxWidth: '440px', boxShadow: '0 25px 50px -12px rgba(0,0,0,0.25)', animation: 'fadeUp 0.3s ease-out' }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '2rem' }}>
                    <h3 style={{ fontSize: '1.5rem', fontWeight: 900 }}>Create Staff Account</h3>
                    <button onClick={() => setShowAddUserModal(false)} style={{ background: 'none', border: 'none', cursor: 'pointer', color: 'var(--text-muted)' }}><XIcon size={24} /></button>
                  </div>

                  <div style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>
                    <div>
                      <label style={labelStyle}>Full Name</label>
                      <input type="text" className="form-input" style={{ background: 'var(--bg-deep)' }} value={newUser.name} onChange={e => setNewUser({...newUser, name: e.target.value})} placeholder="Jane Doe" />
                    </div>
                    <div>
                      <label style={labelStyle}>Email Address (Login ID)</label>
                      <input type="email" className="form-input" style={{ background: 'var(--bg-deep)' }} value={newUser.email} onChange={e => setNewUser({...newUser, email: e.target.value})} placeholder="jane@example.com" />
                    </div>
                    <div>
                      <label style={labelStyle}>Initial Password (Min 6 chars)</label>
                      <input type="password" className="form-input" style={{ background: 'var(--bg-deep)' }} value={newUser.password} onChange={e => setNewUser({...newUser, password: e.target.value})} />
                    </div>
                    <div>
                      <label style={labelStyle}>Role</label>
                      <select className="form-input" style={{ background: 'var(--bg-deep)' }} value={newUser.role} onChange={e => setNewUser({...newUser, role: e.target.value})}>
                        <option value="cashier">Cashier</option>
                        <option value="manager">Manager</option>
                        <option value="hotel_admin">Hotel Admin</option>
                      </select>
                    </div>

                    <button 
                      className="btn btn-primary" 
                      style={{ marginTop: '1rem', height: '52px' }}
                      disabled={isAddingUser || !newUser.name || !newUser.email || newUser.password.length < 6}
                      onClick={async () => {
                        setIsAddingUser(true);
                        try {
                          const res = await api.post(`/tenants/${user?.tenantId}/users`, newUser);
                          setTeamUsers([...teamUsers, res.data]);
                          setShowAddUserModal(false);
                          setNewUser({ name: '', email: '', role: 'cashier', password: '' });
                          setTeamMsg('✓ New staff member successfully created!');
                          setTimeout(() => setTeamMsg(''), 3000);
                        } catch (err: any) {
                          alert(err.response?.data?.error || 'Failed to create user');
                        } finally { setIsAddingUser(false); }
                      }}
                    >
                      {isAddingUser ? <Loader2 className="animate-spin" /> : 'Create Account'}
                    </button>
                  </div>
                </div>
              </div>
            )}

          </div>
        );

      case 'notifications':
        return (
          <div style={{ animation: 'fadeUp 0.4s ease-out' }}>
            <h3 style={{ fontSize: '1.75rem', fontWeight: 900, marginBottom: '0.5rem', letterSpacing: '-0.03em' }}>Notification Preferences</h3>
            <p style={{ fontSize: '1rem', color: 'var(--text-secondary)', marginBottom: '3rem', fontWeight: 600 }}>Choose how you want to be notified. Changes are saved automatically.</p>
            <div style={{ borderRadius: '24px', overflow: 'hidden', border: '1px solid var(--border)' }}>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 120px 120px', padding: '1.25rem 2rem', background: 'var(--bg-deep)', borderBottom: '1px solid var(--border)' }}>
                <span style={{ fontSize: '0.75rem', fontWeight: 900, color: '#94a3b8', textTransform: 'uppercase', letterSpacing: '0.1em' }}>Notification</span>
                {['Push', 'Email'].map(h => <span key={h} style={{ fontSize: '0.75rem', fontWeight: 900, color: '#94a3b8', textAlign: 'center', textTransform: 'uppercase', letterSpacing: '0.1em' }}>{h}</span>)}
              </div>
              {([
                { key: 'newMessages', label: 'New messages', desc: 'Internal team communications' },
                { key: 'weeklyReport', label: 'Weekly report', desc: 'Performance summary each week' },
                { key: 'paymentSuccess', label: 'Payment success', desc: 'Confirmed transaction alerts' },
                { key: 'billingAlert', label: 'Billing alert', desc: 'Payment failures or issues' },
                { key: 'newInventory', label: 'Low inventory', desc: 'When stock falls below threshold' },
              ] as { key: keyof typeof prefs.notifications; label: string; desc: string }[]).map(({ key, label, desc }, i) => (
                <div key={key} style={{ display: 'grid', gridTemplateColumns: '1fr 120px 120px', alignItems: 'center', padding: '1.5rem 2rem', borderBottom: i < 4 ? '1px solid #f8fafc' : 'none', background: 'var(--bg-elevated)' }}>
                  <div>
                    <p style={{ fontSize: '1rem', fontWeight: 800, marginBottom: '2px' }}>{label}</p>
                    <p style={{ fontSize: '0.8rem', color: 'var(--text-muted)', fontWeight: 600 }}>{desc}</p>
                  </div>
                  {(['push', 'email'] as const).map(type => (
                    <div key={type} style={{ display: 'flex', justifyContent: 'center' }}>
                      <Toggle
                        checked={prefs.notifications[key][type]}
                        onChange={v => {
                          const updated = { ...prefs.notifications, [key]: { ...prefs.notifications[key], [type]: v } };
                          setPrefs(p => ({ ...p, notifications: updated }));
                          savePrefs({ notifications: updated });
                        }}
                      />
                    </div>
                  ))}
                </div>
              ))}
            </div>
          </div>
        );

      case 'appearance':
        return (
          <div style={{ animation: 'fadeUp 0.4s ease-out' }}>
            <h3 style={{ fontSize: '1.75rem', fontWeight: 900, marginBottom: '2.5rem', letterSpacing: '-0.03em' }}>Appearance & Vibe</h3>
            <div>
              <label style={labelStyle}>Color Theme</label>
              <div style={{ display: 'flex', gap: '1.5rem' }}>
                {[
                  { value: 'light', icon: Sun, label: 'Light', desc: 'Clean & bright workspace' },
                  { value: 'dark', icon: Moon, label: 'Dark', desc: 'Easier on the eyes at night' },
                ].map(({ value, icon: Icon, label, desc }) => (
                  <button
                    key={value}
                    onClick={() => {
                      const newTheme = value;
                      setPrefs(p => ({ ...p, theme: newTheme }));
                      savePrefs({ theme: newTheme });
                      localStorage.setItem('app_theme', newTheme);
                      if (newTheme === 'dark') {
                        document.documentElement.classList.add('dark');
                      } else {
                        document.documentElement.classList.remove('dark');
                      }
                    }}
                    style={{
                      flex: 1, padding: '2rem', borderRadius: '24px', cursor: 'pointer',
                      border: `2px solid ${prefs.theme === value ? 'var(--accent)' : 'var(--border)'}`,
                      background: prefs.theme === value ? 'var(--accent-soft)' : 'var(--bg-elevated)',
                      textAlign: 'left', display: 'flex', alignItems: 'center', gap: '1.25rem',
                      transition: 'all 0.2s ease'
                    }}
                  >
                    <div style={{ width: '56px', height: '56px', borderRadius: '16px', background: prefs.theme === value ? 'var(--accent)' : '#f1f5f9', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                      <Icon size={26} color={prefs.theme === value ? 'white' : '#64748b'} />
                    </div>
                    <div>
                      <p style={{ fontWeight: 900, fontSize: '1.1rem', marginBottom: '4px' }}>{label}</p>
                      <p style={{ fontSize: '0.85rem', color: 'var(--text-muted)', fontWeight: 600 }}>{desc}</p>
                    </div>
                  </button>
                ))}
              </div>
            </div>
            {saveMsg && <p style={{ marginTop: '1.5rem', fontWeight: 800, color: '#10b981', fontSize: '0.95rem' }}>{saveMsg}</p>}
          </div>
        );

      case 'checkout':
        return (
          <div style={{ animation: 'fadeUp 0.4s ease-out' }}>
            <h3 style={{ fontSize: '1.75rem', fontWeight: 900, marginBottom: '0.5rem', letterSpacing: '-0.03em' }}>POS Checkout Flow</h3>
            <p style={{ fontSize: '1rem', color: 'var(--text-secondary)', marginBottom: '3rem', fontWeight: 600 }}>Control which payment methods are available at the terminal.</p>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
              {[
                { key: 'enableCard', icon: CreditCard, label: 'Card Payment', desc: 'Visa, Mastercard, debit cards' },
                { key: 'enableCash', icon: Banknote, label: 'Cash', desc: 'Physical currency transactions' },
                { key: 'enableMpesa', icon: Phone, label: 'M-Pesa / Mobile Money', desc: 'Safaricom M-Pesa and mobile wallets' },
                { key: 'enableRoomCharge', icon: Building2, label: 'Room Charge', desc: 'Post charge to guest room account' },
              ].map(({ key, icon: Icon, label, desc }) => (
                <div key={key} style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '1.5rem 2rem', borderRadius: '24px', background: 'var(--bg-elevated)', border: '1px solid var(--border)' }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '1.5rem' }}>
                    <div style={{ width: '52px', height: '52px', borderRadius: '16px', background: 'var(--bg-deep)', border: '1px solid var(--border)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                      <Icon size={24} color="var(--accent)" />
                    </div>
                    <div>
                      <p style={{ fontWeight: 900, fontSize: '1rem', marginBottom: '2px' }}>{label}</p>
                      <p style={{ fontSize: '0.8rem', color: 'var(--text-muted)', fontWeight: 600 }}>{desc}</p>
                    </div>
                  </div>
                  <Toggle
                    checked={(prefs.checkout as any)[key]}
                    onChange={v => {
                      const updated = { ...prefs.checkout, [key]: v };
                      setPrefs(p => ({ ...p, checkout: updated }));
                      savePrefs({ checkout: updated });
                    }}
                  />
                </div>
              ))}
            </div>
            {saveMsg && <p style={{ marginTop: '1.5rem', fontWeight: 800, color: '#10b981', fontSize: '0.95rem' }}>{saveMsg}</p>}
          </div>
        );

      case 'mpesa':
        return (
          <div style={{ animation: 'fadeUp 0.4s ease-out' }}>
            <h3 style={{ fontSize: '1.75rem', fontWeight: 900, marginBottom: '0.5rem', letterSpacing: '-0.03em' }}>M-Pesa Integration</h3>
            <p style={{ color: 'var(--text-secondary)', fontWeight: 600, marginBottom: '2.5rem' }}>
              Configure your Safaricom Daraja API credentials to enable automated STK Push payments. Leave blank to use manual M-Pesa entry.
            </p>

            {/* Status Banner */}
            <div style={{ display: 'flex', alignItems: 'center', gap: '1rem', padding: '1.25rem 1.75rem', borderRadius: '20px', marginBottom: '2.5rem', background: mpesaConfigured ? 'rgba(16, 185, 129, 0.08)' : 'rgba(148, 163, 184, 0.08)', border: `1px solid ${mpesaConfigured ? '#10b981' : 'var(--border)'}` }}>
              {mpesaConfigured
                ? <CheckCircle2 size={24} color="#10b981" />
                : <AlertCircle size={24} color="#94a3b8" />}
              <div>
                <p style={{ fontWeight: 800, color: mpesaConfigured ? '#10b981' : 'var(--text-secondary)' }}>
                  {mpesaConfigured ? 'STK Push Active' : 'Manual Mode (No Credentials Set)'}
                </p>
                <p style={{ fontSize: '0.8rem', color: 'var(--text-muted)', fontWeight: 600 }}>
                  {mpesaConfigured
                    ? `Customers on shortcode ${mpesaConfig.mpesaShortcode} will receive an automatic payment prompt.`
                    : 'Cashiers will manually record the M-Pesa confirmation code after customers pay via their phones.'}
                </p>
              </div>
              {mpesaConfigured && (
                <button onClick={async () => { await api.patch(`/tenants/${user?.tenantId}/settings/mpesa`, { mpesaConsumerKey: null, mpesaConsumerSecret: null, mpesaShortcode: null, mpesaPasskey: null, mpesaTillDisplay: null }); setMpesaConfigured(false); setMpesaConfig({ mpesaConsumerKey: '', mpesaConsumerSecret: '', mpesaShortcode: '', mpesaPasskey: '', mpesaTillDisplay: '' }); }}
                  style={{ marginLeft: 'auto', background: '#fff1f2', color: '#f43f5e', border: 'none', borderRadius: '10px', padding: '8px 14px', fontWeight: 800, cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '6px' }}>
                  <XIcon size={14} /> Disconnect
                </button>
              )}
            </div>

            <div style={{ display: 'flex', flexDirection: 'column', gap: '1.75rem' }}>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1.25rem' }}>
                <div>
                  <label style={labelStyle}>Consumer Key</label>
                  <input type="password" className="form-input" style={{ height: '52px', borderRadius: '14px', fontWeight: 700, background: 'var(--bg-deep)', fontFamily: 'monospace' }} placeholder="Paste from Daraja portal" value={mpesaConfig.mpesaConsumerKey} onChange={e => setMpesaConfig(p => ({ ...p, mpesaConsumerKey: e.target.value }))} />
                </div>
                <div>
                  <label style={labelStyle}>Consumer Secret</label>
                  <input type="password" className="form-input" style={{ height: '52px', borderRadius: '14px', fontWeight: 700, background: 'var(--bg-deep)', fontFamily: 'monospace' }} placeholder="Paste from Daraja portal" value={mpesaConfig.mpesaConsumerSecret} onChange={e => setMpesaConfig(p => ({ ...p, mpesaConsumerSecret: e.target.value }))} />
                </div>
              </div>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1.25rem' }}>
                <div>
                  <label style={labelStyle}>Shortcode (Paybill/Till)</label>
                  <input type="text" className="form-input" style={{ height: '52px', borderRadius: '14px', fontWeight: 800, background: 'var(--bg-deep)' }} placeholder="e.g. 600000" value={mpesaConfig.mpesaShortcode} onChange={e => setMpesaConfig(p => ({ ...p, mpesaShortcode: e.target.value }))} />
                </div>
                <div>
                  <label style={labelStyle}>Customer-Facing Till Display</label>
                  <input type="text" className="form-input" style={{ height: '52px', borderRadius: '14px', fontWeight: 800, background: 'var(--bg-deep)' }} placeholder="e.g. 522522 or same as shortcode" value={mpesaConfig.mpesaTillDisplay} onChange={e => setMpesaConfig(p => ({ ...p, mpesaTillDisplay: e.target.value }))} />
                </div>
              </div>
              <div>
                <label style={labelStyle}>Lipa na M-Pesa Online Passkey</label>
                <input type="password" className="form-input" style={{ height: '52px', borderRadius: '14px', fontWeight: 700, background: 'var(--bg-deep)', fontFamily: 'monospace' }} placeholder="From Safaricom Business portal" value={mpesaConfig.mpesaPasskey} onChange={e => setMpesaConfig(p => ({ ...p, mpesaPasskey: e.target.value }))} />
              </div>
            </div>

            <div style={{ marginTop: '3rem', paddingTop: '2rem', borderTop: '1px solid var(--border)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <p style={{ fontSize: '0.8rem', color: 'var(--text-muted)', fontWeight: 600 }}>
                Credentials are stored encrypted. Keys are never returned after saving.
              </p>
              <div style={{ display: 'flex', alignItems: 'center', gap: '1.5rem' }}>
                {mpesaSaveMsg && <span style={{ fontWeight: 800, color: mpesaSaveMsg.includes('✓') ? '#10b981' : '#f43f5e' }}>{mpesaSaveMsg}</span>}
                <button
                  className="btn btn-primary" style={{ height: '52px', minWidth: '180px', borderRadius: '14px', fontWeight: 800 }}
                  disabled={isSavingMpesa}
                  onClick={async () => {
                    setIsSavingMpesa(true); setMpesaSaveMsg('');
                    try {
                      const res = await api.patch(`/tenants/${user?.tenantId}/settings/mpesa`, mpesaConfig);
                      setMpesaConfigured(res.data.isConfigured);
                      setMpesaSaveMsg('✓ Saved!');
                      // Clear secrets from state — they're saved in DB now
                      setMpesaConfig(p => ({ ...p, mpesaConsumerKey: '', mpesaConsumerSecret: '', mpesaPasskey: '' }));
                    } catch { setMpesaSaveMsg('Save failed'); }
                    finally { setIsSavingMpesa(false); setTimeout(() => setMpesaSaveMsg(''), 3000); }
                  }}
                >
                  {isSavingMpesa ? <Loader2 size={20} className="animate-spin" /> : 'Save Credentials'}
                </button>
              </div>
            </div>
          </div>
        );

      case 'security':
        return (
          <div style={{ animation: 'fadeUp 0.4s ease-out' }}>
            <h3 style={{ fontSize: '1.75rem', fontWeight: 900, marginBottom: '2.5rem', letterSpacing: '-0.03em' }}>Security & Vault</h3>
            <div style={{ background: '#fff7ed', border: '1px solid #ffedd5', borderRadius: '20px', padding: '1.5rem 2rem', display: 'flex', alignItems: 'flex-start', gap: '1.25rem', marginBottom: '3rem' }}>
              <Shield size={28} color="#f97316" style={{ flexShrink: 0 }} />
              <div>
                <p style={{ fontWeight: 900, fontSize: '1.05rem', color: '#9a3412' }}>Account Security Notice</p>
                <p style={{ fontSize: '0.9rem', color: '#c2410c', fontWeight: 600 }}>Review active sessions and ensure your account is only accessed from trusted devices.</p>
              </div>
            </div>
            <p style={{ fontWeight: 900, fontSize: '1.1rem', marginBottom: '1.5rem' }}>Active Sessions</p>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
              {sessions.map((s: any) => {
                const isMobile = s.deviceInfo?.toLowerCase().includes('mobile') || s.deviceInfo?.toLowerCase().includes('iphone') || s.deviceInfo?.toLowerCase().includes('android');
                return (
                  <div key={s.id} style={{ display: 'flex', alignItems: 'center', gap: '1.25rem', padding: '1.5rem', borderRadius: '20px', border: '1px solid var(--border)', background: 'var(--bg-elevated)', transition: 'all 0.2s', opacity: s.isActive === false ? 0.5 : 1 }}>
                    <div style={{ width: '52px', height: '52px', borderRadius: '16px', background: 'var(--bg-deep)', border: '1px solid var(--border)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                      {isMobile ? <Smartphone size={24} color="#64748b" /> : <Monitor size={24} color="#64748b" />}
                    </div>
                    <div style={{ flex: 1 }}>
                      <p style={{ fontWeight: 900, fontSize: '1rem', display: 'flex', alignItems: 'center', gap: '8px' }}>
                        {s.deviceInfo || 'Unknown Device'}
                        {s.isCurrent && <span style={{ fontSize: '0.7rem', background: '#ecfdf5', color: '#10b981', padding: '2px 8px', borderRadius: '12px', fontWeight: 800 }}>Current Session</span>}
                      </p>
                      <p style={{ fontSize: '0.85rem', fontWeight: 800, color: s.isCurrent ? '#10b981' : 'var(--text-muted)' }}>
                        {s.ipAddress || 'Unknown IP'} • Logged in: {new Date(s.createdAt).toLocaleString()}
                      </p>
                    </div>
                    {!s.isCurrent && (
                      <button 
                        onClick={async () => {
                          try {
                            await api.delete(`/tenants/${user?.tenantId}/users/me/sessions/${s.id}`);
                            setSessions(prev => prev.filter((p: any) => p.id !== s.id));
                          } catch (e) {
                            alert('Session revocation failed.');
                          }
                        }}
                        style={{ fontSize: '0.85rem', fontWeight: 800, color: '#f43f5e', background: '#fff1f2', border: 'none', borderRadius: '10px', padding: '6px 16px', cursor: 'pointer', transition: 'transform 0.1s' }}
                        onMouseEnter={e => e.currentTarget.style.transform = 'scale(1.05)'}
                        onMouseLeave={e => e.currentTarget.style.transform = 'scale(1)'}
                      >
                        Revoke
                      </button>
                    )}
                  </div>
                );
              })}
              {sessions.length === 0 && (
                <div style={{ padding: '2rem', textAlign: 'center', border: '1px dashed var(--border)', borderRadius: '20px' }}>
                  <p style={{ color: 'var(--text-muted)', fontWeight: 700 }}>No session tracking data found for this tenant.</p>
                </div>
              )}
            </div>
            <p style={{ fontSize: '0.85rem', color: 'var(--text-muted)', fontWeight: 600, marginTop: '1.5rem' }}>
              Signed in as <b>{user?.email}</b> · Role: <b style={{ textTransform: 'capitalize' }}>{user?.role?.replace('_', ' ')}</b>
            </p>
          </div>
        );

      case 'language':
        return (
          <div style={{ animation: 'fadeUp 0.4s ease-out' }}>
            <h3 style={{ fontSize: '1.75rem', fontWeight: 900, marginBottom: '2.5rem', letterSpacing: '-0.03em' }}>Region & Language</h3>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '2rem' }}>
              <div>
                <label style={labelStyle}>Language</label>
                <select
                  className="form-input"
                  style={{ height: '56px', borderRadius: '14px', fontWeight: 800, background: 'var(--bg-deep)', cursor: 'pointer' }}
                  value={prefs.language}
                  onChange={e => setPrefs(p => ({ ...p, language: e.target.value }))}
                >
                  {['English', 'Swahili', 'French', 'Arabic'].map(l => <option key={l}>{l}</option>)}
                </select>
              </div>
              <div>
                <label style={labelStyle}>Timezone</label>
                <select
                  className="form-input"
                  style={{ height: '56px', borderRadius: '14px', fontWeight: 800, background: 'var(--bg-deep)', cursor: 'pointer' }}
                  value={prefs.timezone}
                  onChange={e => setPrefs(p => ({ ...p, timezone: e.target.value }))}
                >
                  {['Africa/Nairobi', 'UTC', 'Africa/Lagos', 'Africa/Cairo', 'Europe/London', 'America/New_York'].map(tz => <option key={tz}>{tz}</option>)}
                </select>
              </div>
              <div>
                <label style={labelStyle}>Default Currency Display</label>
                <select
                  className="form-input"
                  style={{ height: '56px', borderRadius: '14px', fontWeight: 800, background: 'var(--bg-deep)', cursor: 'pointer' }}
                  value={prefs.currency}
                  onChange={e => setPrefs(p => ({ ...p, currency: e.target.value }))}
                >
                  {['KES', 'USD', 'EUR', 'GBP', 'TZS', 'UGX', 'ZAR'].map(c => <option key={c}>{c}</option>)}
                </select>
              </div>
            </div>
            <div style={{ display: 'flex', justifyContent: 'flex-end', alignItems: 'center', gap: '1.5rem', marginTop: '3rem', paddingTop: '2rem', borderTop: '1px solid var(--border)' }}>
              {saveMsg && <span style={{ fontSize: '0.95rem', fontWeight: 800, color: saveMsg === 'Saved!' ? '#10b981' : '#f43f5e' }}>{saveMsg}</span>}
              <button onClick={() => savePrefs({ language: prefs.language, timezone: prefs.timezone, currency: prefs.currency })} className="btn btn-primary" style={{ height: '56px', minWidth: '200px', borderRadius: '16px', fontSize: '1rem', fontWeight: 900 }}>
                {isSaving ? <Loader2 size={20} className="animate-spin" /> : 'Save Changes'}
              </button>
            </div>
          </div>
        );

      default:
        return null;
    }
  };

  return (
    <div style={{ paddingBottom: '3rem' }}>
      {/* Header */}
      <div style={{ marginBottom: '3rem' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '10px', color: 'var(--text-muted)', fontWeight: 700, fontSize: '0.9rem', marginBottom: '1rem' }}>
          <button onClick={() => window.history.back()} style={{ background: 'var(--bg-elevated)', border: '1px solid var(--border)', borderRadius: '8px', padding: '6px', cursor: 'pointer', display: 'flex' }}>
            <ArrowLeft size={16} />
          </button>
          <span>Settings</span>
          <ChevronRight size={14} />
          <span style={{ color: 'var(--text-primary)', fontWeight: 900 }}>{SECTIONS.find(s => s.id === activeSection)?.label}</span>
        </div>
        <h1 style={{ fontSize: '2.5rem', fontWeight: 900, letterSpacing: '-0.04em' }}>Settings</h1>
      </div>

      <div className="responsive-grid" style={{ gridTemplateColumns: undefined, alignItems: 'flex-start' }}>
        {/* Sidebar Nav */}
        <div style={{ 
          padding: '0.75rem', borderRadius: '28px', background: 'var(--bg-deep)', border: '1px solid var(--border)', 
          position: 'sticky', top: '1.5rem', display: 'flex', flexDirection: 'column', gap: '4px',
          overflowX: 'auto', scrollbarWidth: 'none'
        }} className="mobile-horizontal-scroll">
          {SECTIONS.map(({ id, label, icon: Icon }) => (
            <button
              key={id}
              onClick={() => setActiveSection(id)}
              style={{
                display: 'flex', alignItems: 'center', gap: '1rem',
                width: '100%', padding: '1rem 1.25rem', borderRadius: '18px',
                border: 'none', cursor: 'pointer', marginBottom: '4px',
                background: activeSection === id ? 'var(--accent)' : 'transparent',
                color: activeSection === id ? 'white' : '#64748b',
                fontWeight: 800, fontSize: '0.95rem',
                transition: 'all 0.25s ease',
              }}
            >
              <Icon size={20} color={activeSection === id ? 'white' : '#94a3b8'} />
              {label}
            </button>
          ))}
        </div>

        {/* Content Panel */}
        <div style={{ background: 'var(--bg-elevated)', border: '1px solid var(--border)', borderRadius: '36px', padding: '3.5rem', minHeight: '650px', boxShadow: '0 20px 60px rgba(0,0,0,0.03)' }}>
          {renderSection()}
        </div>
      </div>
    </div>
  );
};

export default Settings;

import React, { useState, useEffect, useCallback } from 'react';
import api from '../api';
import {
  Building2, Plus, CheckCircle2, XCircle,
  Loader2, Edit3, X, Save
} from 'lucide-react';
import { useAuth } from '../context/AuthContext';
import { useToast } from '../context/ToastContext';

interface Tenant {
  id: string;
  name: string;
  slug: string;
  currency: string;
  taxRate: number;
  isActive: boolean;
  createdAt: string;
  _count?: { users: number; orders: number };
}

const labelStyle: React.CSSProperties = {
  fontSize: '0.65rem', fontWeight: 700, textTransform: 'uppercase',
  letterSpacing: '0.06em', color: 'var(--text-secondary)', marginBottom: '0.4rem', display: 'block'
};

const SuperAdmin: React.FC = () => {
  const { user } = useAuth();
  const { showToast } = useToast();
  const [tenants, setTenants] = useState<Tenant[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedTenant, setSelectedTenant] = useState<Tenant | null>(null);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [showManageModal, setShowManageModal] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  const [newTenant, setNewTenant] = useState({ name: '', slug: '', currency: 'KES', taxRate: 16 });
  const [editData, setEditData] = useState<Partial<Tenant>>({});

  const fetchTenants = useCallback(async () => {
    try {
      const res = await api.get('/tenants');
      setTenants(res.data);
    } catch {
      showToast('Failed to load tenants', 'error');
    } finally {
      setLoading(false);
    }
  }, [showToast]);

  useEffect(() => {
    if (user?.role === 'super_admin') fetchTenants();
  }, [user, fetchTenants]);

  const handleCreate = async () => {
    if (!newTenant.name.trim() || !newTenant.slug.trim()) {
      showToast('Name and slug are required', 'error'); return;
    }
    setIsSaving(true);
    try {
      await api.post('/tenants', newTenant);
      showToast('Tenant registered successfully!', 'success');
      setShowCreateModal(false);
      setNewTenant({ name: '', slug: '', currency: 'KES', taxRate: 16 });
      fetchTenants();
    } catch (err) {
      const errorMsg = err && typeof err === 'object' && 'response' in err
        ? (err as Record<string, any>).response?.data?.error || 'Failed to create tenant'
        : 'Failed to create tenant';
      showToast(errorMsg, 'error');
    } finally { setIsSaving(false); }
  };

  const handleUpdate = async () => {
    if (!selectedTenant) return;
    setIsSaving(true);
    try {
      await api.patch(`/tenants/${selectedTenant.id}`, editData);
      showToast('Tenant updated!', 'success');
      setShowManageModal(false);
      fetchTenants();
    } catch {
      showToast('Failed to update tenant', 'error');
    } finally { setIsSaving(false); }
  };

  const handleToggleActive = async (tenant: Tenant) => {
    try {
      await api.patch(`/tenants/${tenant.id}`, { isActive: !tenant.isActive });
      showToast(`Tenant ${tenant.isActive ? 'disabled' : 'enabled'}`, 'success');
      fetchTenants();
    } catch {
      showToast('Failed to update tenant status', 'error');
    }
  };

  const openManage = (tenant: Tenant) => {
    setSelectedTenant(tenant);
    setEditData({ name: tenant.name, currency: tenant.currency, taxRate: tenant.taxRate });
    setShowManageModal(true);
  };

  if (loading) return (
    <div style={{ display: 'flex', height: '100%', alignItems: 'center', justifyContent: 'center' }}>
      <Loader2 className="animate-spin" size={48} style={{ color: 'var(--accent)' }} />
    </div>
  );

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem', paddingBottom: '2rem' }}>
      {/* Header */}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', flexWrap: 'wrap', gap: '1rem', paddingBottom: '1.25rem', borderBottom: '1px solid var(--border)' }}>
        <div>
          <h2 style={{ fontSize: '1.5rem', fontWeight: 800, display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
            <Building2 size={28} style={{ color: 'var(--accent)' }} /> System Tenants
          </h2>
          <p style={{ fontSize: '0.85rem', color: 'var(--text-secondary)', marginTop: '0.25rem' }}>
            Manage all hotels and restaurants registered on the platform.
          </p>
        </div>
        <button className="btn btn-primary" onClick={() => setShowCreateModal(true)} style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
          <Plus size={18} /> Register Tenant
        </button>
      </div>

      {/* Stats Bar */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '1rem' }}>
        {[
          { label: 'Total Tenants', value: tenants.length, icon: Building2, color: '#6366f1', bg: '#ede9fe' },
          { label: 'Active', value: tenants.filter(t => t.isActive).length, icon: CheckCircle2, color: '#10b981', bg: '#d1fae5' },
          { label: 'Inactive', value: tenants.filter(t => !t.isActive).length, icon: XCircle, color: '#f43f5e', bg: '#fce7f3' },
        ].map((s, i) => (
          <div key={i} className="card" style={{ padding: '1.25rem', display: 'flex', alignItems: 'center', gap: '1rem' }}>
            <div style={{ width: '2.5rem', height: '2.5rem', borderRadius: '10px', background: s.bg, display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
              <s.icon size={18} style={{ color: s.color }} />
            </div>
            <div>
              <p style={{ fontSize: '0.7rem', color: 'var(--text-secondary)', fontWeight: 700, textTransform: 'uppercase' }}>{s.label}</p>
              <p style={{ fontSize: '1.5rem', fontWeight: 800 }}>{s.value}</p>
            </div>
          </div>
        ))}
      </div>

      {/* Tenants Grid */}
      {tenants.length === 0 ? (
        <div className="card" style={{ padding: '3rem', textAlign: 'center', color: 'var(--text-secondary)' }}>
          <Building2 size={48} style={{ margin: '0 auto 1rem', opacity: 0.3 }} />
          <p style={{ fontWeight: 700, fontSize: '1rem' }}>No tenants registered yet</p>
          <p style={{ fontSize: '0.85rem', marginTop: '0.5rem' }}>Click "Register Tenant" to add the first hotel or restaurant.</p>
        </div>
      ) : (
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: '1rem' }}>
          {tenants.map(tenant => (
            <div key={tenant.id} className="card" style={{ padding: '1.5rem', cursor: 'pointer', transition: 'transform 0.15s ease', border: tenant.isActive ? '1px solid var(--border)' : '1px solid rgba(244,63,94,0.2)', opacity: tenant.isActive ? 1 : 0.7 }}
              onMouseEnter={e => (e.currentTarget.style.transform = 'translateY(-2px)')}
              onMouseLeave={e => (e.currentTarget.style.transform = 'translateY(0)')}
            >
              <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', marginBottom: '1rem' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
                  <div style={{ width: '2.5rem', height: '2.5rem', borderRadius: '10px', background: 'var(--accent-soft)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                    <Building2 size={18} style={{ color: 'var(--accent)' }} />
                  </div>
                  <div>
                    <p style={{ fontWeight: 800, fontSize: '0.95rem' }}>{tenant.name}</p>
                    <p style={{ fontSize: '0.7rem', color: 'var(--text-secondary)' }}>{tenant.slug}.servepoint.app</p>
                  </div>
                </div>
                <span style={{
                  padding: '0.2rem 0.6rem', borderRadius: '99px', fontSize: '0.6rem', fontWeight: 800, textTransform: 'uppercase',
                  background: tenant.isActive ? '#d1fae5' : '#fce7f3',
                  color: tenant.isActive ? '#059669' : '#f43f5e',
                  border: `1px solid ${tenant.isActive ? '#a7f3d0' : '#fecdd3'}`,
                }}>
                  {tenant.isActive ? 'Active' : 'Inactive'}
                </span>
              </div>

              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '0.5rem', padding: '0.875rem', background: 'var(--bg-elevated)', borderRadius: '8px', marginBottom: '1rem' }}>
                {[
                  { label: 'Currency', value: tenant.currency },
                  { label: 'Tax Rate', value: `${tenant.taxRate}%` },
                  { label: 'Users', value: tenant._count?.users ?? '–' },
                ].map(stat => (
                  <div key={stat.label} style={{ textAlign: 'center' }}>
                    <p style={{ fontSize: '0.6rem', color: 'var(--text-secondary)', fontWeight: 700, textTransform: 'uppercase', marginBottom: '0.2rem' }}>{stat.label}</p>
                    <p style={{ fontWeight: 800, fontSize: '0.9rem' }}>{stat.value}</p>
                  </div>
                ))}
              </div>

              <div style={{ display: 'flex', gap: '0.5rem' }}>
                <button
                  className="btn btn-secondary"
                  style={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.4rem', fontSize: '0.8rem', padding: '0.5rem' }}
                  onClick={() => openManage(tenant)}
                >
                  <Edit3 size={14} /> Manage
                </button>
                <button
                  onClick={() => handleToggleActive(tenant)}
                  style={{
                    padding: '0.5rem 0.75rem', borderRadius: 'var(--radius-sm)', border: '1px solid var(--border)',
                    background: 'transparent', cursor: 'pointer', fontSize: '0.75rem', fontWeight: 600,
                    color: tenant.isActive ? '#f43f5e' : '#10b981', fontFamily: "'Outfit', sans-serif"
                  }}
                >
                  {tenant.isActive ? 'Disable' : 'Enable'}
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Create Tenant Modal */}
      {showCreateModal && (
        <div style={{ position: 'fixed', inset: 0, zIndex: 200, display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'rgba(0,0,0,0.5)', backdropFilter: 'blur(4px)' }}>
          <div className="glass" style={{ width: '440px', padding: '1.75rem', borderRadius: '1.25rem' }}>
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '1.5rem' }}>
              <h3 style={{ fontSize: '1.1rem', fontWeight: 700, display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                <Building2 size={20} style={{ color: 'var(--accent)' }} /> Register New Tenant
              </h3>
              <button onClick={() => setShowCreateModal(false)} style={{ background: 'none', border: 'none', cursor: 'pointer', color: 'var(--text-secondary)' }}><X size={20} /></button>
            </div>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
              <div>
                <label style={labelStyle}>Hotel / Restaurant Name *</label>
                <input className="form-input" placeholder="e.g. Lakeside Grand Hotel" value={newTenant.name}
                  onChange={e => { setNewTenant(p => ({ ...p, name: e.target.value, slug: e.target.value.toLowerCase().replace(/\s+/g, '-').replace(/[^a-z0-9-]/g, '') })); }} />
              </div>
              <div>
                <label style={labelStyle}>URL Slug *</label>
                <input className="form-input" placeholder="e.g. lakeside-grand" value={newTenant.slug}
                  onChange={e => setNewTenant(p => ({ ...p, slug: e.target.value.toLowerCase().replace(/[^a-z0-9-]/g, '') }))} />
                <p style={{ fontSize: '0.7rem', color: 'var(--text-secondary)', marginTop: '0.3rem' }}>
                  {newTenant.slug || 'your-slug'}.servepoint.app
                </p>
              </div>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.75rem' }}>
                <div>
                  <label style={labelStyle}>Currency</label>
                  <input className="form-input" maxLength={3} value={newTenant.currency}
                    onChange={e => setNewTenant(p => ({ ...p, currency: e.target.value.toUpperCase() }))} />
                </div>
                <div>
                  <label style={labelStyle}>Tax Rate (%)</label>
                  <input type="number" className="form-input" value={newTenant.taxRate}
                    onChange={e => setNewTenant(p => ({ ...p, taxRate: Number(e.target.value) }))} />
                </div>
              </div>
              <div style={{ display: 'flex', gap: '0.75rem', marginTop: '0.5rem' }}>
                <button onClick={() => setShowCreateModal(false)} className="btn btn-secondary" style={{ flex: 1 }}>Cancel</button>
                <button onClick={handleCreate} className="btn btn-primary" style={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.5rem' }} disabled={isSaving}>
                  {isSaving ? <Loader2 size={16} className="animate-spin" /> : <><Plus size={16} /> Register</>}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Manage Modal */}
      {showManageModal && selectedTenant && (
        <div style={{ position: 'fixed', inset: 0, zIndex: 200, display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'rgba(0,0,0,0.5)', backdropFilter: 'blur(4px)' }}>
          <div className="glass" style={{ width: '440px', padding: '1.75rem', borderRadius: '1.25rem' }}>
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '1.5rem' }}>
              <h3 style={{ fontSize: '1.1rem', fontWeight: 700, display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                <Edit3 size={18} style={{ color: 'var(--accent)' }} /> Manage: {selectedTenant.name}
              </h3>
              <button onClick={() => setShowManageModal(false)} style={{ background: 'none', border: 'none', cursor: 'pointer', color: 'var(--text-secondary)' }}><X size={20} /></button>
            </div>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
              <div>
                <label style={labelStyle}>Hotel Name</label>
                <input className="form-input" value={(editData.name as string) || ''} onChange={e => setEditData(p => ({ ...p, name: e.target.value }))} />
              </div>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.75rem' }}>
                <div>
                  <label style={labelStyle}>Currency</label>
                  <input className="form-input" maxLength={3} value={(editData.currency as string) || ''} onChange={e => setEditData(p => ({ ...p, currency: e.target.value.toUpperCase() }))} />
                </div>
                <div>
                  <label style={labelStyle}>Tax Rate (%)</label>
                  <input type="number" className="form-input" value={(editData.taxRate as number) || 0} onChange={e => setEditData(p => ({ ...p, taxRate: Number(e.target.value) }))} />
                </div>
              </div>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.75rem', padding: '0.875rem', background: 'var(--bg-elevated)', borderRadius: '8px' }}>
                <div style={{ textAlign: 'center' }}>
                  <p style={{ fontSize: '0.65rem', color: 'var(--text-secondary)', fontWeight: 700, textTransform: 'uppercase' }}>Users</p>
                  <p style={{ fontWeight: 800, fontSize: '1.25rem' }}>{selectedTenant._count?.users ?? 0}</p>
                </div>
                <div style={{ textAlign: 'center' }}>
                  <p style={{ fontSize: '0.65rem', color: 'var(--text-secondary)', fontWeight: 700, textTransform: 'uppercase' }}>Orders</p>
                  <p style={{ fontWeight: 800, fontSize: '1.25rem' }}>{selectedTenant._count?.orders ?? 0}</p>
                </div>
              </div>
              <div style={{ display: 'flex', gap: '0.75rem', marginTop: '0.5rem' }}>
                <button onClick={() => setShowManageModal(false)} className="btn btn-secondary" style={{ flex: 1 }}>Cancel</button>
                <button onClick={handleUpdate} className="btn btn-primary" style={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.5rem' }} disabled={isSaving}>
                  {isSaving ? <Loader2 size={16} className="animate-spin" /> : <><Save size={16} /> Save Changes</>}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default SuperAdmin;
